
/* ===== MACROXEL CANONICAL SOURCE: electron-sql-adapter.js ===== */
(() => {
  'use strict';

  const api = window.electronSql;
  if (!api || !api.isElectron) return;

  window.__MACROXEL_ELECTRON__ = true;
  window.__MACROXEL_SQL__ = true;

  // Caché de lectura por tabla: evita transferir y parsear decenas de miles de
  // registros cada vez que se abre un módulo o se actualiza una gráfica.
  const STORE_CACHE = new Map();
  const STORE_LOADS = new Map();
  const STORE_ID_INDEX = new Map();
  const STORE_SECONDARY_INDEX = new Map();
  const STORE_CACHE_AT = new Map();
  const CORE_CACHE_STORES = new Set(['inventory', 'users', 'settings', 'medicos', 'cpm', 'conteo']);
  const HIGH_VOLUME_STORES = new Set(['salidas', 'entradas', 'antibioticos', 'movimientos', 'transferencias', 'pedidos']);
  const HIGH_VOLUME_CACHE_TTL_MS = 30000;
  const HIGH_VOLUME_CACHE_MAX_ROWS = 20000;
  let flushStorageWrites = () => Promise.resolve();
  const ACTIVE_WRITE_PROMISES = new Set();
  let durableFlushTimer = 0;

  function trackWrite(promise) {
    const tracked = Promise.resolve(promise);
    ACTIVE_WRITE_PROMISES.add(tracked);
    tracked.then(
      () => ACTIVE_WRITE_PROMISES.delete(tracked),
      () => ACTIVE_WRITE_PROMISES.delete(tracked)
    );
    return tracked;
  }

  function scheduleDurableFlush(delay = 450) {
    clearTimeout(durableFlushTimer);
    durableFlushTimer = setTimeout(() => {
      durableFlushTimer = 0;
      Promise.allSettled([...ACTIVE_WRITE_PROMISES])
        .then(() => flushStorageWrites())
        .then(() => api.flush())
        .catch(() => {});
    }, Math.max(50, Number(delay) || 450));
  }

  function clearSecondaryIndexes(name) {
    const prefix = `${String(name)}::`;
    for (const key of [...STORE_SECONDARY_INDEX.keys()]) {
      if (key.startsWith(prefix)) STORE_SECONDARY_INDEX.delete(key);
    }
  }

  function dropStoreCache(name) {
    STORE_CACHE.delete(name);
    STORE_LOADS.delete(name);
    STORE_ID_INDEX.delete(name);
    clearSecondaryIndexes(name);
    STORE_CACHE_AT.delete(name);
  }

  function cacheIsFresh(name) {
    if (!STORE_CACHE.has(name)) return false;
    if (CORE_CACHE_STORES.has(name)) return true;
    return Date.now() - Number(STORE_CACHE_AT.get(name) || 0) < HIGH_VOLUME_CACHE_TTL_MS;
  }

  async function cachedAll(store) {
    const name = String(store);
    if (cacheIsFresh(name)) return STORE_CACHE.get(name);
    if (STORE_CACHE.has(name)) dropStoreCache(name);
    if (STORE_LOADS.has(name)) return STORE_LOADS.get(name);
    const loading = api.all(name).then((rows) => {
      const list = Array.isArray(rows) ? rows : [];
      const shouldCache = CORE_CACHE_STORES.has(name) || !HIGH_VOLUME_STORES.has(name) || list.length <= HIGH_VOLUME_CACHE_MAX_ROWS;
      if (shouldCache) {
        STORE_CACHE.set(name, list);
        STORE_CACHE_AT.set(name, Date.now());
        const positions = new Map();
        list.forEach((row, index) => positions.set(Number(row && row._id), index));
        STORE_ID_INDEX.set(name, positions);
      } else {
        dropStoreCache(name);
      }
      STORE_LOADS.delete(name);
      return list;
    }).catch((error) => {
      STORE_LOADS.delete(name);
      throw error;
    });
    STORE_LOADS.set(name, loading);
    return loading;
  }

  function cachedGet(store, key) {
    const name = String(store);
    if (!cacheIsFresh(name)) { if (STORE_CACHE.has(name)) dropStoreCache(name); return undefined; }
    const list = STORE_CACHE.get(name);
    if (!list) return undefined;
    const id = Number(key);
    const position = STORE_ID_INDEX.get(name)?.get(id);
    return Number.isInteger(position) ? (list[position] || null) : null;
  }

  function cacheIndexValue(record, indexName) {
    if (!record) return '';
    if (indexName === 'clave_lote_cad') return [record.clave, record.lote, record.caducidad].map((v) => String(v ?? '').trim());
    const aliases = {
      clave: ['clave', 'CLAVE', 'csg'], codigo_barras: ['codigo_barras', 'codigoBarras', 'barcode', 'CODIGO_BARRAS'],
      fecha: ['fecha', 'date', 'createdAt', 'FECHA'], folio: ['folio', 'FOLIO', 'folio_doc', 'folioDoc'],
      usuario: ['usuario', 'user', 'username', 'USUARIO'], tipo_doc: ['tipo_doc', 'tipoDoc', 'tipo_documento', 'documento', 'TIPO_DOC'],
      cedula: ['cedula', 'cedula_medico', 'CEDULA'], _mx_op_id: ['_mxOpId', '_mx_op_id', 'op_id']
    };
    for (const key of aliases[indexName] || [indexName]) {
      if (record[key] !== undefined && record[key] !== null) return String(record[key]).trim();
    }
    return '';
  }

  function secondaryKey(value) {
    return Array.isArray(value)
      ? value.map((v) => String(v ?? '').trim()).join('\u001f')
      : String(value ?? '').trim();
  }

  function getSecondaryIndex(store, indexName, list) {
    const cacheKey = `${String(store)}::${String(indexName)}`;
    if (STORE_SECONDARY_INDEX.has(cacheKey)) return STORE_SECONDARY_INDEX.get(cacheKey);
    const map = new Map();
    for (const record of list || []) {
      const k = secondaryKey(cacheIndexValue(record, indexName));
      if (!map.has(k)) map.set(k, []);
      map.get(k).push(record);
    }
    STORE_SECONDARY_INDEX.set(cacheKey, map);
    return map;
  }

  function cachedIndexGet(store, indexName, key, all) {
    const name = String(store);
    if (!cacheIsFresh(name)) { if (STORE_CACHE.has(name)) dropStoreCache(name); return undefined; }
    const list = STORE_CACHE.get(name);
    if (!list) return undefined;
    const requested = key && typeof key === 'object' && Object.prototype.hasOwnProperty.call(key, '__mxOnly') ? key.__mxOnly : key;
    const index = getSecondaryIndex(name, indexName, list);
    const matches = index.get(secondaryKey(requested)) || [];
    return all ? matches.slice() : (matches[0] || null);
  }

  function applyCacheOperations(entries, results) {
    entries.forEach((entry, index) => {
      const op = entry && entry.operation;
      if (!op) return;
      const store = String(op.store || '');
      if (!STORE_CACHE.has(store)) return;
      clearSecondaryIndexes(store);
      const list = STORE_CACHE.get(store);
      STORE_CACHE_AT.set(store, Date.now());
      let positions = STORE_ID_INDEX.get(store);
      if (!positions) { positions = new Map(); STORE_ID_INDEX.set(store, positions); }
      if (op.type === 'clear') {
        STORE_CACHE.set(store, []);
        STORE_ID_INDEX.set(store, new Map());
        return;
      }
      if (op.type === 'delete') {
        const id = Number(op.key);
        const position = positions.get(id);
        if (Number.isInteger(position)) {
          list.splice(position, 1);
          positions.delete(id);
          for (let i = position; i < list.length; i += 1) positions.set(Number(list[i] && list[i]._id), i);
        }
        return;
      }
      if (op.type === 'put') {
        const id = Number(results && results[index]) || Number(op.value && op.value._id);
        const record = Object.assign({}, op.value || {}, { _id: id });
        const position = positions.get(id);
        if (Number.isInteger(position)) list[position] = record;
        else { positions.set(id, list.length); list.push(record); }
      }
    });
  }

  window.__mxClearSqlCache = (store) => {
    if (store) dropStoreCache(String(store));
    else { STORE_CACHE.clear(); STORE_LOADS.clear(); STORE_ID_INDEX.clear(); STORE_SECONDARY_INDEX.clear(); STORE_CACHE_AT.clear(); }
  };

  class NameList {
    constructor(items) { this._items = [...new Set(items.map(String))]; }
    contains(name) { return this._items.includes(String(name)); }
    item(index) { return this._items[index] ?? null; }
    get length() { return this._items.length; }
    [Symbol.iterator]() { return this._items[Symbol.iterator](); }
    toString() { return this._items.join(','); }
  }

  class SqlRequest {
    constructor(transaction = null) {
      this.transaction = transaction;
      this.result = undefined;
      this.error = null;
      this.onsuccess = null;
      this.onerror = null;
      this.onblocked = null;
      this.onupgradeneeded = null;
      this.readyState = 'pending';
    }
    _success(value) {
      this.result = value;
      this.readyState = 'done';
      if (typeof this.onsuccess === 'function') {
        try { this.onsuccess({ target: this, type: 'success' }); } catch (error) { console.error(error); }
      }
    }
    _fail(error) {
      this.error = error instanceof Error ? error : new Error(String(error || 'Error SQL'));
      this.readyState = 'done';
      if (typeof this.onerror === 'function') {
        try { this.onerror({ target: this, type: 'error', preventDefault() {}, stopPropagation() {} }); } catch (err) { console.error(err); }
      }
    }
  }

  class SqlTransaction {
    constructor(db, storeNames, mode = 'readonly') {
      this.db = db;
      this.mode = mode || 'readonly';
      this.storeNames = new NameList(Array.isArray(storeNames) ? storeNames : [storeNames]);
      this.oncomplete = null;
      this.onerror = null;
      this.onabort = null;
      this.error = null;
      this._pendingReads = 0;
      this._writeQueue = [];
      this._committing = false;
      this._completed = false;
      this._aborted = false;
      this._completeTimer = null;
      this._commitTimer = null;
    }

    objectStore(name) {
      const store = String(name);
      if (!this.storeNames.contains(store)) throw new Error(`La transacción no incluye ${store}.`);
      return new SqlObjectStore(this, store);
    }

    abort() {
      if (this._completed) return;
      this._aborted = true;
      this.error = new Error('Transacción cancelada.');
      this._writeQueue.length = 0;
      clearTimeout(this._commitTimer);
      clearTimeout(this._completeTimer);
      setTimeout(() => {
        if (typeof this.onabort === 'function') this.onabort({ target: this, type: 'abort' });
      }, 0);
    }

    _queueRead(promise, request) {
      this._pendingReads += 1;
      Promise.resolve(promise).then((value) => {
        request._success(value);
      }).catch((error) => {
        request._fail(error);
        this._fail(error);
      }).finally(() => {
        this._pendingReads = Math.max(0, this._pendingReads - 1);
        this._scheduleComplete();
      });
      return request;
    }

    _holdCursor() {
      this._pendingReads += 1;
    }

    _releaseCursor() {
      this._pendingReads = Math.max(0, this._pendingReads - 1);
      this._scheduleComplete();
    }

    _queueWrite(operation, request) {
      if (this.mode === 'readonly') {
        const error = new Error('La transacción es de solo lectura.');
        request._fail(error);
        this._fail(error);
        return request;
      }
      this._writeQueue.push({ operation, request });
      clearTimeout(this._commitTimer);
      this._commitTimer = setTimeout(() => this._commitWrites(), 0);
      return request;
    }

    async _commitWrites() {
      if (this._aborted || this._completed || this._committing || !this._writeQueue.length) {
        this._scheduleComplete();
        return;
      }
      this._committing = true;
      const batch = this._writeQueue.splice(0);
      try {
        const results = await trackWrite(api.transaction(batch.map((entry) => entry.operation)));
        const destructive = batch.some((entry) => ['clear','delete'].includes(String(entry?.operation?.type || '')));
        if(destructive){
          await flushStorageWrites();
          await api.flush();
        }else{
          scheduleDurableFlush();
        }
        applyCacheOperations(batch, results);
        batch.forEach((entry, index) => entry.request._success(results ? results[index] : undefined));
      } catch (error) {
        batch.forEach((entry) => entry.request._fail(error));
        this._fail(error);
      } finally {
        this._committing = false;
        if (this._writeQueue.length) {
          clearTimeout(this._commitTimer);
          this._commitTimer = setTimeout(() => this._commitWrites(), 0);
        }
        this._scheduleComplete();
      }
    }

    _fail(error) {
      if (this._completed || this._aborted) return;
      this.error = error instanceof Error ? error : new Error(String(error || 'Error de transacción'));
      setTimeout(() => {
        if (typeof this.onerror === 'function') this.onerror({ target: this, type: 'error' });
      }, 0);
    }

    _scheduleComplete() {
      clearTimeout(this._completeTimer);
      this._completeTimer = setTimeout(() => {
        if (this._completed || this._aborted || this._committing || this._pendingReads > 0 || this._writeQueue.length > 0) return;
        this._completed = true;
        if (typeof this.oncomplete === 'function') {
          try { this.oncomplete({ target: this, type: 'complete' }); } catch (error) { console.error(error); }
        }
      }, 0);
    }
  }

  const INDEXES = {
    inventory: ['clave_lote_cad', 'clave', 'codigo_barras'],
    entradas: ['_mx_op_id', 'fecha', 'clave', 'folio', 'usuario', 'tipo_doc'],
    salidas: ['_mx_op_id', 'fecha', 'clave', 'folio', 'usuario', 'tipo_doc'],
    antibioticos: ['_mx_op_id', 'fecha', 'clave', 'folio', 'usuario'],
    movimientos: ['_mx_op_id', 'fecha', 'clave', 'folio', 'usuario'],
    transferencias: ['_mx_op_id', 'fecha', 'clave', 'folio', 'usuario', 'tipo_doc'],
    pedidos: ['_mx_op_id', 'fecha', 'clave', 'folio', 'usuario', 'tipo_doc'],
    folios: ['_mx_op_id', 'fecha', 'clave', 'folio', 'usuario', 'tipo_doc'],
    medicos: ['cedula'],
    users: [], settings: [], cpm: [], conteo: [], kv: []
  };

  function unwrapKey(value) {
    return value && typeof value === 'object' && Object.prototype.hasOwnProperty.call(value, '__mxOnly')
      ? value.__mxOnly
      : value;
  }

  class SqlIndex {
    constructor(transaction, store, name) {
      this.transaction = transaction;
      this.objectStore = store;
      this.name = name;
      this.keyPath = name === 'clave_lote_cad' ? ['clave', 'lote', 'caducidad'] : name;
      this.unique = name === '_mx_op_id';
      this.multiEntry = false;
    }
    get(key) {
      const request = new SqlRequest(this.transaction);
      const cached = cachedIndexGet(this.objectStore.name, this.name, unwrapKey(key), false);
      return this.transaction._queueRead(cached !== undefined ? Promise.resolve(cached) : api.indexGet(this.objectStore.name, this.name, unwrapKey(key), false), request);
    }
    getAll(key) {
      const request = new SqlRequest(this.transaction);
      const cached = cachedIndexGet(this.objectStore.name, this.name, unwrapKey(key), true);
      return this.transaction._queueRead(cached !== undefined ? Promise.resolve(cached) : api.indexGet(this.objectStore.name, this.name, unwrapKey(key), true), request);
    }
  }

  class SqlCursorRequest extends SqlRequest {
    constructor(transaction, loader) {
      super(transaction);
      this._loader = loader;
      this._rows = [];
      this._position = 0;
      this._started = false;
      transaction._holdCursor();
      Promise.resolve(loader()).then((rows) => {
        this._rows = Array.isArray(rows) ? rows : [];
        setTimeout(() => this._emit(), 0);
      }).catch((error) => {
        this._fail(error);
        transaction._releaseCursor();
      });
    }
    _emit() {
      if (this.transaction._aborted) return;
      if (this._position >= this._rows.length) {
        this.result = null;
        this.readyState = 'done';
        if (typeof this.onsuccess === 'function') this.onsuccess({ target: this, type: 'success' });
        this.transaction._releaseCursor();
        return;
      }
      const row = this._rows[this._position++];
      const request = this;
      this.result = {
        key: row.key,
        primaryKey: row.key,
        value: row.value,
        continue() { setTimeout(() => request._emit(), 0); }
      };
      this.readyState = 'done';
      if (typeof this.onsuccess === 'function') this.onsuccess({ target: this, type: 'success' });
    }
  }

  class SqlObjectStore {
    constructor(transaction, name) {
      this.transaction = transaction;
      this.name = name;
      this.keyPath = name === 'kv' ? null : '_id';
      this.autoIncrement = name !== 'kv';
      this.indexNames = new NameList(INDEXES[name] || []);
    }
    getAll(query) {
      const request = new SqlRequest(this.transaction);
      if (query !== undefined && this.name !== 'kv') {
        return this.transaction._queueRead(api.get(this.name, unwrapKey(query)).then((row) => row ? [row] : []), request);
      }
      if (this.name === 'kv') {
        return this.transaction._queueRead(api.kvAll().then((rows) => rows.map((row) => row.value)), request);
      }
      return this.transaction._queueRead(cachedAll(this.name), request);
    }
    get(key) {
      const request = new SqlRequest(this.transaction);
      if (this.name === 'kv') {
        return this.transaction._queueRead(api.kvAll().then((rows) => {
          const found = rows.find((row) => String(row.key) === String(key));
          return found ? found.value : undefined;
        }), request);
      }
      const cached = cachedGet(this.name, unwrapKey(key));
      return this.transaction._queueRead(cached !== undefined ? Promise.resolve(cached) : api.get(this.name, unwrapKey(key)), request);
    }
    put(value, key) {
      const request = new SqlRequest(this.transaction);
      return this.transaction._queueWrite({ type: 'put', store: this.name, value, key }, request);
    }
    add(value, key) { return this.put(value, key); }
    delete(key) {
      const request = new SqlRequest(this.transaction);
      return this.transaction._queueWrite({ type: 'delete', store: this.name, key: unwrapKey(key) }, request);
    }
    clear() {
      const request = new SqlRequest(this.transaction);
      return this.transaction._queueWrite({ type: 'clear', store: this.name }, request);
    }
    count() {
      const request = new SqlRequest(this.transaction);
      const cached = cacheIsFresh(this.name) ? STORE_CACHE.get(this.name) : null;
      if (!cached && STORE_CACHE.has(this.name)) dropStoreCache(this.name);
      return this.transaction._queueRead(cached ? Promise.resolve(cached.length) : api.count(this.name), request);
    }
    index(name) {
      if (!this.indexNames.contains(name)) throw new Error(`Índice inexistente: ${name}`);
      return new SqlIndex(this.transaction, this, String(name));
    }
    createIndex(name) {
      if (!this.indexNames.contains(name)) INDEXES[this.name] = [...(INDEXES[this.name] || []), String(name)];
      this.indexNames = new NameList(INDEXES[this.name] || []);
      return new SqlIndex(this.transaction, this, String(name));
    }
    openCursor() {
      if (this.name === 'kv') return new SqlCursorRequest(this.transaction, () => api.kvAll());
      return new SqlCursorRequest(this.transaction, async () => {
        const rows = await cachedAll(this.name);
        return rows.map((value) => ({ key: value._id, value }));
      });
    }
  }

  class SqlDatabase {
    constructor() {
      this.name = 'macroxel_hospitales_sqlite';
      this.version = Number(api.meta && api.meta.indexedDbVersion) || 100;
      this.objectStoreNames = new NameList((api.meta && api.meta.stores) || Object.keys(INDEXES));
      this.onversionchange = null;
      this.__mxSqlite = true;
      this.__mxLocalFallback = false;
    }
    transaction(storeNames, mode = 'readonly') { return new SqlTransaction(this, storeNames, mode); }
    createObjectStore(name) {
      if (!this.objectStoreNames.contains(name)) {
        this.objectStoreNames = new NameList([...this.objectStoreNames, String(name)]);
      }
      const tx = new SqlTransaction(this, [name], 'versionchange');
      return new SqlObjectStore(tx, String(name));
    }
    deleteObjectStore() {}
    close() { api.flush().catch(() => {}); }
  }

  const sqlDatabase = new SqlDatabase();
  const indexedDbPolyfill = {
    open() {
      const request = new SqlRequest(null);
      setTimeout(() => request._success(sqlDatabase), 0);
      return request;
    },
    deleteDatabase() {
      const request = new SqlRequest(null);
      STORE_CACHE.clear(); STORE_LOADS.clear(); STORE_ID_INDEX.clear(); STORE_CACHE_AT.clear();
      api.clearAll().then(() => request._success(undefined)).catch((error) => request._fail(error));
      return request;
    },
    databases() { return Promise.resolve([{ name: sqlDatabase.name, version: sqlDatabase.version }]); },
    cmp(a, b) { return a === b ? 0 : (a < b ? -1 : 1); }
  };

  try {
    Object.defineProperty(window, 'indexedDB', { value: indexedDbPolyfill, configurable: true, enumerable: true });
  } catch (_) {
    try { window.indexedDB = indexedDbPolyfill; } catch (error) { console.error('[SQL] No se pudo instalar el adaptador IndexedDB:', error); }
  }

  const keyRange = {
    only(value) { return { __mxOnly: value }; },
    lowerBound(value, open = false) { return { lower: value, lowerOpen: !!open }; },
    upperBound(value, open = false) { return { upper: value, upperOpen: !!open }; },
    bound(lower, upper, lowerOpen = false, upperOpen = false) { return { lower, upper, lowerOpen: !!lowerOpen, upperOpen: !!upperOpen }; }
  };
  try { Object.defineProperty(window, 'IDBKeyRange', { value: keyRange, configurable: true }); } catch (_) { window.IDBKeyRange = keyRange; }

  // Migra y replica localStorage en SQLite para que la licencia, permisos y configuración
  // sobrevivan actualizaciones y reinstalaciones sin depender del archivo HTML.
  try {
    const nativeSet = Storage.prototype.setItem;
    const nativeRemove = Storage.prototype.removeItem;
    const nativeClear = Storage.prototype.clear;
    let pendingStorage = {};
    let storageFlushTimer = 0;
    const queueStorageWrite = (key, value) => {
      pendingStorage[String(key)] = String(value);
      clearTimeout(storageFlushTimer);
      storageFlushTimer = setTimeout(() => {
        const batch = pendingStorage;
        pendingStorage = {};
        api.storageBulk(batch).catch(() => {});
      }, 120);
    };
    flushStorageWrites = () => {
      clearTimeout(storageFlushTimer);
      if (!Object.keys(pendingStorage).length) return Promise.resolve();
      const batch = pendingStorage;
      pendingStorage = {};
      return api.storageBulk(batch).catch(() => {});
    };
    const existing = {};
    for (let i = 0; i < localStorage.length; i += 1) {
      const key = localStorage.key(i);
      if (key != null) existing[key] = localStorage.getItem(key);
    }
    const sqlSnapshot = api.storageSnapshot || {};
    // El almacenamiento local del renderer es el más reciente cuando la app
    // se cerró mientras todavía había colas pendientes. No permitimos que una
    // instantánea SQL anterior borre esas operaciones al volver a abrir.
    const merged = Object.assign({}, sqlSnapshot, existing);
    for (const [key, value] of Object.entries(merged)) nativeSet.call(localStorage, key, String(value));

    const deviceKey = 'macroxel_hps_device_id';
    const savedDevice = String(localStorage.getItem(deviceKey) || '').trim().toUpperCase();
    if (!savedDevice.startsWith('MACROXEL-HPS-') && api.deviceId) {
      nativeSet.call(localStorage, deviceKey, api.deviceId);
      existing[deviceKey] = api.deviceId;
    }

    // Antes se reenviaba todo localStorage a SQLite en cada arranque. Con respaldos
    // y configuraciones grandes esa clonación bloqueaba el renderer. Solo replica
    // las claves locales realmente nuevas o modificadas y lo hace en segundo plano.
    const initialDelta = {};
    for (const [key, value] of Object.entries(existing)) {
      if (String(sqlSnapshot[key] ?? '') !== String(value ?? '')) initialDelta[key] = String(value ?? '');
    }
    if (Object.keys(initialDelta).length) {
      setTimeout(() => api.storageBulk(initialDelta).catch(() => {}), 1400);
    }

    Storage.prototype.setItem = function patchedSetItem(key, value) {
      const result = nativeSet.call(this, key, value);
      if (this === localStorage) queueStorageWrite(key, value);
      return result;
    };
    Storage.prototype.removeItem = function patchedRemoveItem(key) {
      const result = nativeRemove.call(this, key);
      if (this === localStorage) {
        delete pendingStorage[String(key)];
        api.storageRemove(String(key)).catch(() => {});
      }
      return result;
    };
    Storage.prototype.clear = function patchedClear() {
      const result = nativeClear.call(this);
      if (this === localStorage) {
        pendingStorage = {};
        clearTimeout(storageFlushTimer);
        api.storageClear().catch(() => {});
      }
      return result;
    };
  } catch (error) {
    console.warn('[SQL] No se pudo replicar localStorage:', error);
  }

  window.__mxWarmSqlStores = (stores) => {
    const requested = Array.isArray(stores) && stores.length ? stores : ['inventory', 'medicos'];
    return Promise.allSettled(requested.map((store) => cachedAll(store)));
  };

  window.__mxFlushSqlWrites = async () => {
    clearTimeout(durableFlushTimer);
    durableFlushTimer = 0;
    // Puede entrar una segunda escritura mientras esperamos la primera.
    // Repetimos hasta que la cola quede realmente vacía.
    for (let pass = 0; pass < 5; pass += 1) {
      const pending = [...ACTIVE_WRITE_PROMISES];
      if (!pending.length) break;
      await Promise.allSettled(pending);
    }
    await flushStorageWrites();
    await api.flush();
    return true;
  };

  if (typeof api.onPrepareClose === 'function') {
    api.onPrepareClose(async (token) => {
      let ok = true;
      let detail = '';
      try {
        if (typeof window.__mxPersistAllNow === 'function') await window.__mxPersistAllNow();
        else await window.__mxFlushSqlWrites();
      } catch (error) {
        ok = false;
        detail = error && error.message ? error.message : String(error || 'Error de persistencia');
        try { await window.__mxFlushSqlWrites(); } catch (_) {}
      } finally {
        try { api.closeReady(token, { ok, detail }); } catch (_) {}
      }
    });
  }

  document.addEventListener('DOMContentLoaded', () => {
    document.documentElement.dataset.macroxelStorage = 'sqlite-native';
    const originalTitle = document.title || 'Sistema de Inventarios Macroxel Hospitales';
    document.title = `${originalTitle.replace(/(?:\s*·\s*)?v\d+\.\d+\.\d+$/i,'').trim()} · v1.0.203`;
    const warmCore = () => {
      // Solo usuarios y configuración antes del acceso. Inventario y médicos se
      // precargan después de mostrar el menú para mantener el login inmediato.
      Promise.allSettled(['settings', 'users'].map((store) => cachedAll(store))).catch(() => {});
    };
    if (typeof requestIdleCallback === 'function') requestIdleCallback(warmCore, { timeout: 1200 });
    else setTimeout(warmCore, 350);
  }, { once: true });

  const flushCriticalNow = () => {
    try { return window.__mxFlushSqlWrites(); } catch (_) { return Promise.resolve(false); }
  };
  window.addEventListener('beforeunload', flushCriticalNow);
  window.addEventListener('pagehide', flushCriticalNow);
  // v1.0.150: cambiar de ventana no fuerza un FLUSH completo de SQLite.
  // Ese flush podía bloquear la interfaz al volver al sistema con tablas grandes.
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') flushCriticalNow();
  });
  console.info('[MACROXEL] Almacenamiento principal: SQLite nativo con WAL', api.meta);
})();


/* ===== MACROXEL CANONICAL SOURCE: inline ===== */
function mxNormTxt(v){
  return (v==null?'':String(v)).trim().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/\s+/g,' ');
}
function mxInvSort(a,b){
  const da = mxNormTxt(a.descripcion ?? a.nombre ?? '');
  const db = mxNormTxt(b.descripcion ?? b.nombre ?? '');
  if(da < db) return -1;
  if(da > db) return 1;
  const ca = mxNormTxt(a.clave ?? a.codigo ?? '');
  const cb = mxNormTxt(b.clave ?? b.codigo ?? '');
  if(ca < cb) return -1;
  if(ca > cb) return 1;
  const la = mxNormTxt(a.lote ?? '');
  const lb = mxNormTxt(b.lote ?? '');
  if(la < lb) return -1;
  if(la > lb) return 1;
  const cadA = mxNormTxt(a.caducidad ?? a.cad ?? '');
  const cadB = mxNormTxt(b.caducidad ?? b.cad ?? '');
  if(cadA < cadB) return -1;
  if(cadA > cadB) return 1;
  return 0;
}
function mxSortInventarioInPlace(arr){
  try{ arr.sort(mxInvSort); }catch(e){}
  return arr;
}

function mxNormDesc(v){
  return (v==null?'':String(v))
    .trim()
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/\s+/g,' ');
}

function mxClaveUnica(v){
  return String(v ?? '')
    .trim()
    .replace(/\s+/g,'')
    .replace(/\.0+$/,'')
    .toUpperCase();
}

function mxSortInvByDescripcion(arr){
  try{
    arr.sort((a,b)=>{
      const da = mxNormDesc(a.descripcion ?? a.DESCRIPCION ?? '');
      const db = mxNormDesc(b.descripcion ?? b.DESCRIPCION ?? '');
      if(da < db) return -1;
      if(da > db) return 1;
      return 0;
    });
  }catch(e){}
  return arr;
}


