/* Orden FEFO en salidas: para recomendaciones de caducidad solo se consideran lotes con existencia real > 0.
   Evita alertas cuando el lote más próximo a caducar ya quedó en cero. */
function mxSalExistenciaReal(it){
  try{
    if(!it) return 0;
    const n = (v)=>{ const x = Number(String(v ?? '').replace(/,/g,'').trim()); return Number.isFinite(x) ? x : 0; };
    const keysLoc = ['almacen','ALMACEN','existenciaAlmacen','existencia almacen','existencia_almacen','alm','estantes','ESTANTES','existenciaEstante','existencia estante','existencia_estante','est'];
    const hasLoc = keysLoc.some(k => Object.prototype.hasOwnProperty.call(it,k) && it[k] !== '' && it[k] != null);
    if(hasLoc){
      const alm = n(it.almacen ?? it.ALMACEN ?? it.existenciaAlmacen ?? it['existencia almacen'] ?? it.existencia_almacen ?? it.alm ?? 0);
      const est = n(it.estantes ?? it.ESTANTES ?? it.existenciaEstante ?? it['existencia estante'] ?? it.existencia_estante ?? it.est ?? 0);
      return (typeof mxWarehouseModeEnabled==='function' && mxWarehouseModeEnabled()) ? est : (alm + est);
    }
    if(typeof mxWarehouseModeEnabled==='function' && mxWarehouseModeEnabled()) return 0;
    const vals = [it.existencias, it.existencia, it['EXISTENCIA'], it['Existencia'], it['existencias por lote'], it.existencia_por_lote, it.exis, it.pzs];
    for(const v of vals){ if(v !== undefined && v !== null && v !== '') return n(v); }
    if(typeof pickExistencia === 'function') return n(pickExistencia(it));
  }catch(e){}
  return 0;
}
function mxSalTieneExistencia(it){ return mxSalExistenciaReal(it) > 0; }

