function mxTempMarkFired(slotISO){
  try{ localStorage.setItem(mxTempLastKey, slotISO); }catch(e){}
}
function mxTempLastFired(){
  try{ return localStorage.getItem(mxTempLastKey) || ''; }catch(e){ return ''; }
}

function mxSnooze(minutes){
  const until = Date.now() + minutes*60*1000;
  try{ localStorage.setItem(mxTempSnoozeKey, String(until)); }catch(e){}
}
function mxSnoozed(){
  try{
    const v = parseInt(localStorage.getItem(mxTempSnoozeKey)||'0',10);
    return v && Date.now() < v;
  }catch(e){ return false; }
}

function mxCheckTempReminder(){
  if(mxSnoozed()) return;
  const now = new Date();
  const times = mxGetTempTimes();
  const today = mxTodayISO();
  const last = mxTempLastFired();

  for(const tt of times){
    const [hh,mm] = tt.split(':').map(x=>parseInt(x,10));
    const slot = new Date(now.getFullYear(), now.getMonth(), now.getDate(), hh, mm, 0, 0);
    const diff = now - slot;
    if(diff >= 0 && diff <= 150000){
      const slotISO = today + ' ' + tt;
      if(last !== slotISO){
        mxTempMarkFired(slotISO);
        mxBeep();
        setTimeout(mxSpeakTemp, 120);
        mxShowTempCard('⏰ Es hora de la toma de temperatura (' + (tt==='00:00'?'24:00':tt) + ').');
      }
      break;
    }
  }
}

function mxInitTempReminderUI(){
  const btnOk = document.getElementById('btnTempListo');
  const btnSn = document.getElementById('btnTempPosponer');
  if(btnOk) btnOk.addEventListener('click', () => { mxHideTempCard(); });
  if(btnSn) btnSn.addEventListener('click', () => { mxSnooze(10); mxHideTempCard(); });

  const t1 = document.getElementById('tempHora1');
  const t2 = document.getElementById('tempHora2');
  const t3 = document.getElementById('tempHora3');
  const t4 = document.getElementById('tempHora4');
  const info = document.getElementById('tempHorasInfo');
  const save = document.getElementById('btnGuardarTempHoras');
  const test = document.getElementById('btnProbarTempAlerta');

  function syncToInputs(){
    const times = mxGetTempTimes();
    if(t1) t1.value = times[0] || '';
    if(t2) t2.value = times[1] || '';
    if(t3) t3.value = times[2] || '';
    if(t4) t4.value = times[3] || '';
    if(info) info.textContent = 'Guardado: ' + mxFormatTimesForUI(times);
  }

  if(save) save.addEventListener('click', () => {
    const inTimes = [t1?.value, t2?.value, t3?.value, t4?.value];
    const out = mxSetTempTimes(inTimes);
    if(info) info.textContent = 'Guardado: ' + mxFormatTimesForUI(out);
    mxBeep();
    setTimeout(mxSpeakTemp, 120);
  });

  if(test) test.addEventListener('click', () => {
    mxBeep();
    setTimeout(mxSpeakTemp, 120);
    mxShowTempCard('🔔 Prueba: Toma de temperatura.');
  });

  syncToInputs();
}

