function mxApplyIndexedDbSchema(dbObj, tx){
  const stores = ['inventory','salidas','entradas','antibioticos','users','settings','movimientos','transferencias','medicos','cpm','conteo','pedidos'];
  stores.forEach(name => {
    if(!dbObj.objectStoreNames.contains(name)) dbObj.createObjectStore(name,{keyPath:'_id',autoIncrement:true});
  });
  if(!dbObj.objectStoreNames.contains('kv')) dbObj.createObjectStore('kv');
  const ensureIndex=(storeName,indexName,keyPath,options={unique:false})=>{
    try{
      const st=tx.objectStore(storeName);
      if(!st.indexNames.contains(indexName)) st.createIndex(indexName,keyPath,options);
    }catch(_err){}
  };
  ensureIndex('inventory','clave_lote_cad',['clave','lote','caducidad']);
  ensureIndex('inventory','clave','clave');
  ensureIndex('inventory','codigo_barras','codigo_barras');
  ['entradas','salidas','antibioticos','movimientos','transferencias','pedidos'].forEach(storeName=>{
    ensureIndex(storeName,'_mx_op_id','_mxOpId',{unique:true});
    ensureIndex(storeName,'fecha','fecha');
    ensureIndex(storeName,'clave','clave');
    ensureIndex(storeName,'folio','folio');
    ensureIndex(storeName,'usuario','usuario');
  });
  ensureIndex('salidas','tipo_doc','tipo_doc');
  ensureIndex('entradas','tipo_doc','tipo_doc');
  ensureIndex('medicos','cedula','cedula');
}
function mxAttachIndexedDbConnection(conn){
  db=conn;
  try{
    db.onversionchange=function(){
      try{db.close();}catch(_e){}
      db=null;
      __mxDbOpenPromise=null;
    };
  }catch(_e){}
  return db;
}
function idbOpen(){
  if(db) return Promise.resolve(db);
  if(__mxDbOpenPromise) return __mxDbOpenPromise;
  __mxDbOpenPromise=new Promise((resolve,reject)=>{
    const fail=err=>{__mxDbOpenPromise=null;reject(err||new Error('No se pudo abrir la base de datos.'));};
    const finish=conn=>resolve(mxAttachIndexedDbConnection(conn));
    const upgradeToTarget=current=>{
      try{current&&current.close();}catch(_e){}
      let req;
      try{req=indexedDB.open(DB_NAME,DB_VER);}catch(err){fail(err);return;}
      req.onupgradeneeded=ev=>mxApplyIndexedDbSchema(req.result,ev.target.transaction);
      req.onsuccess=()=>finish(req.result);
      req.onerror=()=>fail(req.error);
      req.onblocked=()=>fail(new Error('La base de datos está bloqueada por otra pestaña. Cierra otras copias del sistema y vuelve a intentarlo.'));
    };
    let probe;
    try{
      // Abrir sin número de versión evita el error cuando el equipo ya tiene una versión superior.
      probe=indexedDB.open(DB_NAME);
    }catch(err){fail(err);return;}
    probe.onupgradeneeded=ev=>mxApplyIndexedDbSchema(probe.result,ev.target.transaction);
    probe.onsuccess=()=>{
      const current=probe.result;
      if(Number(current.version||0)<Number(DB_VER||1)) upgradeToTarget(current);
      else finish(current);
    };
    probe.onerror=()=>fail(probe.error);
    probe.onblocked=()=>fail(new Error('La base de datos está bloqueada por otra pestaña. Cierra otras copias del sistema y vuelve a intentarlo.'));
  });
  return __mxDbOpenPromise;
}
function idbAll(s){return new Promise((res,rej)=>{if(!db) return rej('DB'); const tx=db.transaction(s,'readonly'),st=tx.objectStore(s); const rq=st.getAll(); rq.onsuccess=()=>res(rq.result); rq.onerror=()=>rej(rq.error);});}
function idbPut(s,o){if(s==='movimientos' && !(o && Number(o._mxAnomalia)===1)) return Promise.resolve(null); return new Promise((res,rej)=>{if(!db) return rej('DB'); const tx=db.transaction(s,'readwrite'),st=tx.objectStore(s); const rq=st.put(o); rq.onsuccess=()=>res(rq.result); rq.onerror=()=>rej(rq.error);});}

(function(){
  if(window.__mxIdbCommitPatchInstalled) return;
  window.__mxIdbCommitPatchInstalled = true;

  function wrapWriteWithCommit(kind){
    const original = window[kind];
    if(typeof original !== 'function') return;

    window[kind] = function(storeName, payload){
      if(window.__mxUseLsDb) return original.apply(this, arguments);
      return new Promise((resolve, reject)=>{
        try{
          if(!db) return reject('DB');
          const tx = db.transaction(storeName, 'readwrite');
          const st = tx.objectStore(storeName);
          let request;
          if(kind === 'idbPut') request = st.put(payload);
          else if(kind === 'idbDelete') request = st.delete(payload);
          else if(kind === 'idbClear') request = st.clear();
          else return resolve(original.apply(this, arguments));

          let reqResult = true;
          if(request){
            request.onsuccess = ()=>{ try{ reqResult = request.result; }catch(_e){} };
            request.onerror = ()=> reject(request.error);
          }
          tx.oncomplete = ()=> resolve(reqResult);
          tx.onerror = ()=> reject(tx.error || (request && request.error) || new Error('IDB write error'));
          tx.onabort = ()=> reject(tx.error || (request && request.error) || new Error('IDB transaction aborted'));
        }catch(err){
          reject(err);
        }
      }).catch(err => {
        try{ mxEnableLsdb(err && (err.message || err.name || err)); }catch(_e){}
        return original.apply(this, arguments);
      });
    };
  }

  wrapWriteWithCommit('idbPut');
  wrapWriteWithCommit('idbDelete');
  wrapWriteWithCommit('idbClear');
})();
function idbBulkPut(s,a){if(s==='movimientos') a=(a||[]).filter(o=>o&&Number(o._mxAnomalia)===1); return new Promise((res,rej)=>{if(!db) return rej('DB'); const tx=db.transaction(s,'readwrite'),st=tx.objectStore(s); (a||[]).forEach(o=>{if('_id'in o) delete o._id; st.put(o);}); tx.oncomplete=()=>res(true); tx.onerror=()=>rej(tx.error);});}
function idbClear(s){return new Promise((res,rej)=>{if(!db) return rej('DB'); const tx=db.transaction(s,'readwrite'),st=tx.objectStore(s); const rq=st.clear(); rq.onsuccess=()=>res(true); rq.onerror=()=>rej(rq.error);});}

function idbDelete(s,id){return new Promise((res,rej)=>{if(!db) return rej('DB'); const tx=db.transaction(s,'readwrite'),st=tx.objectStore(s); const rq=st.delete(id); rq.onsuccess=()=>res(true); rq.onerror=()=>rej(rq.error);});}

/* MX local fallback DB for file:// and blocked IndexedDB environments */
(function(){
  const MX_LSDB_FLAG = '__mx_lsdb_enabled_v1';
  const MX_LSDB_PREFIX = '__mx_lsdb_store_v1__';
  const MX_LSDB_META = '__mx_lsdb_meta_v1';

  function mxLsdbClone(v){
    try{ return JSON.parse(JSON.stringify(v)); }catch(e){ return v; }
  }
  function mxLsdbReadStore(name){
    try{
      const raw = localStorage.getItem(MX_LSDB_PREFIX + name);
      const arr = raw ? JSON.parse(raw) : [];
      return Array.isArray(arr) ? arr : [];
    }catch(e){ return []; }
  }
  function mxLsdbWriteStore(name, arr){
    localStorage.setItem(MX_LSDB_PREFIX + name, JSON.stringify(Array.isArray(arr) ? arr : []));
  }
  function mxLsdbReadMeta(){
    try{
      const raw = localStorage.getItem(MX_LSDB_META);
      const meta = raw ? JSON.parse(raw) : {};
      return meta && typeof meta === 'object' ? meta : {};
    }catch(e){ return {}; }
  }
  function mxLsdbWriteMeta(meta){
    localStorage.setItem(MX_LSDB_META, JSON.stringify(meta && typeof meta === 'object' ? meta : {}));
  }
  function mxLsdbNextId(store){
    const meta = mxLsdbReadMeta();
    const next = Number((meta[store] || 0)) + 1;
    meta[store] = next;
    mxLsdbWriteMeta(meta);
    return next;
  }
  function mxLsdbNormalize(store, obj){
    const o = mxLsdbClone(obj || {});
    if(o._id == null || o._id === '') o._id = mxLsdbNextId(store);
    return o;
  }
  function mxLsdbGetAll(store){
    return mxLsdbReadStore(store).map(mxLsdbClone);
  }
  function mxLsdbPut(store, obj){
    const arr = mxLsdbReadStore(store);
    const row = mxLsdbNormalize(store, obj);
    const idx = arr.findIndex(x => String(x && x._id) === String(row._id));
    if(idx >= 0) arr[idx] = row; else arr.push(row);
    mxLsdbWriteStore(store, arr);
    return row._id;
  }
  function mxLsdbClear(store){
    mxLsdbWriteStore(store, []);
    return true;
  }
  function mxLsdbDelete(store, id){
    const arr = mxLsdbReadStore(store).filter(x => String(x && x._id) !== String(id));
    mxLsdbWriteStore(store, arr);
    return true;
  }
  function mxMakeReq(executor){
    const req = { onsuccess:null, onerror:null, result:undefined, error:null };
    setTimeout(function(){
      try{
        req.result = executor();
        if(typeof req.onsuccess === 'function') req.onsuccess({ target:req });
      }catch(err){
        req.error = err;
        if(typeof req.onerror === 'function') req.onerror({ target:req });
      }
    }, 0);
    return req;
  }
  function mxCreateFakeDb(){
    return {
      __mxLocalFallback: true,
      close(){},
      transaction(store){
        return {
          objectStore(name){
            const s = name || store;
            return {
              getAll(){ return mxMakeReq(() => mxLsdbGetAll(s)); },
              put(obj){ return mxMakeReq(() => mxLsdbPut(s, obj)); },
              clear(){ return mxMakeReq(() => mxLsdbClear(s)); },
              delete(id){ return mxMakeReq(() => mxLsdbDelete(s, id)); }
            };
          }
        };
      }
    };
  }
  function mxEnableLsdb(reason){
    try{
      window.__mxUseLsDb = true;
      localStorage.setItem(MX_LSDB_FLAG, '1');
      db = mxCreateFakeDb();
      window.db = db;
      console.warn('[MX] Activando base local de respaldo', reason || '');
      return db;
    }catch(err){
      console.error('[MX] No se pudo activar la base local de respaldo', err);
      throw err;
    }
  }

  const _origIdbOpen = idbOpen;
  idbOpen = function(){
    try{
      if(window.__mxUseLsDb) return Promise.resolve(db || mxEnableLsdb('already-enabled'));
      if(!window.indexedDB) return Promise.resolve(mxEnableLsdb('indexedDB-missing'));
    }catch(e){}
    return new Promise((resolve, reject) => {
      try{
        const p = _origIdbOpen();
        Promise.resolve(p).then(resolve).catch(err => {
          try{
            resolve(mxEnableLsdb(err && (err.message || err.name || err)));
          }catch(fallbackErr){
            reject(fallbackErr);
          }
        });
      }catch(err){
        try{
          resolve(mxEnableLsdb(err && (err.message || err.name || err)));
        }catch(fallbackErr){
          reject(fallbackErr);
        }
      }
    });
  };

  idbAll = function(s){
    if(window.__mxUseLsDb) return Promise.resolve(mxLsdbGetAll(s));
    return new Promise((res,rej)=>{
      if(!db) return rej('DB');
      const tx=db.transaction(s,'readonly'),st=tx.objectStore(s); const rq=st.getAll();
      rq.onsuccess=()=>res(rq.result); rq.onerror=()=>rej(rq.error);
    }).catch(err => {
      if(window.__mxUseLsDb) return mxLsdbGetAll(s);
      throw err;
    });
  };
  idbPut = function(s,o){
    if(window.__mxUseLsDb) return Promise.resolve(mxLsdbPut(s,o));
    return new Promise((res,rej)=>{
      if(!db) return rej('DB');
      const tx=db.transaction(s,'readwrite'),st=tx.objectStore(s); const rq=st.put(o);
      rq.onsuccess=()=>res(rq.result); rq.onerror=()=>rej(rq.error);
    }).catch(err => {
      mxEnableLsdb(err && (err.message || err.name || err));
      return mxLsdbPut(s,o);
    });
  };
  idbBulkPut = function(s,a){
    if(window.__mxUseLsDb){
      (Array.isArray(a)?a:[]).forEach(o => { if(o && '_id' in o && (o._id==null || o._id==='')) delete o._id; mxLsdbPut(s,o); });
      return Promise.resolve(true);
    }
    return new Promise((res,rej)=>{
      if(!db) return rej('DB');
      const tx=db.transaction(s,'readwrite'),st=tx.objectStore(s);
      (Array.isArray(a)?a:[]).forEach(o=>{ if(o && '_id'in o && (o._id==null || o._id==='')) delete o._id; st.put(o); });
      tx.oncomplete=()=>res(true); tx.onerror=()=>rej(tx.error);
    }).catch(err => {
      mxEnableLsdb(err && (err.message || err.name || err));
      (Array.isArray(a)?a:[]).forEach(o => mxLsdbPut(s,o));
      return true;
    });
  };
  idbClear = function(s){
    if(window.__mxUseLsDb) return Promise.resolve(mxLsdbClear(s));
    return new Promise((res,rej)=>{
      if(!db) return rej('DB');
      const tx=db.transaction(s,'readwrite'),st=tx.objectStore(s); const rq=st.clear();
      rq.onsuccess=()=>res(true); rq.onerror=()=>rej(rq.error);
    }).catch(err => {
      mxEnableLsdb(err && (err.message || err.name || err));
      return mxLsdbClear(s);
    });
  };
  idbDelete = function(s,id){
    if(window.__mxUseLsDb) return Promise.resolve(mxLsdbDelete(s,id));
    return new Promise((res,rej)=>{
      if(!db) return rej('DB');
      const tx=db.transaction(s,'readwrite'),st=tx.objectStore(s); const rq=st.delete(id);
      rq.onsuccess=()=>res(true); rq.onerror=()=>rej(rq.error);
    }).catch(err => {
      mxEnableLsdb(err && (err.message || err.name || err));
      return mxLsdbDelete(s,id);
    });
  };

  window.__mxMigrateLocalFallbackToIndexedDb = async function(){
    try{
      if(!window.indexedDB || !db || db.__mxLocalFallback || window.__mxUseLsDb) return false;
      if(window.__mxLsdbMigrating) return false;

      const stores = ['inventory','salidas','entradas','antibioticos','users','settings','movimientos','transferencias','medicos','cpm','conteo','pedidos'];
      const hasLocalRows = stores.some(function(s){ return mxLsdbReadStore(s).length > 0; });
      if(!hasLocalRows) return false;

      window.__mxLsdbMigrating = true;
      let copied = 0;

      async function realGetAll(store){
        return new Promise(function(resolve){
          try{
            const tx = db.transaction(store, 'readonly');
            const st = tx.objectStore(store);
            const rq = st.getAll();
            rq.onsuccess = function(){ resolve(Array.isArray(rq.result) ? rq.result : []); };
            rq.onerror = function(){ resolve([]); };
          }catch(e){ resolve([]); }
        });
      }
      async function realPutMany(store, rows, preserveId){
        if(!Array.isArray(rows) || !rows.length) return 0;
        return new Promise(function(resolve){
          let n = 0;
          try{
            const tx = db.transaction(store, 'readwrite');
            const st = tx.objectStore(store);
            rows.forEach(function(row){
              try{
                const r = mxLsdbClone(row || {});
                if(!preserveId && r && Object.prototype.hasOwnProperty.call(r, '_id')){
                  r.__mxMigratedFromLsdbId = r._id;
                  delete r._id;
                }
                st.put(r);
                n++;
              }catch(_e){}
            });
            tx.oncomplete = function(){ resolve(n); };
            tx.onerror = function(){ resolve(n); };
            tx.onabort = function(){ resolve(n); };
          }catch(e){ resolve(n); }
        });
      }

      for(const s of stores){
        const localRows = mxLsdbReadStore(s);
        if(!localRows.length) continue;
        const existing = await realGetAll(s);
        if(existing.length === 0){
          copied += await realPutMany(s, localRows, true);
        }else{
          const existingIds = new Set(existing.map(function(x){ return String(x && x._id); }));
          const rowsToAdd = localRows.filter(function(x){ return !existingIds.has(String(x && x._id)); });
          copied += await realPutMany(s, rowsToAdd, false);
        }
      }

      if(copied > 0){
        try{ localStorage.setItem('__mx_lsdb_migrated_to_idb_v1', new Date().toISOString()); }catch(_e){}
        console.warn('[MX] Datos de respaldo local migrados a IndexedDB:', copied);
      }
      return copied > 0;
    }catch(e){
      console.warn('[MX] No se pudo migrar respaldo local a IndexedDB', e);
      return false;
    }finally{
      window.__mxLsdbMigrating = false;
    }
  };

})();

/* MX CORE ESTABLE 48.1 — persistencia confirmada, reemplazos con rollback y activación protegida */
/* MACROXEL 106 — todas las alertas, confirmaciones y capturas usan modales internos compatibles con Node/Electron. */
(function(){
  if(window.__mxCoreStable481Installed) return;
  window.__mxCoreStable481Installed = true;

  const clone = (v)=>{ try{ return structuredClone(v); }catch(_e){ try{return JSON.parse(JSON.stringify(v));}catch(_e2){return v;} } };
  const oldPut = window.idbPut;
  const oldBulk = window.idbBulkPut;
  const oldClear = window.idbClear;
  const oldDelete = window.idbDelete;

  function realTxWrite(storeName, mode, runner){
    return new Promise((resolve,reject)=>{
      try{
        if(!db) return reject(new Error('DB no disponible'));
        const tx = db.transaction(storeName, mode);
        const st = tx.objectStore(storeName);
        let result = true;
        runner(st, tx, v=>{ result=v; });
        tx.oncomplete = ()=>resolve(result);
        tx.onerror = ()=>reject(tx.error || new Error('Error de transacción IndexedDB'));
        tx.onabort = ()=>reject(tx.error || new Error('Transacción IndexedDB cancelada'));
      }catch(err){ reject(err); }
    });
  }

  function canUseLocalFallback(err){
    const name=String(err && err.name || '');
    const msg=String(err && (err.message||err) || '');
    return ['InvalidStateError','UnknownError','QuotaExceededError','SecurityError','VersionError'].includes(name)
      || /DB no disponible|database is closed|connection is closing/i.test(msg);
  }

  window.idbPut = async function(storeName, payload){
    if(window.__mxUseLsDb || (db && db.__mxLocalFallback)) return oldPut.apply(this, arguments);
    try{
      return await realTxWrite(storeName,'readwrite',(st,tx,setResult)=>{
        const rq=st.put(clone(payload));
        rq.onsuccess=()=>setResult(rq.result);
        rq.onerror=()=>{ try{tx.abort();}catch(_e){} };
      });
    }catch(err){
      if(canUseLocalFallback(err)) return oldPut.apply(this, arguments);
      throw err;
    }
  };

  window.idbBulkPut = async function(storeName, rows){
    const arr = Array.isArray(rows) ? rows : [];
    if(!arr.length) return true;
    if(window.__mxUseLsDb || (db && db.__mxLocalFallback)) return oldBulk.call(this, storeName, arr);
    try{
      return await realTxWrite(storeName,'readwrite',(st,tx)=>{
        for(const source of arr){
          const row=clone(source || {});
          if(row && Object.prototype.hasOwnProperty.call(row,'_id') && (row._id===null || row._id==='')) delete row._id;
          const rq=st.put(row);
          rq.onerror=()=>{ try{tx.abort();}catch(_e){} };
        }
      });
    }catch(err){
      if(canUseLocalFallback(err)) return oldBulk.call(this, storeName, arr);
      throw err;
    }
  };

  window.idbClear = async function(storeName){
    if(window.__mxUseLsDb || (db && db.__mxLocalFallback)) return oldClear.apply(this, arguments);
    try{
      return await realTxWrite(storeName,'readwrite',(st,tx)=>{
        const rq=st.clear(); rq.onerror=()=>{ try{tx.abort();}catch(_e){} };
      });
    }catch(err){ if(canUseLocalFallback(err)) return oldClear.apply(this, arguments); throw err; }
  };

  window.idbDelete = async function(storeName, id){
    if(window.__mxUseLsDb || (db && db.__mxLocalFallback)) return oldDelete.apply(this, arguments);
    try{
      return await realTxWrite(storeName,'readwrite',(st,tx)=>{
        const rq=st.delete(id); rq.onerror=()=>{ try{tx.abort();}catch(_e){} };
      });
    }catch(err){ if(canUseLocalFallback(err)) return oldDelete.apply(this, arguments); throw err; }
  };

  window.mxIdbDeleteMany = async function(storeName, ids){
    const clean=(Array.isArray(ids)?ids:[]).filter(v=>v!==null && v!==undefined && v!=='');
    if(!clean.length) return 0;
    if(window.__mxUseLsDb || (db && db.__mxLocalFallback)){
      let n=0; for(const id of clean){ await window.idbDelete(storeName,id); n++; } return n;
    }
    return await realTxWrite(storeName,'readwrite',(st,tx,setResult)=>{
      let n=0;
      for(const id of clean){ const rq=st.delete(id); rq.onsuccess=()=>{n++;setResult(n)}; rq.onerror=()=>{try{tx.abort()}catch(_e){}}; }
    });
  };

  window.mxStoreExists = function(storeName){
    try{ return !!(db && db.objectStoreNames && db.objectStoreNames.contains(storeName)); }catch(_e){ return false; }
  };

  window.mxIdbAllWithKeys = async function(storeName){
    if(String(storeName)!=='kv' || window.__mxUseLsDb || (db && db.__mxLocalFallback)) return await window.idbAll(storeName);
    return await new Promise((resolve,reject)=>{
      try{
        const tx=db.transaction(storeName,'readonly');
        const st=tx.objectStore(storeName);
        const out=[];
        const rq=st.openCursor();
        rq.onsuccess=()=>{ const cur=rq.result; if(!cur) return; out.push({__mxKey:clone(cur.key),value:clone(cur.value)}); cur.continue(); };
        rq.onerror=()=>reject(rq.error);
        tx.oncomplete=()=>resolve(out);
        tx.onerror=()=>reject(tx.error||rq.error);
      }catch(err){ reject(err); }
    });
  };

  async function replaceOneStore(storeName, rows){
    const next=Array.isArray(rows)?rows:[];
    if(String(storeName)!=='kv'){
      await window.idbClear(storeName);
      if(next.length) await window.idbBulkPut(storeName,next);
      return;
    }
    // kv usa claves externas; los respaldos nuevos conservan {__mxKey,value}.
    const keyed=next.filter(x=>x && typeof x==='object' && Object.prototype.hasOwnProperty.call(x,'__mxKey'));
    // Respaldo antiguo: no guardaba las claves de kv. Se conserva kv actual para no perder configuración.
    if(next.length && !keyed.length){ console.warn('[MX] Respaldo antiguo sin claves KV; se conserva la configuración local actual.'); return; }
    await window.idbClear('kv');
    if(!keyed.length) return;
    if(window.__mxUseLsDb || (db && db.__mxLocalFallback)) return; // la configuración importante también vive en localStorage
    await realTxWrite('kv','readwrite',(st,tx)=>{
      for(const item of keyed){ const rq=st.put(clone(item.value),clone(item.__mxKey)); rq.onerror=()=>{try{tx.abort()}catch(_e){}}; }
    });
  }

  window.mxReplaceStoreSafely = async function(storeName, rows){
    const next=Array.isArray(rows)?rows:[];
    if(typeof ensureDBReady==='function') await ensureDBReady(); else if(typeof idbOpen==='function') await idbOpen();
    if(!window.__mxUseLsDb && !window.mxStoreExists(storeName)) throw new Error('Módulo no disponible: '+storeName);
    const previous=await window.mxIdbAllWithKeys(storeName);
    try{
      await replaceOneStore(storeName,next);
      return {ok:true,count:next.length};
    }catch(err){
      try{ await replaceOneStore(storeName,previous); }catch(rollbackErr){ console.error('[MX] Falló rollback',storeName,rollbackErr); }
      throw err;
    }
  };

  window.mxReplaceStoresSafely = async function(dataByStore){
    if(typeof ensureDBReady==='function') await ensureDBReady(); else if(typeof idbOpen==='function') await idbOpen();
    const entries=Object.entries(dataByStore||{}).filter(([name,rows])=>Array.isArray(rows) && (window.__mxUseLsDb || window.mxStoreExists(name)));
    if(!entries.length) throw new Error('El respaldo no contiene módulos compatibles.');
    const previous={};
    for(const [name] of entries) previous[name]=await window.mxIdbAllWithKeys(name);
    try{
      for(const [name,rows] of entries) await replaceOneStore(name,rows);
      return {ok:true,stores:entries.map(([n])=>n)};
    }catch(err){
      for(const [name] of entries){
        try{ await replaceOneStore(name,previous[name]); }
        catch(rollbackErr){ console.error('[MX] Falló rollback de respaldo',name,rollbackErr); }
      }
      throw err;
    }
  };

  window.mxActivationKeys = [
    'macroxel_hps_license','macroxel_hps_device_id',
    'macroxel_inventarios_license','macroxel_inventarios_device_id',
    'macroxel_license','macroxel_device_id','deviceId','mx_install_id_v1',
    'mx_remote_db_url_v1'
  ];
  window.mxCaptureActivation = function(){
    const out={};
    for(const k of window.mxActivationKeys){ try{ const v=localStorage.getItem(k); if(v!=null) out[k]=v; }catch(_e){} }
    return out;
  };
  window.mxRestoreActivation = function(saved){
    for(const [k,v] of Object.entries(saved||{})){ try{ localStorage.setItem(k,String(v)); }catch(_e){} }
    try{
      const curLic=localStorage.getItem('macroxel_hps_license');
      const legacyLic=localStorage.getItem('macroxel_inventarios_license') || localStorage.getItem('macroxel_license');
      if(!curLic && legacyLic){
        try{
          const parsed=JSON.parse(legacyLic);
          if(parsed && String(parsed.appCode||'').toUpperCase()==='MACROXEL-HPS') localStorage.setItem('macroxel_hps_license',legacyLic);
        }catch(_e2){}
      }
      // El ID antiguo MACROXEL-INVENTARIOS no se reutiliza: HPS genera su propio ID estable.
    }catch(_e){}
  };
  window.mxClearTransientPersistence = function(){
    try{
      const remove=[];
      for(let i=0;i<localStorage.length;i++){
        const k=localStorage.key(i)||'';
        if(k.startsWith('mx_wal_v1_') || ['__mx_pendingEntradas_v1','__mx_pendingSalidas_v1','__mx_pendingAntib_v1','__mx_auto_backup_running_v1','__mx_auto_backup_running_v2'].includes(k)) remove.push(k);
      }
      remove.forEach(k=>localStorage.removeItem(k));
    }catch(_e){}
    try{ if(typeof __pendingEntradas!=='undefined') __pendingEntradas.length=0; }catch(_e){}
    try{ if(typeof __pendingSalidas!=='undefined') __pendingSalidas.length=0; }catch(_e){}
    try{ if(typeof __pendingAntib!=='undefined') __pendingAntib.length=0; }catch(_e){}
    try{ window.__pendingEntradas=(typeof __pendingEntradas!=='undefined')?__pendingEntradas:[]; }catch(_e){}
    try{ window.__pendingSalidas=(typeof __pendingSalidas!=='undefined')?__pendingSalidas:[]; }catch(_e){}
    try{ window.__pendingAntib=(typeof __pendingAntib!=='undefined')?__pendingAntib:[]; }catch(_e){}
  };
  window.mxNormalizeBackupPack = function(pack){
    if(!pack || typeof pack!=='object') throw new Error('Archivo de respaldo inválido.');
    const source=(pack.stores && typeof pack.stores==='object') ? pack.stores : pack;
    const allowed=['inventory','salidas','entradas','antibioticos','users','settings','movimientos','transferencias','medicos','cpm','conteo','pedidos','kv'];
    const stores={};
    for(const name of allowed){ if(Array.isArray(source[name])) stores[name]=source[name]; }
    const required=['inventory','salidas','entradas','antibioticos'];
    const present=required.filter(name=>Array.isArray(stores[name]));
    if(present.length<3) throw new Error('El archivo no contiene los módulos principales de un respaldo completo.');
    return {
      stores,
      localStorage:(pack.localStorage && typeof pack.localStorage==='object') ? pack.localStorage : ((pack.__localStorage && typeof pack.__localStorage==='object') ? pack.__localStorage : {}),
      sessionStorage:(pack.sessionStorage && typeof pack.sessionStorage==='object') ? pack.sessionStorage : ((pack.__sessionStorage && typeof pack.__sessionStorage==='object') ? pack.__sessionStorage : {})
    };
  };
})();

async function exportProximosCaducarToExcel(opts={}){
  const filename = opts.filename || ("PROXIMOS_CADUCAR_" + _fileSafeTS() + ".xlsx");
  try{
    if (typeof XLSX === "undefined"){
      mxAlert("No se encontró la librería XLSX. Revisa conexión al CDN.");
      return false;
    }
    await ensureDBReady?.();
    const inventario = await idbAll('inventory').catch(()=>[]);
    if(!inventario || !inventario.length){
      mxAlert("No hay inventario para exportar.");
      return false;
    }

    const hoy = new Date();
    const cadMaxEl = document.getElementById('cadMax');
    let cadMax = parseInt((cadMaxEl && cadMaxEl.value) || localStorage.getItem('dashCadMax') || '30', 10);
    if (!Number.isFinite(cadMax) || cadMax < 1) cadMax = 30;
    cadMax = Math.min(200, cadMax);

    const cad = inventario
      .map(i => {
        const d = parseFechaFlexible(i.caducidad);
        if (!d) return null;
        const dias = Math.ceil((d - hoy) / (1000 * 3600 * 24));
        if (dias < 0 || dias > 90) return null;
        return {
          id   : (i && (i._id!=null)) ? i._id : null,
          clave: i.clave || '',
          descripcion: i.descripcion || i.nombre || '',
          unidad: i.unidad || '',
          lote: i.lote || '',
          caducidad: i.caducidad || '',
          dias_restantes: dias,
          entradas: Number(i.entradas || 0),
          salidas: Number(i.salidas || 0),
          existencia: Number(i.existencia || 0),
          clasificacion: i.clasificacion || '',
          restriccion: i.restriccion || ''
        };
      })
      .filter(Boolean)
      .sort((a,b)=>a.dias_restantes - b.dias_restantes)
      .slice(0, cadMax);

    if(!cad.length){
      mxAlert("No hay productos próximos a caducar (≤ 90 días) para exportar.");
      return false;
    }

    const rows = cad.map(r=>({
      "Clave": r.clave,
      "Descripción": r.descripcion,
      "Unidad": r.unidad,
      "Lote": r.lote,
      "Caducidad": r.caducidad,
      "Días restantes": r.dias_restantes,
      "Entradas": r.entradas,
      "Salidas": r.salidas,
      "Existencia": r.existencia,
      "Clasificación": r.clasificacion,
      "Restricción": r.restriccion
    }));

    const ws = XLSX.utils.json_to_sheet(rows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "ProxCaducar");
    XLSX.writeFile(wb, filename);
    return true;
  }catch(err){
    console.error("Error exportProximosCaducarToExcel:", err);
    mxAlert("No se pudo exportar a Excel. Revisa la consola.");
    return false;
  }
}

async function exportTopSalidasToExcel(opts={}){
  const filename = opts.filename || ("TOP_SALIDAS_" + _fileSafeTS() + ".xlsx");
  try{
    if (typeof XLSX === "undefined"){
      mxAlert("No se encontró la librería XLSX. Revisa conexión al CDN.");
      return false;
    }
    await ensureDBReady?.();

    const salidas = await idbAll('salidas').catch(()=>[]);
    if(!Array.isArray(salidas) || !salidas.length){
      mxAlert('No hay historial de salidas para exportar.');
      return false;
    }

    const map = new Map();
    for(const s of salidas){
      const clave = (s && s.clave!=null) ? String(s.clave).trim() : '';
      if(!clave) continue;
      const pzs = Number(s.pzs || s.piezas || 0) || 0;
      if(pzs === 0) continue;
      const desc = String(s.descripcion || s.producto || s.nombre || '').trim();
      const cur = map.get(clave) || { clave, descripcion: desc, salidas: 0 };
      cur.salidas += pzs;
      if(!cur.descripcion && desc) cur.descripcion = desc;
      map.set(clave, cur);
    }

    const top = Array.from(map.values())
      .sort((a,b)=> (b.salidas||0) - (a.salidas||0))
      .slice(0, 30);

    if(!top.length){
      mxAlert('No hay salidas acumuladas para exportar.');
      return false;
    }

    const rows = top.map((r, i)=>({
      "#": i+1,
      "Clave": r.clave,
      "Descripción": r.descripcion || '',
      "Salidas (pzs)": Math.round((r.salidas||0)*1000)/1000
    }));

    const ws = XLSX.utils.json_to_sheet(rows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "TopSalidas");
    XLSX.writeFile(wb, filename);
    return true;
  }catch(err){
    console.error('Error exportTopSalidasToExcel:', err);
    mxAlert('No se pudo exportar Top Salidas a Excel. Revisa la consola.');
    return false;
  }
}
async function exportAntibioticosMasMovimientoToExcel(opts={}){
  const filename = opts.filename || ("ANTIBIOTICOS_MAS_MOVIMIENTO_" + _fileSafeTS() + ".xlsx");
  try{
    if (typeof XLSX === "undefined"){
      mxAlert("No se encontró la librería XLSX. Revisa conexión al CDN.");
      return false;
    }

    await ensureDBReady?.();

    const mesPick = (document.getElementById('consMesPick')?.value || '').trim(); // YYYY-MM
    const mesObjetivo = mesPick || (new Date().toLocaleString().slice(0,7));

    const inv = await idbAll('inventory').catch(()=>[]);
    const metaByClave = {};
    (inv||[]).forEach(i=>{
      const clave = mxClaveUnica(i.clave ?? i.codigo ?? i.Clave ?? i.Codigo ?? i.sku ?? '');
      if(!clave) return;
      if(!metaByClave[clave]) metaByClave[clave] = {};
      const desc = String(i.descripcion ?? i.Descripción ?? i.nombre ?? i.producto ?? '').trim();
      const clas = String(i.clasificacion ?? i.clasificación ?? i.departamento ?? i.depto ?? '').trim();
      const uni  = String(i.unidad ?? i.um ?? i.UM ?? '').trim();
      if(desc) metaByClave[clave].descripcion = desc;
      if(clas) metaByClave[clave].clasificacion = clas;
      if(uni)  metaByClave[clave].unidad = uni;
    });

    const isAntibiotico = (s)=>{
      const clave = String(s.clave||'').trim();
      const tipo = (s.tipoDoc||s.tipo||s.documento||'').toString().toLowerCase();
      if(tipo.includes('antib')) return true;
      const meta = metaByClave[clave];
      const clas = meta ? String(meta.clasificacion||'') : '';
      return clas.toUpperCase().includes('ANTIB');
    };

    const addMov = (mov, clave, desc, pzs)=>{
      if(!clave) return;
      if(!mov[clave]) mov[clave] = { clave, descripcion: desc||'', consumo: 0 };
      mov[clave].consumo += (Number(pzs)||0);
      if(desc && (!mov[clave].descripcion || desc.length > mov[clave].descripcion.length)){
        mov[clave].descripcion = desc;
      }
    };

    const antibStore = await idbAll('antibioticos').catch(()=>[]);
    const salidas = await idbAll('salidas').catch(()=>[]);

    const acumularPorMes = (mesFiltro)=>{
      const mov = {}; // clave -> {clave, descripcion, consumo}
      (antibStore||[]).forEach(a=>{
        const dt = parseFechaFlexible(a.fecha || a.date || a.ts || a.timestamp || a.fechahora || a.fechaHora || a.createdAt);
        const mes = dt ? dt.toISOString().slice(0,7) : null;
        if(mesFiltro && mes !== mesFiltro) return;

        const clave = mxClaveUnica(a.clave ?? a.Clave ?? a.codigo ?? a.Codigo ?? a.sku ?? '');
        if(!clave) return;

        const meta = metaByClave[clave] || {};
        const desc = String(a.descripcion ?? a.Descripción ?? a.nombre ?? a.producto ?? meta.descripcion ?? '').trim();
        const pzs  = Number(a.pzs ?? a.cantidad ?? a.piezas ?? a.qty ?? 0) || 0;

        addMov(mov, clave, desc, pzs);
      });

      (salidas||[]).forEach(s=>{
        const dt = parseFechaFlexible(s.fecha || s.date || s.ts || s.timestamp || s.fechahora || s.fechaHora || s.createdAt);
        const mes = dt ? dt.toISOString().slice(0,7) : null;
        if(mesFiltro && mes !== mesFiltro) return;

        const clave = mxClaveUnica(s.clave ?? s.Clave ?? s.codigo ?? s.Codigo ?? s.sku ?? '');
        if(!clave) return;
        if(!isAntibiotico({ ...s, clave })) return;

        const meta = metaByClave[clave] || {};
        const desc = String(s.descripcion ?? s.Descripción ?? s.nombre ?? s.producto ?? meta.descripcion ?? '').trim();
        const pzs  = Number(s.pzs ?? s.cantidad ?? s.piezas ?? s.qty ?? s.salida ?? s.cant ?? 0) || 0;

        addMov(mov, clave, desc, pzs);
      });

      return mov;
    };

    let mov = acumularPorMes(mesObjetivo);
    let rowsArr = Object.values(mov).filter(r=>r.consumo>0).sort((a,b)=>b.consumo-a.consumo);

    if(!rowsArr.length){
      mov = acumularPorMes(null); // sin filtro de mes
      rowsArr = Object.values(mov).filter(r=>r.consumo>0).sort((a,b)=>b.consumo-a.consumo);
    }

    if(!rowsArr.length){
      mxAlert("No hay movimientos de antibióticos para exportar.");
      return false;
    }

    const rows = rowsArr.map(r=>({
      "Clave": r.clave,
      "Descripción": r.descripcion || (metaByClave[r.clave]?.descripcion || ""),
      "Consumo (pzs)": r.consumo
    }));

    const wb = XLSX.utils.book_new();
    const ws = XLSX.utils.json_to_sheet(rows);
    XLSX.utils.book_append_sheet(wb, ws, "Antibióticos");
    XLSX.writeFile(wb, filename);
    return true;

  }catch(e){
    console.error(e);
    mxAlert("No se pudo exportar. Revisa la consola.");
    return false;
  }
}

