async function exportConsumoMensualToExcel(){
  try{
    if (typeof XLSX === "undefined"){
      mxAlert("No se encontró la librería XLSX. Revisa conexión al CDN.");
      return false;
    }

    const pick = document.getElementById('consMesPick');
    const month = (pick && pick.value) ? pick.value : (new Date().toLocaleString().slice(0,7)); // YYYY-MM

    const parts = month.split('-');
    const y = Number(parts[0]||0);
    const mo = Number(parts[1]||0); // 1..12
    const diasMes = (y>0 && mo>=1 && mo<=12) ? new Date(y, mo, 0).getDate() : 30;

    const salidas = await idbAll('salidas');
    const inv = await idbAll('inventory');

    const metaByClave = {};
    inv.forEach(r=>{
      const c = String(r.clave||'').trim();
      if(!c) return;
      if(!metaByClave[c]){
        metaByClave[c] = {
          clave: c,
          descripcion: String(r.descripcion || r.nombre || '').trim(),
          unidad: String(r.unidad || '').trim(),
          clasificacion: String(r.clasificacion || r.clasif || r.departamento || 'Sin clasificar').trim(),
          cads: new Set()
        };
      }
      const m = metaByClave[c];

      const desc = String(r.descripcion || r.nombre || '').trim();
      const uni  = String(r.unidad || '').trim();
      const clas = String(r.clasificacion || r.clasif || r.departamento || '').trim();
      if(!m.descripcion && desc) m.descripcion = desc;
      if(!m.unidad && uni) m.unidad = uni;
      if((!m.clasificacion || m.clasificacion==='Sin clasificar') && clas) m.clasificacion = clas;

      const cad = String(r.caducidad || r.cad || '').trim();
      if(cad) m.cads.add(cad);
    });

    const isAntibiotico = (s)=>{
      const clave = String(s.clave||'').trim();
      const tipo = (s.tipoDoc||s.tipo||s.documento||'').toString().toLowerCase();
      if(tipo.includes('antib')) return true;
      const meta = metaByClave[clave];
      const clas = meta ? String(meta.clasificacion||'') : '';
      return clas.toUpperCase().includes('ANTIB');
    };

    const aggAb = new Map();
    const aggNo = new Map();

    for(const s of salidas){
      const d = mxYMD(s.fecha || s.date || s.ts || s.timestamp);
      if(!d || !d.startsWith(month)) continue;

      const clave = String(s.clave||'').trim();
      if(!clave) continue;

      const meta = metaByClave[clave] || { descripcion:'', unidad:'', clasificacion:'Sin clasificar', cads:new Set() };
      const desc = String(s.descripcion || meta.descripcion || '').trim();
      const unidad = String(s.unidad || meta.unidad || '').trim();
      const clas = String(meta.clasificacion || 'Sin clasificar').trim();

      const pzs = Number(s.pzs || s.cantidad || 0) || 0;

      const target = isAntibiotico(s) ? aggAb : aggNo;
      const cur = target.get(clave) || {
        clave,
        descripcion: desc,
        unidad,
        clasificacion: clas,
        pzs: 0,
        movimientos: 0,
        cads: new Set()
      };

      cur.pzs += pzs;
      cur.movimientos += 1;

      const cadSalida = String(s.caducidad || s.cad || '').trim();
      if(cadSalida) cur.cads.add(cadSalida);
      if(meta && meta.cads){
        meta.cads.forEach(x=>cur.cads.add(x));
      }

      if(!cur.descripcion && desc) cur.descripcion = desc;
      if(!cur.unidad && unidad) cur.unidad = unidad;
      if((!cur.clasificacion || cur.clasificacion==='Sin clasificar') && clas) cur.clasificacion = clas;

      target.set(clave, cur);
    }

    const toRows = (mp)=>{
      return Array.from(mp.values())
        .sort((a,b)=> (b.pzs - a.pzs) || (b.movimientos - a.movimientos))
        .map((r, idx)=>{
          const cadStr = r.cads && r.cads.size ? Array.from(r.cads).sort().join(" | ") : "";
          const promDia = diasMes ? (r.pzs / diasMes) : 0;
          return {
            "#": idx+1,
            "CLAVE": r.clave,
            "DESCRIPCION": r.descripcion,
            "UNIDAD": r.unidad,
            "CLASIFICACION": r.clasificacion,
            "CADUCIDADES": cadStr,
            "TOTAL_PZS_MES": r.pzs,
            "PROMEDIO_DIA": Number(promDia.toFixed(2)),
            "MOVIMIENTOS": r.movimientos
          };
        });
    };

    const rowsAb = toRows(aggAb);
    const rowsNo = toRows(aggNo);

    if(!rowsAb.length && !rowsNo.length){
      mxAlert("No hay salidas registradas en el mes seleccionado ("+month+").");
      return false;
    }

    const wb = XLSX.utils.book_new();
    const wsAb = XLSX.utils.json_to_sheet(rowsAb.length?rowsAb:[{"INFO":"Sin registros en este mes"}]);
    const wsNo = XLSX.utils.json_to_sheet(rowsNo.length?rowsNo:[{"INFO":"Sin registros en este mes"}]);

    XLSX.utils.book_append_sheet(wb, wsAb, "Antibioticos");
    XLSX.utils.book_append_sheet(wb, wsNo, "No_antibioticos");

    const filename = `CONSUMO_MENSUAL_${month}_AB_SEPARADO.xlsx`;
    XLSX.writeFile(wb, filename);
    return true;
  }catch(e){
    console.error(e);
    mxAlert("No se pudo exportar el consumo mensual: " + (e && e.message ? e.message : e));
    return false;
  }
}

async function ensureDBReady(){
  if(db){
    try{
      if(!window.__mxUseLsDb && !window.__mxLsdbMigrationChecked && typeof window.__mxMigrateLocalFallbackToIndexedDb === 'function'){
        window.__mxLsdbMigrationChecked = true;
        await window.__mxMigrateLocalFallbackToIndexedDb();
      }
    }catch(e){ console.warn('[MX] Revisión de persistencia local falló', e); }
    return db;
  }
  await idbOpen();
  if(!db) throw new Error('DB');
  try{
    if(!window.__mxUseLsDb && !window.__mxLsdbMigrationChecked && typeof window.__mxMigrateLocalFallbackToIndexedDb === 'function'){
      window.__mxLsdbMigrationChecked = true;
      await window.__mxMigrateLocalFallbackToIndexedDb();
    }
  }catch(e){ console.warn('[MX] Revisión de persistencia local falló', e); }
  return db;
}

async function exportStockBajoToExcel(opts={}){
  const filename = opts.filename || ("STOCK_BAJO_" + _fileSafeTS() + ".xlsx");
  try{
    if (typeof XLSX === "undefined"){
      mxAlert("No se encontró la librería XLSX. Revisa conexión al CDN.");
      return false;
    }
    if (typeof ensureDBReady === 'function') await ensureDBReady();
    const inventario = await idbAll('inventory').catch(()=>[]);
    if(!inventario.length){ mxAlert("No hay inventario para exportar."); return false; }

    const agg = {};
    inventario.forEach(it=>{
      const clave = String(it?.clave ?? it?.CLAVE ?? '').trim();
      if(!clave) return;
      const ex = Number(it?.existencia ?? it?.existencias ?? it?.EXISTENCIA ?? it?.EXISTENCIAS ?? (Number(it?.almacen||0)+Number(it?.estantes||0)) ?? 0) || 0;
      const desc = String(it?.descripcion ?? it?.nombre ?? it?.DESCRIPCION ?? it?.NOMBRE ?? '').trim();
      const ubic = String(it?.ubicacion ?? it?.UBICACION ?? it?.ubic ?? it?.UBIC ?? '').trim();
      if(!agg[clave]) agg[clave] = { clave, descripcion: desc, existencia: 0, ubicacion: ubic };
      agg[clave].existencia += ex;
      if((!agg[clave].descripcion || agg[clave].descripcion.trim()==='') && desc) agg[clave].descripcion = desc;
      if((!agg[clave].ubicacion || agg[clave].ubicacion.trim()==='') && ubic) agg[clave].ubicacion = ubic;
    });

    const list = Object.values(agg)
      .filter(x => Number(x.existencia||0) > 0)
      .sort((a,b)=> Number(a.existencia||0) - Number(b.existencia||0))
      .slice(0, 15);

    if(!list.length){ mxAlert("No hay productos con existencia para calcular stock bajo."); return false; }

    const rows = list.map((x,i)=>({
      "#": i+1,
      "Clave": x.clave,
      "Descripción": x.descripcion || "",
      "Existencia": Number(x.existencia||0),
      "Ubicación": x.ubicacion || ""
    }));

    const ws = XLSX.utils.json_to_sheet(rows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Stock bajo");
    XLSX.writeFile(wb, filename);
    return true;
  }catch(err){
    console.error("exportStockBajoToExcel()", err);
    mxAlert("No se pudo exportar Stock bajo. Revisa la consola.");
    return false;
  }
}

async function exportCadRangosToExcel(opts={}){
  const filename = opts.filename || ("CADUCIDAD_RANGOS_DETALLE_" + _fileSafeTS() + ".xlsx");
  try{
    if (typeof XLSX === "undefined"){
      mxAlert("No se encontró la librería XLSX. Revisa conexión al CDN.");
      return false;
    }
    if (typeof ensureDBReady === 'function') await ensureDBReady();
    const inventario = await idbAll('inventory').catch(()=>[]);
    if(!inventario.length){ mxAlert("No hay inventario para exportar."); return false; }

    const today = new Date(); today.setHours(0,0,0,0);
    const parseCad = (cadStr)=>{
      if (typeof parseFechaFlexible === 'function') return parseFechaFlexible(cadStr);
      const d = cadStr ? new Date(String(cadStr).trim()) : null;
      return (d && !isNaN(d.getTime())) ? d : null;
    };
    const rangoDe = (diffDays, hasDate)=>{
      if(!hasDate) return "Sin fecha";
      if(diffDays < 0) return "Caducado";
      if(diffDays <= 90) return "0-90 días";
      if(diffDays <= 180) return "91-180 días";
      if(diffDays <= 365) return "181-365 días";
      return ">365 días";
    };
    const getEx = (it)=>{
      return Number(
        it?.existencia ?? it?.existencias ?? it?.EXISTENCIA ?? it?.EXISTENCIAS ??
        (Number(it?.almacen||0)+Number(it?.estantes||0)) ?? 0
      ) || 0;
    };

    const resumen = [
      { "Rango":"Caducado", "Lotes":0 },
      { "Rango":"0-90 días", "Lotes":0 },
      { "Rango":"91-180 días", "Lotes":0 },
      { "Rango":"181-365 días", "Lotes":0 },
      { "Rango":">365 días", "Lotes":0 },
      { "Rango":"Sin fecha", "Lotes":0 },
    ];
    const idx = {"Caducado":0,"0-90 días":1,"91-180 días":2,"181-365 días":3,">365 días":4,"Sin fecha":5};

    const detalle = [];
    (inventario||[]).forEach(it=>{
      const clave = String(it?.clave ?? it?.CLAVE ?? '').trim();
      if(!clave) return;
      const desc = String(it?.descripcion ?? it?.DESCRIPCION ?? it?.nombre ?? it?.NOMBRE ?? '').trim();
      const lote = String(it?.lote ?? it?.LOTE ?? '').trim();
      const cadStr = String(it?.caducidad ?? it?.CADUCIDAD ?? it?.cad ?? it?.CAD ?? '').trim();
      const ubic = String(it?.ubicacion ?? it?.UBICACION ?? it?.ubic ?? it?.UBIC ?? '').trim();
      const clas = String(it?.clasificacion ?? it?.CLASIFICACION ?? '').trim();
      const rest = String(it?.restriccion ?? it?.RESTRICCION ?? '').trim();

      const d = parseCad(cadStr);
      const hasDate = !!d;
      let diffDays = null;
      if(hasDate){
        const dd = new Date(d); dd.setHours(0,0,0,0);
        diffDays = Math.floor((dd - today)/86400000);
      }
      const rango = rangoDe(diffDays, hasDate);
      resumen[idx[rango]].Lotes += 1;

      detalle.push({
        rango,
        clave,
        descripcion: desc,
        lote,
        caducidad: cadStr,
        dias_restantes: (diffDays==null? "": diffDays),
        existencia: Math.round(getEx(it)),
        ubicacion: ubic,
        clasificacion: clas,
        restriccion: rest
      });
    });

    detalle.sort((a,b)=>{
      const aHas = a.dias_restantes!==""; const bHas = b.dias_restantes!=="";
      if(aHas && !bHas) return -1;
      if(!aHas && bHas) return 1;
      if(!aHas && !bHas) return 0;
      return Number(a.dias_restantes) - Number(b.dias_restantes);
    });

    const topN = Math.max(1, Math.min(200, Number(opts.top || 30) || 30));
    const top = detalle.slice(0, topN).map((x,i)=>({
      "#": i+1,
      "Rango": x.rango,
      "Clave": x.clave,
      "Descripción": x.descripcion,
      "Lote": x.lote,
      "Caducidad": x.caducidad,
      "Días restantes": x.dias_restantes,
      "Existencia": x.existencia,
      "Ubicación": x.ubicacion,
      "Clasificación": x.clasificacion,
      "Restricción": x.restriccion
    }));

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(resumen), "Rangos");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(top), "Detalle Top 30");
    XLSX.writeFile(wb, filename);
    return true;
  }catch(err){
    console.error("exportCadRangosToExcel()", err);
    mxAlert("No se pudo exportar Caducidad por rangos. Revisa la consola.");
    return false;
  }
}
async function exportProxAgotarToExcel(opts={}){
  const filename = opts.filename || ("PROXIMOS_AGOTARSE_" + _fileSafeTS() + ".xlsx");
  try{
    if (typeof XLSX === "undefined"){
      mxAlert("No se encontró la librería XLSX. Revisa conexión al CDN.");
      return false;
    }
    if (typeof ensureDBReady === 'function') await ensureDBReady();

    const inventario = await idbAll('inventory').catch(()=>[]);
    const salidas = await idbAll('salidas').catch(()=>[]);
    if(!inventario.length){ mxAlert("No hay inventario para exportar."); return false; }
    if(!salidas.length){ mxAlert("No hay historial de salidas para estimar consumo."); return false; }

    const ymdLocal = (v)=>{
      if(!v) return '';
      const s = String(v).trim();
      let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
      if(m) return `${m[1]}-${m[2]}-${m[3]}`;
      m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/);
      if(m) return `${m[3]}-${m[2]}-${m[1]}`;
      m = s.match(/^(\d{2})-(\d{2})-(\d{4})/);
      if(m) return `${m[3]}-${m[2]}-${m[1]}`;
      const d = new Date(s);
      if(!isNaN(d.getTime())) return d.toISOString().slice(0,10);
      return '';
    };
    const lastNDaysLocal = (n)=>{
      const out=[];
      const d=new Date(); d.setHours(0,0,0,0);
      for(let i=0;i<n;i++){
        const x=new Date(d); x.setDate(d.getDate()-i);
        out.push(x.toISOString().slice(0,10));
      }
      return out;
    };
    const ymd = (typeof window.ymd === 'function') ? window.ymd : ymdLocal;
    const lastNDays = (typeof window.lastNDays === 'function') ? window.lastNDays : lastNDaysLocal;

    const dias30 = lastNDays(30);
    const consumo30 = {};
    salidas.forEach(s=>{
      const d = ymd(s.fecha || s.date || s.ts || s.timestamp || s.fechahora || s.createdAt);
      if(d && dias30.includes(d)){
        const c = String(s.clave ?? s.CLAVE ?? '').trim();
        if(!c) return;
        consumo30[c] = (consumo30[c]||0) + Number(s.pzs ?? s.piezas ?? s.cantidad ?? 0);
      }
    });

    const exByClave = {};
    const descByClave = {};
    const ubicByClave = {};
    inventario.forEach(it=>{
      const c = String(it?.clave ?? it?.CLAVE ?? '').trim();
      if(!c) return;
      const ex = Number(it?.existencia ?? it?.existencias ?? it?.EXISTENCIA ?? it?.EXISTENCIAS ?? 0) || 0;
      exByClave[c] = (exByClave[c]||0) + ex;
      const desc = String(it?.descripcion ?? it?.nombre ?? '').trim();
      if(desc && !descByClave[c]) descByClave[c]=desc;
      const ub = String(it?.ubicacion ?? it?.UBICACION ?? it?.ubic ?? '').trim();
      if(ub && !ubicByClave[c]) ubicByClave[c]=ub;
    });

    const agotar=[];
    Object.keys(exByClave).forEach(c=>{
      const ex = Number(exByClave[c]||0);
      const cons = Number(consumo30[c]||0);
      if(ex>0 && cons>0){
        const prom = cons/30;
        const diasRest = ex / (prom || 1e-9);
        if(diasRest <= 60){
          agotar.push({
            clave: c,
            descripcion: descByClave[c] || '',
            existencia: Math.round(ex),
            consumo_30_dias: Math.round(cons),
            promedio_diario: Number(prom.toFixed(3)),
            dias_restantes_estimados: Math.round(diasRest),
            ubicacion: ubicByClave[c] || ''
          });
        }
      }
    });

    const top = agotar.sort((a,b)=>a.dias_restantes_estimados - b.dias_restantes_estimados).slice(0, 30);
    if(!top.length){
      mxAlert("No hay productos próximos a agotarse con consumo en los últimos 30 días (<=30 días estimados).");
      return false;
    }

    const rows = top.map((x,i)=>({
      "#": i+1,
      "Clave": x.clave,
      "Descripción": x.descripcion,
      "Existencia": x.existencia,
      "Consumo 30 días": x.consumo_30_dias,
      "Promedio diario": x.promedio_diario,
      "Días restantes (estimado)": x.dias_restantes_estimados,
      "Ubicación": x.ubicacion
    }));

    const ws = XLSX.utils.json_to_sheet(rows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Prox. agotarse");
    XLSX.writeFile(wb, filename);
    return true;
  }catch(err){
    console.error("exportProxAgotarToExcel()", err);
    mxAlert("No se pudo exportar Próximos a agotarse. Revisa la consola.");
    return false;
  }
}

