function idbGetByIndex(store, indexName, keyArr){
  return new Promise((res, rej)=>{
    if(!db) return rej('DB');
    const tx = db.transaction(store,'readonly');
    const st = tx.objectStore(store);
    let idx;
    try { idx = st.index(indexName); } catch(e){ return res(null); }
    const rq = idx.get(keyArr);
    rq.onsuccess = ()=> res(rq.result || null);
    rq.onerror   = ()=> rej(rq.error);
  });
}

let __pendingSalidas = Array.isArray(window.__pendingSalidas) ? window.__pendingSalidas : [];
window.__pendingSalidas = __pendingSalidas;
window.__mxSalidasOpsCanceladas = window.__mxSalidasOpsCanceladas || Object.create(null);
let __salidasFlushPromise = null;

function mxSalidaOpId(row){ return String(row && row._mxOpId || '').trim(); }
function mxCancelarOpSalida(row){
  const opId=mxSalidaOpId(row); if(!opId) return '';
  window.__mxSalidasOpsCanceladas[opId]=Date.now();
  try{ mxWalAcknowledge('salidas',[row]); }catch(_e){}
  return opId;
}
async function mxEliminarSalidaPersistidaPorOpId(opId){
  opId=String(opId||'').trim();if(!opId)return false;
  try{
    let found=null;
    if(window.electronSql?.isElectron&&typeof window.electronSql.indexGet==='function')found=await window.electronSql.indexGet('salidas','_mx_op_id',opId,false);
    else if(typeof idbGetByIndex==='function')found=await idbGetByIndex('salidas','_mx_op_id',opId);
    if(found&&found._id!=null){
      if(window.electronSql?.isElectron&&typeof window.electronSql.transaction==='function'){
        await window.electronSql.transaction([{type:'delete',store:'salidas',key:Number(found._id)}]);
        try{window.__mxClearSqlCache?.('salidas')}catch(_e){}
      }else await idbDelete('salidas',found._id);
      return true;
    }
  }catch(e){console.warn('No se pudo retirar una salida cancelada por operación',e);}
  return false;
}

// Fallback mínimo. El motor durable SQLite instalado al final sustituye estas dos
// funciones antes de que el usuario pueda capturar. Se conserva solo para recuperación.
async function __flushSalidas(){ return true; }
async function saveSalida(row){
  const source=(row&&typeof row==='object')?row:{};
  try{Object.assign(source,mxNormalizeSalidaRow(source)||source);}catch(_e){}
  try{mxEnsureOpId('salidas',source);}catch(_e){}
  try{
    const id=await idbPut('salidas',source);
    if(id&&!source._id) source._id=id;
    try{mxPushSalidaHistCache(source);mxConfirmSalidasHistCacheRows([source]);}catch(_e){}
    return source;
  }catch(e){throw e;}
}
try{ saveSalida.__mxFoliosDirectV113=true; }catch(_e){}

