function __mxEntradaExIni(r){
  return Number(r?.ex_ini ?? r?.existencia_inicial ?? 0) || 0;
}
function __mxEntradaExFin(r){
  const exIni = __mxEntradaExIni(r);
  const pzs = Number(r?.pzs || 0) || 0;
  return exIni + pzs;
}
function __mxSalidaExIni(r){
  return Number(r?.ex_ini ?? r?.existencia_inicial ?? 0) || 0;
}
function __mxSalidaExFin(r){
  const exIni = __mxSalidaExIni(r);
  const pzs = Number(r?.pzs || 0) || 0;
  const raw = Number(r?.ex_fin ?? r?.existencia_final);
  return Number.isFinite(raw) ? raw : Math.max(0, exIni - pzs);
}
