async function __flushEntradas(){ return true; }

let __pendingAntib = Array.isArray(window.__pendingAntib) ? window.__pendingAntib : [];
window.__pendingAntib = __pendingAntib;
let __antibFlushTimer = null;
async function __flushAntib(){
  if(!__pendingAntib.length) return true;
  const payload = __pendingAntib.splice(0, __pendingAntib.length);
  let toWrite=payload;
  try{
    toWrite=await mxRowsNotCommitted('antibioticos',payload);
    if(toWrite.length) await idbBulkPut('antibioticos',toWrite);
    if(typeof window.__mxFlushSqlWrites==='function') await window.__mxFlushSqlWrites();
    try{ mxWalAcknowledge('antibioticos', payload); }catch(_e){}
    try{ window.__mxSaveQueues(); }catch(_e){}
    return true;
  }catch(e){
    console.warn('Batch antibioticos failed', e);
    try{ mxWalAcknowledge('antibioticos',payload.filter(r=>!toWrite.includes(r))); }catch(_e){}
    __pendingAntib.unshift(...toWrite);
    try{ window.__mxSaveQueues(); }catch(_e){}
    throw e;
  }
}
function saveAntibiotico(row){
  try{ mxEnsureOpId('antibioticos', row); }catch(_e){}
  mxWalAppend('antibioticos', row);

  __pendingAntib.push(row);
  try{ window.__mxSaveQueues(); }catch(_e){}
  appendRowIfVisible('tblAb', rowHtmlAntib(row));

  clearTimeout(__antibFlushTimer);
  __antibFlushTimer = setTimeout(()=>{ try{ __mxScheduleFlushAll(0); }catch(_e){} }, 35);
}

if (typeof saveSalida === 'function') {
  const __origSaveSalida = saveSalida;
  saveSalida = async function(row){
    try{
      if(row && !row.createdAt) row.createdAt = Date.now();
      mxWalAppend('salidas', row);
    }catch(_){}

    // Guardado lógico inmediato: actualiza cola, WAL y caché sin esperar la escritura física.
    const result = await __origSaveSalida(row);

    // Persistencia en segundo plano. Ya no bloquea el historial ni el siguiente escaneo.
    try{ __mxScheduleFlushAll(0); }catch(_){}
    try{
      if(typeof mxRefreshUltimoYSiguienteFolioSalida === 'function'){
        setTimeout(()=>{ try{ mxRefreshUltimoYSiguienteFolioSalida(); }catch(e){} }, 180);
      }
    }catch(_){ }

    return result || row;
  }
}

