function mxRemoteDbRestUrl(path, cacheBust=false){
  const base = mxNormalizeDbUrl(typeof mxRemoteDbUrl === 'function' ? mxRemoteDbUrl() : '');
  if(!base) return '';
  let cleanPath = String(path || '');
  if(!cleanPath.startsWith('/')) cleanPath = '/' + cleanPath;
  if(!/\.json(?:\?|$)/i.test(cleanPath)) cleanPath += '.json';
  const url = new URL(base + cleanPath);
  if(cacheBust) url.searchParams.set('ts', String(Date.now()));
  return url.toString();
}
window.mxRemoteDbAuth = mxRemoteDbAuth;
window.mxSetRemoteDbAuth = mxSetRemoteDbAuth;
window.mxRemoteDbRestUrl = mxRemoteDbRestUrl;

function mxNormalizeDbUrl(url){
  return String(url || '').trim().replace(/\/+$/g,'');
}
const MX_RESERVED_FIREBASE_HOSTS = new Set([
  'ecosistema-macroxel-default-rtdb.firebaseio.com',
  'licenciasmacroxel-default-rtdb.firebaseio.com'
]);
function mxOperationalDbValidation(url){
  const clean=mxNormalizeDbUrl(url);
  if(!clean)return{ok:false,url:'',reason:'URL vacía'};
  try{
    const u=new URL(clean),host=String(u.hostname||'').toLowerCase();
    if(u.protocol!=='https:')return{ok:false,url:clean,reason:'Debe usar https://'};
    if(!/(?:firebaseio\.com|firebasedatabase\.app)$/i.test(host))return{ok:false,url:clean,reason:'Debe ser una URL de Firebase Realtime Database'};
    if(MX_RESERVED_FIREBASE_HOSTS.has(host))return{ok:false,url:clean,reason:'Esta Firebase está reservada para control/licencias y no puede usarse como base operativa'};
    return{ok:true,url:clean,host};
  }catch(_e){return{ok:false,url:clean,reason:'URL no válida'}}
}
window.mxOperationalDbValidation=mxOperationalDbValidation;

function mxRemoteDbPool(){
  let urls=[],active='';
  try{const raw=JSON.parse(localStorage.getItem(MX_REMOTE_DB_POOL_STORAGE_KEY)||'{}');if(Array.isArray(raw?.urls))urls=raw.urls.map(mxNormalizeDbUrl).filter(u=>mxOperationalDbValidation(u).ok);active=mxNormalizeDbUrl(raw?.active||'');if(active&&!mxOperationalDbValidation(active).ok)active=''}catch(_e){}
  urls=[...new Set(urls)];if(active&&!urls.includes(active))active='';if(!active)active=urls[0]||'';return{urls,active};
}
function mxSaveRemoteDbPool(urls,active){
  const clean=[...new Set((Array.isArray(urls)?urls:[]).map(mxNormalizeDbUrl).filter(u=>mxOperationalDbValidation(u).ok))];
  let a=mxNormalizeDbUrl(active||'');
  if(a&&!clean.includes(a))a='';
  if(!a)a=clean[0]||'';
  try{
    localStorage.setItem(MX_REMOTE_DB_POOL_STORAGE_KEY,JSON.stringify({urls:clean,active:a,updatedAt:new Date().toISOString()}));
    localStorage.setItem(MX_REMOTE_DB_POOL_INITIALIZED_KEY,'1');
  }catch(_e){}
  return {urls:clean,active:a};
}
function mxConfiguredRemoteDbUrl(){try{const pool=mxRemoteDbPool();window.__mxRemoteDbUrlCache=pool.active||'';return pool.active||''}catch(_e){return''}}
function mxRemoteDbUrl(){return mxRemoteDbEnabled()?mxConfiguredRemoteDbUrl():'';}
function mxRemoteDbCandidates(){const p=mxRemoteDbPool();return [p.active,...p.urls].map(mxNormalizeDbUrl).filter((x,i,a)=>x&&a.indexOf(x)===i);}
window.mxConfiguredRemoteDbUrl=mxConfiguredRemoteDbUrl;
window.mxRemoteDbPool=mxRemoteDbPool;
window.mxRemoteDbCandidates=mxRemoteDbCandidates;

async function mxWriteRemoteDbUrlToIndexedDb(url){
  const normalized = mxNormalizeDbUrl(url);
  const clean = normalized;
  try{
    if(typeof idbOpen !== 'function') return clean;
    await idbOpen();
    if(!db) return clean;
    const tx = db.transaction('kv', 'readwrite');
    const st = tx.objectStore('kv');
    await new Promise((resolve)=>{
      const rq = clean ? st.put(clean, MX_REMOTE_DB_KV_KEY) : st.delete(MX_REMOTE_DB_KV_KEY);
      rq.onsuccess = () => resolve();
      rq.onerror = () => resolve();
    });
  }catch(e){}
  return clean;
}

async function mxHydrateRemoteDbUrl(){
  const current=mxConfiguredRemoteDbUrl();window.__mxRemoteDbUrlCache=current||'';
  // v1.0.1 estricto: las URLs antiguas no son fuente de configuración.
  try{localStorage.removeItem(MX_REMOTE_DB_STORAGE_KEY);localStorage.setItem(MX_REMOTE_DB_POOL_INITIALIZED_KEY,'1')}catch(_e){}
  try{await mxWriteRemoteDbUrlToIndexedDb(current||'')}catch(_e){}
  return current||'';
}

function mxSetRemoteDbPool(urls,active=''){
  const previous=mxConfiguredRemoteDbUrl(); const pool=mxSaveRemoteDbPool(urls,active);
  const next=pool.active||''; window.__mxRemoteDbUrlCache=next;
  try{if(next)localStorage.setItem(MX_REMOTE_DB_STORAGE_KEY,next);else localStorage.removeItem(MX_REMOTE_DB_STORAGE_KEY);}catch(_e){}
  Promise.resolve(mxWriteRemoteDbUrlToIndexedDb(next)).catch(()=>{});
  try{window.dispatchEvent(new CustomEvent('mx-remote-db-url-changed',{detail:{previousUrl:previous,url:next,enabled:mxRemoteDbEnabled()&&!!next,configured:!!next,pool:pool.urls}}))}catch(_e){}
  setTimeout(()=>mxPublishRouterToPool('POOL_UPDATED').catch(()=>{}),100);
  return pool;
}
function mxActivateRemoteDbUrl(url,reason='FAILOVER'){
  const check=mxOperationalDbValidation(url),clean=check.ok?check.url:''; if(!clean)return '';
  const previous=mxConfiguredRemoteDbUrl(); const pool=mxRemoteDbPool();
  mxSaveRemoteDbPool(pool.urls,clean); window.__mxRemoteDbUrlCache=clean;
  try{localStorage.setItem(MX_REMOTE_DB_STORAGE_KEY,clean);}catch(_e){}
  Promise.resolve(mxWriteRemoteDbUrlToIndexedDb(clean)).catch(()=>{});
  if(previous!==clean){
    console.warn('[Firebase failover]',previous,'→',clean,reason);
    try{window.dispatchEvent(new CustomEvent('mx-remote-db-url-changed',{detail:{previousUrl:previous,url:clean,enabled:true,configured:true,failover:true,reason}}))}catch(_e){}
    setTimeout(()=>mxPublishRouterToPool(reason).catch(()=>{}),150);
  }
  return clean;
}
async function mxPublishRouterToPool(reason='SYNC'){
  const pool=mxRemoteDbPool(); if(!pool.urls.length)return false;
  const branch=String(typeof mxGetSucursalFromLicense==='function'?(mxGetSucursalFromLicense()||'HGAM'):'HGAM').trim().toUpperCase()||'HGAM';
  const unitName=String(typeof mxGetUnitNameFromLicense==='function'?(mxGetUnitNameFromLicense()||''):'').trim();
  const body={version:4,v:Date.now(),activeUrl:pool.active,urls:pool.urls,reason,mode:'PRODUCTION',unitId:branch,activationId:branch,unitName,principalName:unitName,appVersion:'1.0.1',updatedAt:new Date().toISOString()};
  const path=`/ecosystem_router/${encodeURIComponent(branch)}.json`;
  await Promise.allSettled(pool.urls.map(async base=>{const c=new AbortController();const t=setTimeout(()=>c.abort(),6500);try{await fetch(base+path,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:c.signal,cache:'no-store'});}finally{clearTimeout(t);}}));
  return true;
}
window.mxSetRemoteDbPool=mxSetRemoteDbPool;
window.mxActivateRemoteDbUrl=mxActivateRemoteDbUrl;
window.mxPublishRouterToPool=mxPublishRouterToPool;


