document.getElementById('btnLogout').onclick=()=>{
  // v1.0.151: cambio de usuario sin recargar Electron. La base, la licencia y
  // los índices permanecen abiertos; sólo se cierra la sesión visual/operativa.
  try{ sessionStorage.clear(); }catch(e){}
  try{ if(window.speechSynthesis) window.speechSynthesis.cancel(); }catch(e){}
  try{
    if(typeof currentUser!=='undefined') currentUser = null;
    try{ window.currentUser = null; }catch(_){}
    try{ window.__currentUser = null; }catch(_){}
    try{ window.__mxCurrentUser = null; }catch(_){}
  }catch(e){}
  try{ window.mxOperationalCoolDown?.(); }catch(_e){}
  try{
    document.body.classList.remove('logged');
    const login=document.getElementById('loginView'),top=document.getElementById('topbar'),app=document.getElementById('app'),who=document.getElementById('who');
    if(top) top.style.display='none';
    if(app) app.classList.add('hidden');
    if(login) login.style.display='';
    if(who) who.textContent='';
    const pass=document.getElementById('lgPass'); if(pass) pass.value='';
    const user=document.getElementById('lgUser'); if(user){ user.value=''; setTimeout(()=>user.focus(),40); }
  }catch(e){ console.warn('[MX LOGOUT] No se pudo volver a la pantalla de acceso',e); }
};

