  if(!list.length)return mxAlert('No hay anomalías registradas para eliminar.');
  if(!await mxConfirm(`¿Eliminar definitivamente las ${list.length} anomalías, incluyendo pendientes, revisadas y descartadas?\n\nEsta acción no se puede deshacer.`))return;
  if(_mxAnomalyAnalysisPromise){
    mxDetenerAnalisisAnomalias();
    try{await _mxAnomalyAnalysisPromise;}catch(_e){}
  }
  await idbClear('movimientos');
  _movCache=[];
  _mxAnomalySignatures=new Set();
  const status=document.getElementById('anomAnalysisStatus');
  if(status){status.className='mx-anom-status ok';status.textContent='Todas las anomalías fueron eliminadas correctamente.';}
