const mxDocStatsKey = 'mx_doc_stats_v1';
const mxDocSeenKey  = 'mx_doc_seen_v1';

function mxLoadDocStats(){
  try{ return JSON.parse(localStorage.getItem(mxDocStatsKey) || '{}') || {}; }
  catch(e){ return {}; }
}
function mxSaveDocStats(obj){
  try{ localStorage.setItem(mxDocStatsKey, JSON.stringify(obj||{})); }catch(e){}
}
function mxLoadDocSeen(){
  try{ return JSON.parse(localStorage.getItem(mxDocSeenKey) || '[]') || []; }
  catch(e){ return []; }
}
function mxSaveDocSeen(arr){
  try{ localStorage.setItem(mxDocSeenKey, JSON.stringify(arr||[])); }catch(e){}
}

function mxRegisterDocFromSalida(row){
  try{
    if(!row) return;
    const folio = String(row.folio||'').trim();
    const tipo  = String(row.tipo_doc||'').trim();
    if(!folio || !tipo) return;

    const key = `${tipo}||${folio}`;
    const seen = mxLoadDocSeen();
    if(seen.includes(key)) return;

    seen.push(key);
    while(seen.length > 2000) seen.shift();
    mxSaveDocSeen(seen);

    const stats = mxLoadDocStats();
    stats[tipo] = Number(stats[tipo]||0) + 1;
    stats.__total = Number(stats.__total||0) + 1;
    mxSaveDocStats(stats);

    try{ if(window.__currentViewId === 'productividad') drawProductividad(); }catch(_){ }
  }catch(e){}
}


function _parseYMDorDDMM(val){
  const s = String(val||'').trim();
  if(!s) return '';
  const iso = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if(iso) return `${iso[1]}-${String(iso[2]).padStart(2,'0')}-${String(iso[3]).padStart(2,'0')}`;
  const dmy = s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);
  if(dmy) return `${dmy[3]}-${String(dmy[2]).padStart(2,'0')}-${String(dmy[1]).padStart(2,'0')}`;
  return '';
}

function _fmtISOtoDMYHM(iso){
  const s = String(iso||'').trim();
  if(!s) return '';
  const ymd = _dateOnly(s);
  const t = s.includes('T') ? s.split('T')[1].slice(0,5) : '';
  const dmy = _fmtYMD(ymd);
  return t ? `${dmy} ${t}` : dmy;
}

async function drawProductividad(opts={}){
  try{
    const qRaw = (document.getElementById('prodBusca')?.value || '').trim();
    const q = typeof mxNormTxt === 'function' ? mxNormTxt(qRaw) : qRaw.toLowerCase();
    const hoy = _todayYMD();
    const mesInicio = hoy ? hoy.slice(0,7) + '-01' : hoy;
    const d1 = document.getElementById('prodDesde');
    const d2 = document.getElementById('prodHasta');
    const desde = (d1?.value || '').trim() || mesInicio || hoy;
    const hasta = (d2?.value || '').trim() || hoy;
    if(d1 && !d1.value && desde) d1.value = desde;
    if(d2 && !d2.value && hasta) d2.value = hasta;

    const _days = (()=>{ try{ const a=new Date(desde+'T00:00:00'); const b=new Date(hasta+'T00:00:00'); const diff=Math.floor((b-a)/86400000)+1; return diff>0?diff:1; }catch(e){ return 1; } })();
    const norm = (v)=> typeof mxNormTxt === 'function' ? mxNormTxt(v) : String(v||'').trim().toLowerCase();
    const pretty = (v)=>{
      const s = String(v||'').trim().replace(/\s+/g,' ');
      if(!s) return '—';
      return s.toLowerCase().replace(/(^|\s|[-\/\(])([a-záéíóúñ])/g, (m,p1,p2)=> p1 + p2.toUpperCase());
    };
    const baseAgg = ()=>({usuario:'—', total:0, entradas:0, pzsEnt:0, salidas:0, pzsSal:0, antib:0, ajustes:0, last:'', docs_total:0, docs_dia:0, docs_detalle:'', _userForms:{}});
    const ensureAgg = (map, rawUser)=>{
      const key = norm(rawUser || '—') || '—';
      if(!map[key]) map[key] = baseAgg();
      const row = map[key];
      const raw = String(rawUser||'').trim() || '—';
      row._userForms[raw] = (row._userForms[raw]||0) + 1;
      row.usuario = Object.entries(row._userForms).sort((a,b)=>Number(b[1]||0)-Number(a[1]||0))[0]?.[0] || pretty(raw);
      return { key, row };
    };
    const bestLabel = (obj, fallback)=>{
      const entries = Object.entries(obj||{});
      if(!entries.length) return fallback || '—';
      return entries.sort((a,b)=>Number(b[1]||0)-Number(a[1]||0))[0][0];
    };

    const agg = {};
    let entradasAll = [];
    let salidasAll = [];
    try{
      [entradasAll, salidasAll] = await Promise.all([
        idbAll('entradas').catch(()=>[]),
        idbAll('salidas').catch(()=>[])
      ]);
    }catch(_){
      entradasAll = [];
      salidasAll = [];
    }

    // Productividad se calcula directamente desde Entradas y Salidas.

    const docsByUser = {};
    const _docSeenUser = new Set();
    function _addDoc(u, tipo, folio){
      const userNorm = norm(u || '—') || '—';
      const tipoRaw = String(tipo||'').trim().replace(/\s+/g,' ');
      const tipoNorm = norm(tipoRaw);
      const folRaw = String(folio||'').trim();
      if(!tipoNorm || !folRaw) return;
      const k = `${userNorm}||${tipoNorm}||${folRaw.toUpperCase()}`;
      if(_docSeenUser.has(k)) return;
      _docSeenUser.add(k);
      if(!docsByUser[userNorm]) docsByUser[userNorm] = {total:0, tipos:{}, tipoLabels:{}};
      const d = docsByUser[userNorm];
      d.total += 1;
      d.tipos[tipoNorm] = Number(d.tipos[tipoNorm]||0) + 1;
      d.tipoLabels[tipoNorm] = d.tipoLabels[tipoNorm] || {};
      const shown = tipoRaw || pretty(tipoNorm);
      d.tipoLabels[tipoNorm][shown] = Number(d.tipoLabels[tipoNorm][shown]||0) + 1;
    }

    try{
      const entradas = entradasAll;
      for(const e of (entradas||[])){
        const f = _parseYMDorDDMM(e.fecha);
        if(!f || f < desde || f > hasta) continue;
        const rawUser = String(e.usuario||'—').trim() || '—';
        const uNorm = norm(rawUser);
        if(q && !uNorm.includes(q)) continue;
        const { row } = ensureAgg(agg, rawUser);
        row.entradas += 1;
        row.pzsEnt += Number(e.pzs||0);
        _addDoc(rawUser, `Entrada: ${String(e.tipo_doc||'').trim()}`, e.folio);
        if(!row.last || _dateOnly(row.last) < f) row.last = f;
      }
    }catch(_){ }

    try{
      const salidas = salidasAll;
      for(const s of (salidas||[])){
        const f = _parseYMDorDDMM(s.fecha);
        if(!f || f < desde || f > hasta) continue;
        const rawUser = String(s.usuario||'—').trim() || '—';
        const uNorm = norm(rawUser);
        if(q && !uNorm.includes(q)) continue;
        const { row } = ensureAgg(agg, rawUser);
        row.salidas += 1;
        row.pzsSal += Number(s.pzs||0);
        if(norm(s.tipo_doc||'').includes('antibi')) row.antib += 1;
        _addDoc(rawUser, String(s.tipo_doc||'').trim(), s.folio);
        if(!row.last || _dateOnly(row.last) < f) row.last = f;
      }
    }catch(_){ }

    Object.entries(agg).forEach(([userNorm, a])=>{
      const recomputedTotal = Number(a.entradas||0) + Number(a.salidas||0) + Number(a.ajustes||0);
      a.total = recomputedTotal;
      const d = docsByUser[userNorm] || {total:0, tipos:{}, tipoLabels:{}};
      a.docs_total = Number(d.total||0);
      a.docs_dia = Math.round((Number(a.docs_total||0) / (_days||1)) * 10) / 10;
      const pairs = Object.entries(d.tipos||{}).sort((x,y)=>Number(y[1]||0)-Number(x[1]||0));
      a.docs_detalle = pairs.map(([k,v])=>`${bestLabel(d.tipoLabels?.[k], pretty(k))} ${v}`).join(' | ');
      a.usuario = pretty(bestLabel(a._userForms, a.usuario));
    });

    const rows = Object.values(agg).sort((x,y)=> y.total - x.total || String(x.usuario||'').localeCompare(String(y.usuario||'')));

    const tb = document.querySelector('#tblProd tbody');
    if(tb){
      const _esc = (s)=>String(s??'').replace(/[&<>"']/g, ch=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[ch]));
      tb.innerHTML = rows.map(r=>`
        <tr>
          <td>${r.usuario}</td>
          <td>${r.total}</td>
          <td>${r.entradas}</td>
          <td>${Number(r.pzsEnt||0)}</td>
          <td>${r.salidas}</td>
          <td>${Number(r.pzsSal||0)}</td>
          <td>${r.antib}</td>
          <td>${r.ajustes}</td>
          <td>${Number(r.docs_total||0)}</td>
          <td>${Number(r.docs_dia||0)}</td>
          <td style="max-width:520px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;" title="${_esc(r.docs_detalle||'')}">${_esc(r.docs_detalle||'')}</td>
          <td>${_fmtISOtoDMYHM(r.last)}</td>
        </tr>
      `).join('');
    }

    const resumen = document.getElementById('prodResumen');
    if(resumen){
      const tot = rows.reduce((a,b)=>a + Number(b.total||0), 0);
      const docs = rows.reduce((a,b)=>a + Number(b.docs_total||0), 0);
      const entOps = rows.reduce((a,b)=>a + Number(b.entradas||0), 0);
      resumen.textContent = `Periodo: ${_fmtYMD(desde)} a ${_fmtYMD(hasta)} · Operaciones: ${tot} · Docs: ${docs} · Entradas capturadas: ${entOps}`;
    }

    const sal = salidasAll;
    const ent = entradasAll;
    const per = {};
    const perLabels = {};
    const seenPer = new Set();
    for(const s of sal){
      const tipoRaw = String(s.tipo_doc||'').trim().replace(/\s+/g,' ');
      const tipo = norm(tipoRaw);
      const fol = String(s.folio||'').trim();
      if(!tipo || !fol) continue;
      const f = _parseYMDorDDMM(s.fecha);
      if(!f || f < desde || f > hasta) continue;
      const k = `${tipo}||${fol.toUpperCase()}`;
      if(seenPer.has(k)) continue;
      seenPer.add(k);
      per[tipo] = Number(per[tipo]||0) + 1;
      perLabels[tipo] = perLabels[tipo] || {};
      const shown = tipoRaw || pretty(tipo);
      perLabels[tipo][shown] = Number(perLabels[tipo][shown]||0) + 1;
    }
    for(const e of ent){
      const tipoBaseRaw = String(e.tipo_doc||'').trim().replace(/\s+/g,' ');
      const tipoRaw = `Entrada: ${tipoBaseRaw}`;
      const tipo = norm(tipoRaw);
      const fol = String(e.folio||'').trim();
      if(!tipo || !fol) continue;
      const f = _parseYMDorDDMM(e.fecha);
      if(!f || f < desde || f > hasta) continue;
      const k = `${tipo}||${fol.toUpperCase()}`;
      if(seenPer.has(k)) continue;
      seenPer.add(k);
      per[tipo] = Number(per[tipo]||0) + 1;
      perLabels[tipo] = perLabels[tipo] || {};
      const shown = tipoRaw || pretty(tipo);
      perLabels[tipo][shown] = Number(perLabels[tipo][shown]||0) + 1;
    }

    const histRaw = mxLoadDocStats();
    const hist = {};
    const histLabels = {};
    let totHist = Number(histRaw.__total||0);
    Object.entries(histRaw||{}).forEach(([k,v])=>{
      if(!k || k.startsWith('__')) return;
      const nk = norm(k);
      if(!nk) return;
      hist[nk] = Number(hist[nk]||0) + Number(v||0);
      histLabels[nk] = histLabels[nk] || {};
      histLabels[nk][k] = Number(histLabels[nk][k]||0) + Number(v||0);
    });

    const tipos = Array.from(new Set([...Object.keys(per), ...Object.keys(hist)]))
      .filter(Boolean)
      .sort((a,b)=>pretty(bestLabel(perLabels[a]||histLabels[a], a)).localeCompare(pretty(bestLabel(perLabels[b]||histLabels[b], b))));

    const tbd = document.querySelector('#tblDocs tbody');
    if(tbd){
      tbd.innerHTML = tipos.map(t=>`
        <tr>
          <td>${pretty(bestLabel(perLabels[t]||histLabels[t], t))}</td>
          <td>${Number(per[t]||0)}</td>
          <td>${Number(hist[t]||0)}</td>
        </tr>
      `).join('');
    }

    const totPer = Object.values(per).reduce((a,b)=>a+Number(b||0),0);
    const elTot = document.getElementById('docsTotales');
    const elH = document.getElementById('docsTotalesHistorico');
    if(elTot) elTot.textContent = `Total docs: ${totPer}`;
    if(elH) elH.textContent = `Histórico: ${totHist}`;

    try{
      const users = rows.length;
      const opsTot = rows.reduce((a,b)=>a + Number(b.total||0), 0);
      const docsTot = rows.reduce((a,b)=>a + Number(b.docs_total||0), 0);
      const pzsEntTot = rows.reduce((a,b)=>a + Number(b.pzsEnt||0), 0);
      const pzsSalTot = rows.reduce((a,b)=>a + Number(b.pzsSal||0), 0);
      const docsDiaTot = Math.round((docsTot / (_days||1))*10)/10;

      const setK = (id,val)=>{ const el=document.getElementById(id); if(el) el.textContent = String(val); };
      setK('kpiProdUsers', users);
      setK('kpiProdOps', opsTot);
      setK('kpiProdDocs', docsTot);
      setK('kpiProdPzsEnt', pzsEntTot);
      setK('kpiProdPzsSal', pzsSalTot);
      setK('kpiProdDocsDia', docsDiaTot);

      const top = rows.slice().sort((a,b)=>Number(b.total||0)-Number(a.total||0)).slice(0,12);
      const labels = top.map(x=>x.usuario);
      const valsOps = top.map(x=>Number(x.total||0));
      const valsDocs = top.map(x=>Number(x.docs_total||0));
      const valsPzsSal = top.map(x=>Number(x.pzsSal||0));

      const cv = document.getElementById('chartProdUsuarios');
      if(cv && window.Chart){
        try{ if(window.__chartProdUsuarios){ window.__chartProdUsuarios.destroy(); } }catch(_){ }
        window.__chartProdUsuarios = new Chart(cv.getContext('2d'), {
          data: {
            labels,
            datasets: [
              { type:'bar', label: 'Operaciones', data: valsOps },
              { type:'line', label: 'Docs (folios)', data: valsDocs, tension:.25 },
              { type:'line', label: 'Pzs salidas', data: valsPzsSal, tension:.25, yAxisID:'y1' }
            ]
          },
          options: {
            responsive:true,
            maintainAspectRatio:false,
            interaction:{ mode:'index', intersect:false },
            plugins:{ legend:{ display:true }},
            scales:{
              x:{ ticks:{ autoSkip:false, maxRotation:45, minRotation:0 } },
              y:{ beginAtZero:true, title:{ display:true, text:'Operaciones / Docs' } },
              y1:{ beginAtZero:true, position:'right', grid:{ drawOnChartArea:false }, title:{ display:true, text:'Piezas salidas' } }
            }
          }
        });
      }
    }catch(_){ }

    try{
      await drawProductividadMedicos({ desde, hasta, q, salidas: salidasAll });
    }catch(_){ }
  }catch(e){
    console.warn('Error drawProductividad', e);
    const resumen = document.getElementById('prodResumen');
    if(resumen) resumen.textContent = 'Error al calcular productividad.';
    throw e;
  }
}

async function drawProductividadMedicos(opts={}){
  try{
    const hoy = _todayYMD();
    const desde = (opts.desde || document.getElementById('prodDesde')?.value || hoy).trim();
    const hasta = (opts.hasta || document.getElementById('prodHasta')?.value || hoy).trim();
    const q = (opts.q != null ? String(opts.q) : String(document.getElementById('prodBusca')?.value||'')).trim().toLowerCase();
    const norm = (s)=> String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/\s+/g,' ');
    const pretty = (s)=> String(s||'').toLowerCase().replace(/\b([a-záéíóúñ])/g, m=>m.toUpperCase());
    const esc = (s)=>String(s??'').replace(/[&<>"']/g, ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));
    const normTipo = (v)=>{
      const t = norm(v);
      if(t.includes('receta carta') || t.includes('receta media carta') || t.includes('receta ordinaria')) return 'ordinaria';
      if(t.includes('receta antibiot')) return 'antibioticos';
      if(t.includes('colectivo ordinario')) return 'colectivo_ordinario';
      if(t.includes('colectivo justificado')) return 'colectivo_justificado';
      return '';
    };
    const normEstado = (v)=>{
      const t = norm(v);
      if(t.includes('incompleta')) return 'incompleta';
      if(t.includes('completa')) return 'completa';
      return 'sin estado';
    };
    const pickMed = (row)=>{
      const m = String(row?.medico || row?.doctor || row?.nombre_medico || '').trim();
      if(m) return m;
      return 'SIN MÉDICO CAPTURADO';
    };

    let salidas = Array.isArray(opts.salidas) ? opts.salidas : [];
    if(!Array.isArray(opts.salidas)){
      try{ salidas = await idbAll('salidas'); }catch(e){ salidas = []; }
    }

    const porDoc = {};
    for(const s of (salidas||[])){
      const f = _parseYMDorDDMM(s.fecha);
      if(!f || f < desde || f > hasta) continue;
      const tipo = normTipo(s.tipo_doc || s.tipo || '');
      if(!tipo) continue;
      const folio = String(s.folio||'').trim().toUpperCase();
      if(!folio) continue;
      const medicoRaw = pickMed(s);
      const medicoNorm = norm(medicoRaw) || 'sin medico capturado';
      if(q && !(medicoNorm.includes(q) || folio.toLowerCase().includes(q) || norm(String(s.tipo_doc||'')).includes(q))) continue;
      const estado = normEstado(s.estado || s.estatus || '');
      const key = `${tipo}||${folio}`;
      if(!porDoc[key]){
        porDoc[key] = {
          tipo, folio, medicoNorm, medicoRaw, estados:{completa:0,incompleta:0,'sin estado':0},
          fecha:f, latest:String(s.fecha||''), lineas:0
        };
      }
      const d = porDoc[key];
      d.lineas += 1;
      d.estados[estado] = Number(d.estados[estado]||0) + 1;
      if(String(s.fecha||'') > String(d.latest||'')){
        d.latest = String(s.fecha||'');
        d.fecha = f;
        if(medicoRaw && d.medicoRaw === 'SIN MÉDICO CAPTURADO'){
          d.medicoRaw = medicoRaw;
          d.medicoNorm = medicoNorm;
        }
      }
    }

    const agg = {};
    Object.values(porDoc).forEach(doc=>{
      const key = doc.medicoNorm || 'sin medico capturado';
      if(!agg[key]) agg[key] = {
        medico: doc.medicoRaw || 'SIN MÉDICO CAPTURADO', recetas:0, ord:0, ordComp:0, ordIncomp:0, ab:0, abComp:0, abIncomp:0, colOrd:0, colJust:0, comp:0, incomp:0, sinEstado:0, ultima:''
      };
      const a = agg[key];
      a.recetas += 1;
      const finalEstado = doc.estados.incompleta > 0 ? 'incompleta' : (doc.estados.completa > 0 ? 'completa' : 'sin estado');
      if(doc.tipo === 'ordinaria'){
        a.ord += 1;
        if(finalEstado === 'completa') a.ordComp += 1;
        else if(finalEstado === 'incompleta') a.ordIncomp += 1;
      }else if(doc.tipo === 'antibioticos'){
        a.ab += 1;
        if(finalEstado === 'completa') a.abComp += 1;
        else if(finalEstado === 'incompleta') a.abIncomp += 1;
      }else if(doc.tipo === 'colectivo_ordinario'){
        a.colOrd += 1;
      }else if(doc.tipo === 'colectivo_justificado'){
        a.colJust += 1;
      }
      if(finalEstado === 'completa') a.comp += 1;
      else if(finalEstado === 'incompleta') a.incomp += 1;
      else a.sinEstado += 1;
      if(!a.ultima || String(doc.latest||'') > String(a.ultima||'')) a.ultima = String(doc.latest||'');
    });

    const rows = Object.values(agg).map(r=>{
      const evaluadas = Number(r.comp||0) + Number(r.incomp||0);
      const pct = evaluadas ? Math.round((Number(r.comp||0) / evaluadas) * 1000)/10 : 0;
      return { ...r, pctComp: pct };
    }).sort((a,b)=> Number(b.recetas||0)-Number(a.recetas||0) || String(a.medico||'').localeCompare(String(b.medico||'')));

    window.__prodMedStats = {
      desde, hasta, rows,
      resumen: {
        medicos: rows.filter(r=>norm(r.medico) !== 'sin medico capturado').length,
        recetas: rows.reduce((a,b)=>a+Number(b.recetas||0),0),
        ord: rows.reduce((a,b)=>a+Number(b.ord||0),0),
        ab: rows.reduce((a,b)=>a+Number(b.ab||0),0),
        colOrd: rows.reduce((a,b)=>a+Number(b.colOrd||0),0),
        colJust: rows.reduce((a,b)=>a+Number(b.colJust||0),0),
        comp: rows.reduce((a,b)=>a+Number(b.comp||0),0),
        incomp: rows.reduce((a,b)=>a+Number(b.incomp||0),0),
        sinEstado: rows.reduce((a,b)=>a+Number(b.sinEstado||0),0)
      }
    };

    const tb = document.querySelector('#tblProdMed tbody');
    if(tb){
      tb.innerHTML = rows.map(r=>`
        <tr>
          <td>${esc(pretty(r.medico))}</td>
          <td>${Number(r.recetas||0)}</td>
          <td>${Number(r.ord||0)}</td>
          <td>${Number(r.ordComp||0)}</td>
          <td>${Number(r.ordIncomp||0)}</td>
          <td>${Number(r.ab||0)}</td>
          <td>${Number(r.abComp||0)}</td>
          <td>${Number(r.abIncomp||0)}</td>
          <td>${Number(r.colOrd||0)}</td>
          <td>${Number(r.colJust||0)}</td>
          <td>${Number(r.pctComp||0)}%</td>
          <td>${_fmtISOtoDMYHM(r.ultima)}</td>
        </tr>
      `).join('');
    }

    const setK = (id,val)=>{ const el=document.getElementById(id); if(el) el.textContent = String(val); };
    setK('kpiProdMedicos', window.__prodMedStats.resumen.medicos);
    setK('kpiProdRecetas', window.__prodMedStats.resumen.recetas);
    setK('kpiProdRecOrd', window.__prodMedStats.resumen.ord);
    setK('kpiProdRecAb', window.__prodMedStats.resumen.ab);
    setK('kpiProdColOrd', window.__prodMedStats.resumen.colOrd);
    setK('kpiProdColJust', window.__prodMedStats.resumen.colJust);
    setK('kpiProdRecComp', window.__prodMedStats.resumen.comp);
    setK('kpiProdRecIncomp', window.__prodMedStats.resumen.incomp);

    const nota = document.getElementById('prodMedNota');
    if(nota){
      nota.textContent = `Se cuenta 1 receta por folio único dentro del historial de salidas. El estado final del folio se toma como incompleta si alguna línea del folio quedó incompleta; si no, completa cuando exista al menos una línea completa.`;
    }
    const resumen = document.getElementById('prodMedResumen');
    if(resumen){
      resumen.textContent = `Periodo: ${_fmtYMD(desde)} a ${_fmtYMD(hasta)} · Folios: ${window.__prodMedStats.resumen.recetas}`;
    }

    try{
      const top = rows.filter(r=>norm(r.medico) !== 'sin medico capturado').slice(0,12);
      const labels = (top.length?top:rows.slice(0,12)).map(r=>pretty(r.medico));
      const valsRec = (top.length?top:rows.slice(0,12)).map(r=>Number(r.recetas||0));
      const valsComp = (top.length?top:rows.slice(0,12)).map(r=>Number(r.comp||0));
      const valsIncomp = (top.length?top:rows.slice(0,12)).map(r=>Number(r.incomp||0));
      const cv = document.getElementById('chartProdMedicos');
      if(cv && window.Chart){
        try{ if(window.__chartProdMedicos){ window.__chartProdMedicos.destroy(); } }catch(_){ }
        window.__chartProdMedicos = new Chart(cv.getContext('2d'), {
          data:{
            labels,
            datasets:[
              { type:'bar', label:'Recetas', data: valsRec },
              { type:'line', label:'Completas', data: valsComp, tension:.25 },
              { type:'line', label:'Incompletas', data: valsIncomp, tension:.25 }
            ]
          },
          options:{ responsive:true, maintainAspectRatio:false, interaction:{mode:'index',intersect:false}, plugins:{legend:{display:true}}, scales:{ y:{ beginAtZero:true } } }
        });
      }
      const cv2 = document.getElementById('chartProdMedEstado');
      if(cv2 && window.Chart){
        try{ if(window.__chartProdMedEstado){ window.__chartProdMedEstado.destroy(); } }catch(_){ }
        window.__chartProdMedEstado = new Chart(cv2.getContext('2d'), {
          type:'doughnut',
          data:{ labels:['Completas','Incompletas','Sin estado'], datasets:[{ data:[window.__prodMedStats.resumen.comp, window.__prodMedStats.resumen.incomp, window.__prodMedStats.resumen.sinEstado] }] },
          options:{ responsive:true, maintainAspectRatio:false, plugins:{ legend:{display:true} } }
        });
      }
    }catch(_){ }
  }catch(e){
    console.warn('Error drawProductividadMedicos', e);
  }
}

async function mxExportProdMedExcel(){
  try{
    if(!window.__prodMedStats || !Array.isArray(window.__prodMedStats.rows)) await drawProductividadMedicos();
    const st = window.__prodMedStats || {rows:[],resumen:{}};
    const pretty = (s)=> String(s||'').toLowerCase().replace(/\b([a-záéíóúñ])/g, m=>m.toUpperCase());
    const resumen = [{
      DESDE: st.desde || '', HASTA: st.hasta || '',
      MEDICOS_DETECTADOS: st.resumen?.medicos || 0, FOLIOS_TOTALES: st.resumen?.recetas || 0, ORDINARIAS: st.resumen?.ord || 0, ANTIBIOTICOS: st.resumen?.ab || 0, COLECTIVO_ORDINARIO: st.resumen?.colOrd || 0, COLECTIVO_JUSTIFICADO: st.resumen?.colJust || 0, COMPLETAS: st.resumen?.comp || 0, INCOMPLETAS: st.resumen?.incomp || 0, SIN_ESTADO: st.resumen?.sinEstado || 0
    }];
    const detalle = (st.rows||[]).map(r=>( {
      MEDICO: pretty(r.medico), FOLIOS: r.recetas, ORDINARIAS: r.ord, ORDINARIAS_COMPLETAS: r.ordComp, ORDINARIAS_INCOMPLETAS: r.ordIncomp, ANTIBIOTICOS: r.ab, ANTIBIOTICOS_COMPLETAS: r.abComp, ANTIBIOTICOS_INCOMPLETAS: r.abIncomp, COLECTIVO_ORDINARIO: r.colOrd, COLECTIVO_JUSTIFICADO: r.colJust, PORC_COMPLETAS: `${r.pctComp}%`, FECHA_ULTIMO_REGISTRO: _fmtISOtoDMYHM(r.ultima)
    }));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(resumen), 'Resumen');
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(detalle.length?detalle:[{INFO:'Sin datos'}]), 'Detalle_medicos');
    XLSX.writeFile(wb, `productividad_medicos_${st.desde||_todayYMD()}_a_${st.hasta||_todayYMD()}.xlsx`);
  }catch(e){ mxAlert('No se pudo exportar Excel de médicos.'); }
}

async function mxExportProdMedPdf(){
  try{
    if(!window.__prodMedStats || !Array.isArray(window.__prodMedStats.rows)) await drawProductividadMedicos();
    const st = window.__prodMedStats || {rows:[],resumen:{}};
    const pretty = (s)=> String(s||'').toLowerCase().replace(/\b([a-záéíóúñ])/g, m=>m.toUpperCase());
    const { jsPDF } = window.jspdf || {};
    if(!jsPDF){ mxAlert('PDF no disponible.'); return; }
    const doc = new jsPDF({ orientation:'landscape', unit:'pt', format:'letter' });
    const pad = 28;
    doc.setFont('helvetica','bold');
    doc.setFontSize(16);
    doc.text('Productividad por médico', pad, 30);
    doc.setFont('helvetica','normal');
    doc.setFontSize(10);
    doc.text(`Periodo: ${_fmtYMD(st.desde||'')} a ${_fmtYMD(st.hasta||'')}`, pad, 46);
    doc.text(`Folios: ${st.resumen?.recetas||0} · Ordinarias: ${st.resumen?.ord||0} · Antibióticos: ${st.resumen?.ab||0} · Col. ord.: ${st.resumen?.colOrd||0} · Col. just.: ${st.resumen?.colJust||0} · Completas: ${st.resumen?.comp||0} · Incompletas: ${st.resumen?.incomp||0}`, pad, 60);
    try{
      const cv = document.getElementById('chartProdMedicos');
      if(cv){
        const img = cv.toDataURL('image/png', 1.0);
        doc.addImage(img, 'PNG', pad, 74, 430, 220);
      }
      const cv2 = document.getElementById('chartProdMedEstado');
      if(cv2){
        const img2 = cv2.toDataURL('image/png', 1.0);
        doc.addImage(img2, 'PNG', 480, 92, 250, 180);
      }
    }catch(_){ }
    const body = (st.rows||[]).slice(0,25).map(r=>[pretty(r.medico), r.recetas, r.ord, r.ab, r.colOrd, r.colJust, r.comp, r.incomp, `${r.pctComp}%`, _fmtISOtoDMYHM(r.ultima)]);
    if(doc.autoTable){
      doc.autoTable({
        startY: 310,
        head: [['Médico','Folios','Ord','Ab','Col. ord.','Col. just.','Comp','Incomp','% completas','Último registro']],
        body: body.length?body:[['Sin datos','','','','','','','','','']],
        styles:{ fontSize:8, cellPadding:4, overflow:'linebreak' },
        headStyles:{ fillColor:[30,64,175] }
      });
    }
    window.mxStampPdfEstablishmentV156?.(doc);doc.save(`productividad_medicos_${st.desde||_todayYMD()}_a_${st.hasta||_todayYMD()}.pdf`);
  }catch(e){ mxAlert('No se pudo exportar PDF de médicos.'); }
}

let __mxProdRefreshRunning = false;
async function mxActualizarProductividad(){
  if(__mxProdRefreshRunning) return;
  __mxProdRefreshRunning = true;
  const btn = document.getElementById('btnActualizarProd');
  const resumen = document.getElementById('prodResumen');
  const oldText = btn?.innerHTML || '🔄 Actualizar';
  try{
    if(btn){ btn.disabled = true; btn.innerHTML = '⏳ Actualizando…'; }
    if(resumen) resumen.textContent = 'Leyendo Entradas y Salidas…';
    await new Promise(resolve=>requestAnimationFrame(()=>resolve()));
    if(typeof ensureDBReady === 'function') await ensureDBReady();
    await drawProductividad({force:true});
  }catch(e){
    console.warn('No se pudo actualizar productividad', e);
    if(resumen) resumen.textContent = 'No se pudo calcular la productividad.';
    await mxAlert('No se pudo actualizar Productividad. Revisa que Entradas y Salidas estén disponibles.');
  }finally{
    if(btn){ btn.disabled = false; btn.innerHTML = oldText; }
    __mxProdRefreshRunning = false;
  }
}
