function mxSalidaQueueTreatmentSave(product,data,loaded={}){
  const prev=window.__mxManualTreatmentSaveQueue||Promise.resolve();
  // v1.0.147: la sincronización clínica remota sigue ocurriendo, pero fuera de la
  // ruta crítica de selección/finalización para no competir con la captura.
  const task=Promise.resolve(prev).catch(()=>{}).then(()=>new Promise(resolve=>{
    const run=()=>Promise.resolve(mxSalidaManualTreatmentSave(product,data,loaded)).then(resolve).catch(()=>resolve(false));
    try{ if(typeof requestIdleCallback==='function') requestIdleCallback(run,{timeout:500}); else setTimeout(run,120); }
    catch(_e){ setTimeout(run,120); }
  }));
  window.__mxManualTreatmentSaveQueue=task.catch(e=>{console.warn('[SALIDAS][TRATAMIENTO MANUAL][COLA]',e);return false});
  return task;
}
