  const doseValue=screen.dosisIndicadaValor||Number(prior.dosisIndicadaValor)||0,hoursValue=screen.dosisCadaHoras||Number(prior.dosisCadaHoras)||0,daysValue=screen.tiempoTratamientoDias||Number(prior.tiempoTratamientoDias)||0;
  const inferred=String(screen.dosisUnidad||prior.dosisUnidad||mxSalidaInferDoseUnit(product)||'').toUpperCase(),hasPrior=!!(doseValue>0&&hoursValue>0&&daysValue>0);
