function mxSetCjFieldValue(id,value){
  const el=document.getElementById(id);if(!el)return;const raw=String(value??'').trim();
  if(el.tagName==='SELECT'){
    const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toUpperCase();
    const option=Array.from(el.options||[]).find(o=>norm(o.value)===norm(raw)||norm(o.textContent)===norm(raw));el.value=option?option.value:'';
  }else el.value=raw;
}
