function mxRefreshCjServiceSelect(preferredValue=''){
  const sel=document.getElementById('salServicioJ');
  if(!sel||sel.tagName!=='SELECT')return;
  const current=String(preferredValue||sel.value||'').trim();
  const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toUpperCase();
  let rows=[];
  try{rows=(window.mxLoadServiciosUnidad?.()||[]).filter(x=>x&&x.activo!==false&&String(x.nombre||'').trim());}catch(_e){rows=[];}
  const unique=[];const seen=new Set();
  rows.forEach(x=>{const nombre=String(x.nombre||'').trim();const key=norm(nombre);if(!nombre||seen.has(key))return;seen.add(key);unique.push({nombre,iniciales:String(x.iniciales||'').trim()});});
  sel.innerHTML='<option value="">Selecciona servicio</option>'+unique.map(x=>`<option value="${String(x.nombre).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}">${String(x.nombre).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}${x.iniciales?` (${String(x.iniciales).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')})`:''}</option>`).join('');
  if(current){
    const match=Array.from(sel.options).find(o=>norm(o.value)===norm(current)||norm(o.textContent.split(' (')[0])===norm(current));
    if(match)sel.value=match.value;
    else{const opt=document.createElement('option');opt.value=current;opt.textContent=`${current} (histórico)`;sel.appendChild(opt);sel.value=current;}
  }
}
