let __mxLastFolioWarning = '';

function mxNormalizeTipoSalida(tipo){
  const raw = String(tipo||'').trim();
  if(!raw) return '';
  const n = raw
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase()
    .replace(/\s+/g,' ')
    .trim();

  if(n === 'receta carta') return 'Receta Carta';
  if(n === 'receta media carta' || n === 'receta media-carta') return 'Receta Media carta';
  if(n === 'receta ordinaria') return 'Receta ordinaria';
  if(n === 'receta antibioticos' || n === 'receta antibioticos') return 'Receta antibióticos';
  if(n === 'colectivo justificado') return 'Colectivo justificado';
  return raw;
}

function mxGetSalFolioHintEl(){
  return document.getElementById('salFolioHint');
}

function mxGetSalTipoFolioInfoEl(){
  return document.getElementById('salTipoFolioInfo');
}

function mxSetSalTipoFolioInfo(msg, tone='info'){
  const el = mxGetSalTipoFolioInfoEl();
  if(!el) return;
  if(!msg){
    el.style.display = 'none';
    el.textContent = '';
    return;
  }
  const map = {
    ok:   {bg:'#ecfdf5', bd:'#86efac', fg:'#166534'},
    info: {bg:'#eef2ff', bd:'#c7d2fe', fg:'#3730a3'},
    warn: {bg:'#fffbeb', bd:'#fcd34d', fg:'#92400e'}
  };
  const s = map[tone] || map.info;
  el.style.display = 'block';
  el.style.background = s.bg;
  el.style.border = '1px solid ' + s.bd;
  el.style.color = s.fg;
  el.textContent = msg;
}

function mxTodayDDMMYYYY(){
  const d = new Date();
  const dd = String(d.getDate()).padStart(2,'0');
  const mm = String(d.getMonth()+1).padStart(2,'0');
  const yy = d.getFullYear();
  return `${dd}${mm}${yy}`;
}

function mxPadSalidaConsecutivo(value, minWidth=4){
  const raw=String(value??'').trim();
  if(!/^\d+$/.test(raw)) return raw;
  const next=String(Math.max(0,Number(raw)||0));
  return next.padStart(Math.max(Number(minWidth)||4,raw.length), '0');
}
function mxNormalizarCerosFolioSalida(value, tipoDoc=''){
  const raw=String(value??'').trim();
  if(!raw) return raw;
  const tipo=mxNormalizeTipoSalida(tipoDoc);
  if(!mxTipoSalidaRequiereFolioInteligente(tipo)) return raw;
  let m=raw.match(/^A-(\d+)(-.*)$/i);
  if(m) return `A-${mxPadSalidaConsecutivo(m[1],4)}${m[2]}`;
  m=raw.match(/^(\d+)(-.*)$/);
  if(m) return `${mxPadSalidaConsecutivo(m[1],4)}${m[2]}`;
  return raw;
}
function mxAplicarCerosFolioSalida(input){
  const inp=input||document.getElementById('salFolioDoc');
  const tipo=document.getElementById('salTipo')?.value||'';
  if(!inp) return '';
  const before=String(inp.value||'').trim();
  const after=mxNormalizarCerosFolioSalida(before,tipo);
  if(after && after!==before){
    inp.value=after;
    try{ inp.dispatchEvent(new Event('input',{bubbles:true})); }catch(_e){}
  }
  return after||before;
}
window.mxAplicarCerosFolioSalida=mxAplicarCerosFolioSalida;

async function mxGetUltimoFolioRegistradoPorTipo(tipo){
  // Respaldo de arranque: el historial de Salidas NO es autoridad de folios.
  // folios-control.js sustituye esta función al cargar; mientras tanto se lee
  // únicamente el control central guardado por el administrador.
  try{
    const t=mxNormalizeTipoSalida(tipo);
    if(!t) return null;
    const keyMap={
      'Receta Carta':'RC',
      'Receta Media carta':'RMC',
      'Receta ordinaria':'RO',
      'Receta antibióticos':'RA',
      'Colectivo justificado':'CJ',
      'Colectivo ordinario':'CO',
      'Vale de salida':'VALE_DE_SALIDA'
    };
    const key=keyMap[t]||String(t).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,'_').replace(/^_+|_+$/g,'');
    let branch='HGAM';
    try{ branch=String(window.mxGetSucursalFromLicense?.()||'HGAM').trim().toUpperCase()||'HGAM'; }catch(_e){}
    const raw=JSON.parse(localStorage.getItem(`mx_folio_control_v3_${branch}`)||'null');
    const current=Math.max(0,Math.floor(Number(raw?.documents?.[key]?.current??raw?.documents?.[key]?.max??0)||0));
    return {folio:'',consecutivo:current,meta:{consecutivo:current},ts:0,ord:0};
  }catch(e){
    console.warn('No se pudo leer el control central de folios',e);
    return null;
  }
}

function mxTipoSalidaRequiereFolioInteligente(tipo){
  const t = mxNormalizeTipoSalida(tipo);
  return ['Receta Carta','Receta Media carta','Receta ordinaria','Receta antibióticos'].includes(t);
}

function mxBuildSiguienteFolioSalida(tipo, info){
  const t=mxNormalizeTipoSalida(tipo);
  const folioPrev=String(info?.folio||'').trim();
  const next=Number(info?.consecutivo||0)+1;
  let rawDigits='';
  if(t==='Receta antibióticos') rawDigits=(folioPrev.match(/^A-(\d+)/i)||[])[1]||'';
  else rawDigits=(folioPrev.match(/^(\d+)/)||[])[1]||'';
  const width=Math.max(4,rawDigits.length||0);
  const padded=String(next).padStart(width,'0');
  const fecha=mxTodayDDMMYYYY();
  if(t==='Receta antibióticos') return `A-${padded}-${fecha}`;
  return `${padded}-${fecha}`;
}

async function mxRefreshUltimoYSiguienteFolioSalida(){
  const tipoSel = document.getElementById('salTipo');
  if(!tipoSel) return;
  const tipo = mxNormalizeTipoSalida(tipoSel.value);
  if(!tipo || !mxTipoSalidaRequiereFolioInteligente(tipo)){
    mxSetSalTipoFolioInfo('');
    return;
  }
  const info = await mxGetUltimoFolioRegistradoPorTipo(tipo);
  if(!info){
    let base = '';
    const fecha = mxTodayDDMMYYYY();
    if(tipo === 'Receta antibióticos') base = `A-0001-${fecha}`;
    else if(['Receta Carta','Receta Media carta','Receta ordinaria'].includes(tipo)) base = `0001-${fecha}`;
    mxSetSalTipoFolioInfo(`Sin folios previos en ${tipo}. Siguiente sugerido: ${base}`, 'info');
    return;
  }
  const siguiente = mxBuildSiguienteFolioSalida(tipo, info);
  mxSetSalTipoFolioInfo(`Último folio en ${tipo}: ${info.folio} | Siguiente sugerido: ${siguiente}`, 'info');
}

