function _mxParseCadDate(cadStr){
  const s = String(cadStr||'').trim();
  if(!s) return null;
  let m;
  if((m = s.match(/^(\d{4})-(\d{2})-(\d{2})/))) return new Date(+m[1], +m[2]-1, +m[3]);
  if((m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/))) return new Date(+m[3], +m[2]-1, +m[1]);
  if((m = s.match(/^(\d{2})-(\d{2})-(\d{4})/))) return new Date(+m[3], +m[2]-1, +m[1]);
  if((m = s.match(/^(\d{4})\/(\d{2})\/(\d{2})/))) return new Date(+m[1], +m[2]-1, +m[3]);
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}
function _mxCadSemaforoInfoFromCadStr(cadStr){
  const cadDate = _mxParseCadDate(cadStr);
  if(!cadDate) return { cls:'mx-sema-na', title:'Sin caducidad' };
  const today = new Date(); today.setHours(0,0,0,0);
  const cd = new Date(cadDate); cd.setHours(0,0,0,0);
  const diffDays = Math.floor((cd - today) / 86400000);
  if (diffDays <= 90){
    const t = diffDays < 0 ? `Caducado (${Math.abs(diffDays)} días)` : `<= 3 meses (${diffDays} días)`;
    return { cls:'mx-sema-rojo', title: t };
  }
  if (diffDays <= 180){
    return { cls:'mx-sema-amarillo', title: `<= 6 meses (${diffDays} días)` };
  }
  return { cls:'mx-sema-verde', title: `> 6 meses (${diffDays} días)` };
}
function _mxSemDotHTML(cadStr){
  _mxEnsureSemaforoStyle();
  const info = _mxCadSemaforoInfoFromCadStr(cadStr);
  const cadTxt = String(cadStr||'').trim();
  const title = info.title + (cadTxt ? ` | Cad: ${cadTxt}` : '');
  return `<span class="mx-sema-dot ${info.cls}" title="${title.replace(/"/g,'&quot;')}"></span>`;
}

