let __mxAudioCtx = null;
function mxDoubleBeep(){
  try{
    const AC = window.AudioContext || window.webkitAudioContext;
    if(!AC) return;
    if(!__mxAudioCtx) __mxAudioCtx = new AC();
    const ctx = __mxAudioCtx;
    if(ctx.state === 'suspended') ctx.resume();
    const now = ctx.currentTime;

    const beep = (t0)=>{
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = 'sine';
      o.frequency.value = 880;
      g.gain.setValueAtTime(0.0001, t0);
      g.gain.exponentialRampToValueAtTime(0.18, t0 + 0.01);
      g.gain.exponentialRampToValueAtTime(0.0001, t0 + 0.09);
      o.connect(g); g.connect(ctx.destination);
      o.start(t0); o.stop(t0 + 0.10);
    };

    beep(now + 0.00);
    beep(now + 0.16); // doble bip-bip
  }catch(e){}
}


function mxSalidasNorm(v){
  return String(v ?? '')
    .trim()
    .toUpperCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/\s+/g,' ');
}


function mxSalidasClasificacionAntibiotica(v){
  try{
    const cls = mxSalidasNorm(v);
    // Validación estricta por CLASIFICACIÓN, no por descripción ni tipo de receta.
    return /(^|\s)ANTIBIOTIC[OA]S?(\s|$)/.test(cls);
  }catch(e){ return false; }
}

function mxSalidasClaveLoose(v){
  return String(v ?? '')
    .trim()
    .toUpperCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^A-Z0-9]/g,'');
}

function mxSalidasGetClasificacion(row){
  try{
    return row?.clasificacion ?? row?.clasificación ?? row?.CLASIFICACION ?? row?.['CLASIFICACIÓN'] ?? row?.['Clasificación'] ?? '';
  }catch(e){ return ''; }
}

function mxSalidasCatalogoClasifPorClave(clave){
  // Catálogo de Configuración: claves clasificadas como antibiótico.
  try{
    const k = mxSalidasClaveLoose(clave);
    if(!k) return null;
    if(typeof mxFindClasifCatalog === 'function'){
      const c = mxFindClasifCatalog(clave);
      if(c) return c;
    }
    const raw = localStorage.getItem('mx_clasif_catalog_v1');
    const arr = raw ? JSON.parse(raw) : [];
    if(!Array.isArray(arr)) return null;
    return arr.find(x => mxSalidasClaveLoose(x?.clave || x?.key || '') === k) || null;
  }catch(e){ return null; }
}

function mxSalidasEsAntibioticoRow(row){
  // 1) Inventario: Clasificación = Antibiótico.
  // 2) Configuración: catálogo de claves con clasificación Antibiótico.
  // Nunca valida por nombre/descrición/tipo de receta para evitar falsos positivos.
  try{
    if(!row) return false;
    if(mxSalidasClasificacionAntibiotica(mxSalidasGetClasificacion(row))) return true;
    const cat = mxSalidasCatalogoClasifPorClave(row.clave);
    if(cat && mxSalidasClasificacionAntibiotica(cat.clasificacion || cat.clasif || cat.tipo || '')) return true;
    return false;
  }catch(e){ return false; }
}


// Aviso operativo no bloqueante: antibióticos con más de 10 piezas SOLO en documentos tipo Receta.
// Los colectivos (justificado, ordinario u otros) quedan expresamente exentos.
let __mxSalAbExcesoTimer = 0;
function mxSalidasEnsureAbExcesoToast(){
  let box=document.getElementById('mxSalAbExcesoToast');
  if(box) return box;
  if(!document.getElementById('mxSalAbExcesoToastStyle')){
    const st=document.createElement('style');
    st.id='mxSalAbExcesoToastStyle';
    st.textContent=`
      @keyframes mxSalAbExcesoBlink{
        0%,100%{background:#991b1b;box-shadow:0 14px 38px rgba(153,27,27,.35),0 0 0 0 rgba(239,68,68,.58);transform:translateY(0) scale(1)}
        50%{background:#ef4444;box-shadow:0 18px 48px rgba(239,68,68,.48),0 0 0 8px rgba(239,68,68,.10);transform:translateY(-1px) scale(1.015)}
      }
      #mxSalAbExcesoToast{
        position:fixed;right:22px;bottom:24px;z-index:1000004;
        display:none;width:min(430px,calc(100vw - 32px));
        padding:13px 16px;border-radius:15px;border:2px solid rgba(255,255,255,.82);
        color:#fff;pointer-events:none;font-family:inherit;
        box-shadow:0 14px 38px rgba(153,27,27,.35);
      }
      #mxSalAbExcesoToast.show{display:block;animation:mxSalAbExcesoBlink .48s ease-in-out infinite}
      #mxSalAbExcesoToast .mx-ab-ex-title{font-size:16px;font-weight:1000;letter-spacing:.02em;line-height:1.1}
      #mxSalAbExcesoToast .mx-ab-ex-msg{margin-top:5px;font-size:12px;font-weight:800;line-height:1.3}
      @media(max-width:700px){#mxSalAbExcesoToast{right:12px;bottom:14px;width:calc(100vw - 24px)}}
    `;
    document.head.appendChild(st);
  }
  box=document.createElement('div');
  box.id='mxSalAbExcesoToast';
  box.setAttribute('role','status');
  box.setAttribute('aria-live','polite');
  box.innerHTML='<div class="mx-ab-ex-title"></div><div class="mx-ab-ex-msg"></div>';
  document.body.appendChild(box);
  return box;
}
function mxSalidasTipoConAvisoAb(tipo){
  const t=mxSalidasNorm(tipo);
  // Regla estricta: el aviso de más de 10 piezas aplica ÚNICAMENTE a recetas.
  // Nunca debe mostrarse en colectivos, vales ni cualquier otro documento,
  // incluso si por compatibilidad algún registro antiguo trae texto combinado.
  if(!t || t.includes('COLECTIVO')) return false;
  return new Set([
    'RECETA',
    'RECETA CARTA',
    'RECETA MEDIA CARTA',
    'RECETA ORDINARIA',
    'RECETA ANTIBIOTICOS'
  ]).has(t);
}
function mxSalidasMostrarAvisoAbExceso(data={}){
  try{
    const tipo=String(data.tipo||'').trim();
    // Defensa adicional: aunque esta función sea invocada por otra ruta,
    // jamás renderizar el aviso si el documento no es una receta válida.
    if(!mxSalidasTipoConAvisoAb(tipo)){
      try{document.getElementById('mxSalAbExcesoToast')?.classList.remove('show')}catch(_e){}
      return false;
    }
    const box=mxSalidasEnsureAbExcesoToast();
    const total=Math.max(0,Math.floor(Number(data.total)||0));
    const nombre=String(data.descripcion||data.clave||'ANTIBIÓTICO').trim();
    const title=box.querySelector('.mx-ab-ex-title');
    const msg=box.querySelector('.mx-ab-ex-msg');
    if(title) title.textContent=`⚠ ANTIBIÓTICO: ${total} PZS`;
    if(msg) msg.textContent=`Supera 10 piezas en ${tipo||'esta receta'}. ${nombre}`;
    clearTimeout(__mxSalAbExcesoTimer);
    box.classList.remove('show');
    void box.offsetWidth;
    box.classList.add('show');
    __mxSalAbExcesoTimer=setTimeout(()=>{try{box.classList.remove('show')}catch(_e){}},3000);
    return true;
  }catch(_e){ return false; }
}
function mxSalidasRowEsAntibioticoConCache(row){
  try{
    if(mxSalidasEsAntibioticoRow(row)) return true;
    const clave=String(row?.clave||'').trim();
    if(!clave) return false;
    try{
      const byClave=window.__mxInventoryByClave;
      if(byClave instanceof Map){
        const arr=byClave.get(clave)||[];
        if(arr.some(x=>mxSalidasEsAntibioticoRow(x))) return true;
      }
    }catch(_e){}
    try{
      if(Array.isArray(cacheInv) && cacheInv.some(x=>String(x?.clave||'').trim()===clave && mxSalidasEsAntibioticoRow(x))) return true;
    }catch(_e){}
    return false;
  }catch(_e){ return false; }
}
async function mxSalidasAvisarAntibioticoMas10(row){
  try{
    if(!row || !mxSalidasTipoConAvisoAb(row.tipo_doc||row.tipo)){
      try{document.getElementById('mxSalAbExcesoToast')?.classList.remove('show')}catch(_e){}
      return false;
    }
    if(!mxSalidasRowEsAntibioticoConCache(row)) return false;
    const clave=String(row.clave||'').trim();
    const folio=String(row.folio||'').trim();
    const tipoNorm=mxSalidasNorm(row.tipo_doc||row.tipo);
    let total=Math.max(0,Number(row.pzs||row.cantidad||0)||0);
    if(folio && typeof mxHistGetExactFolioFast==='function'){
      let rows=[];
      try{rows=await mxHistGetExactFolioFast('salidas',folio)}catch(_e){rows=[]}
      if(Array.isArray(rows) && rows.length){
        const same=rows.filter(r=>String(r?.clave||'').trim()===clave && mxSalidasNorm(r?.tipo_doc||r?.tipo)===tipoNorm);
        if(same.length){
          total=same.reduce((sum,r)=>sum+(Number(r?.pzs||r?.cantidad||0)||0),0);
          const op=String(row?._mxOpId||row?.op_id||'').trim();
          const id=Number(row?._id||0)||0;
          const included=same.some(r=>{
            const rop=String(r?._mxOpId||r?.op_id||'').trim();
            if(op && rop) return op===rop;
            return id>0 && Number(r?._id||0)===id;
          });
          if(!included) total+=(Number(row.pzs||row.cantidad||0)||0);
        }
      }
    }
    if(total>10){
      mxSalidasMostrarAvisoAbExceso({
        total,
        clave,
        descripcion:row.descripcion||row.nombre||'',
        tipo:String(row.tipo_doc||row.tipo||'')
      });
      return true;
    }
    return false;
  }catch(_e){ return false; }
}
