  const mxFolioOrderPieces=(o={})=>mxFolioItems(o).reduce((sum,it)=>sum+Math.max(0,Number(it?.cantidadSolicitadaAhora??it?.cantidadSolicitudActual??it?.cantidadPorRecibir??it?.cantidadRecibidaSolicitada??it?.cantidad24Horas??it?.cantidadSolicitada??it?.pzs??it?.cantidad??0)||0),0);
