function validarEntradasPrev(){
  const tipo = $('#entTipoDoc').value, folio = $('#entFolioDoc').value.trim();
  if(!tipo || !folio) return {ok:false, msg:'Selecciona tipo y captura folio antes de registrar.'};
  const financiero = (typeof window.mxFinancialEnabled==='function' && window.mxFinancialEnabled());
  const proveedor = String(document.getElementById('entProveedor')?.value || '').trim();
  if(financiero && !proveedor) return {ok:false, msg:'En modo Financiero selecciona un proveedor antes de registrar la Entrada. Si no existe, agrégalo en el módulo Proveedores.'};
  return {ok:true};
}


function formatearCaducidad(fecha){
  if(!fecha) return '';
  const f = String(fecha).trim().slice(0,10);
  if(/^\d{2}\/\d{2}\/\d{4}$/.test(f)) return f;
  if(/^\d{4}-\d{2}-\d{2}$/.test(f)){ const [y,m,d]=f.split('-'); return `${d}/${m}/${y}`; }
  if(/^\d{4}-\d{2}$/.test(f)){ const [y,m]=f.split('-'); return `01/${m}/${y}`; }
  const p = f.replace(/-/g,'/').split('/');
  if(p.length===3){
    let [d,m,y]=p; d=d.padStart(2,'0'); m=m.padStart(2,'0');
    if(y.length===2) y=`20${y}`; else if(y.length===3) y=`2${y}`;
    return `${d}/${m}/${y}`;
  }
  return f;
}
function mxEnterFieldVisible(el){
  if(!(el instanceof HTMLElement)) return false;
  if(el.disabled || el.readOnly) return false;
  if(el.getAttribute('aria-hidden')==='true' || el.getAttribute('tabindex')==='-1') return false;
  if(!el.isConnected || el.getClientRects().length===0) return false;
  const type=String(el.getAttribute('type')||'text').toLowerCase();
  if(['hidden','button','submit','reset','image','checkbox','radio','file','range','color'].includes(type)) return false;
  return ['INPUT','SELECT','TEXTAREA'].includes(el.tagName);
}
function mxEnterNavigationScope(el){
  const modal=el.closest('.modal.show, .modal[style*="display: flex"], .modal[style*="display:flex"]');
  if(modal) return modal;
  return el.closest('section.panel:not(.hidden), section:not(.hidden), form, main') || document;
}
function mxFocusNextField(current){
  try{
    if(!(current instanceof HTMLElement)) return false;
    const scope=mxEnterNavigationScope(current);
    const fields=Array.from(scope.querySelectorAll('input, select, textarea')).filter(mxEnterFieldVisible);
    const index=fields.indexOf(current);
    if(index<0) return false;
    const next=fields[index+1];
    if(!next) return false;
    try{ next.focus({preventScroll:true}); }catch(_e){ try{ next.focus(); }catch(__e){} }
    try{ next.scrollIntoView({block:'nearest',inline:'nearest',behavior:'auto'}); }catch(_e){}
    return document.activeElement===next;
  }catch(_e){ return false; }
}
window.mxFocusNextField=mxFocusNextField;

function activarEnterGlobal(){
  if(window.__mxEnterGlobalBound) return;
  window.__mxEnterGlobalBound=true;

  document.addEventListener('keydown',(e)=>{
    if(e.key!=='Enter' || e.defaultPrevented || e.isComposing) return;
    if(e.ctrlKey || e.altKey || e.metaKey || e.shiftKey) return;
    const el=e.target;
    if(!mxEnterFieldVisible(el)) return;
    /* En áreas de texto, Enter conserva el salto de línea normal. */
    if(el.tagName==='TEXTAREA') return;
    e.preventDefault();
    mxFocusNextField(el);
  });
}
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',activarEnterGlobal,{once:true});
else activarEnterGlobal();

let medEditId = null;
async function drawMedicos(){
  const q=($('#medBusca')?.value||'').toLowerCase();
  const data=(await idbAll('medicos'))
    .sort((a,b)=>toStr(a.nombre).localeCompare(toStr(b.nombre),'es',{sensitivity:'base'}));
  const rows=data.filter(m=>(toStr(m.nombre)+' '+toStr(m.cedula)+' '+toStr(m.telefono)).toLowerCase().includes(q));
  const tb=document.querySelector('#tblMed tbody');
  tb.innerHTML=rows.map(m=>`<tr>
    <td>${toStr(m.nombre)}</td>
    <td>${toStr(m.cedula)}</td>
    <td>${toStr(m.telefono)}</td>
    <td>${toStr(m.institucion)}</td>
    <td>${toStr(m.domicilio)}</td>
    <td>
      <button class="btn" data-ed="${m._id}">✏️</button>
      <button class="btn danger" data-del="${m._id}">🗑️</button>
    </td>
  </tr>`).join('');
  tb.querySelectorAll('[data-ed]').forEach(b=>b.onclick=()=>openMedModal(b.getAttribute('data-ed')));
  tb.querySelectorAll('[data-del]').forEach(b=>b.onclick=async()=>{
    const id=Number(b.getAttribute('data-del')); if(!await mxConfirm('¿Eliminar médico?')) return;
    await idbDelete('medicos', id); drawMedicos();
  });
}
