async function exportMedicosExcel(){
  try{
    await ensureDBReady();
    const all = await idbAll('medicos');
    const rows = (Array.isArray(all) ? all.slice() : [])
      .sort((a,b)=> Number(a?._id||0) - Number(b?._id||0))
      .map((m, idx)=>(
        {
          'NO.': idx + 1,
          'NOMBRE': toStr(m?.nombre),
          'CEDULA': toStr(m?.cedula),
          'TELEFONO': toStr(m?.telefono),
          'INSTITUCION': toStr(m?.institucion),
          'DOMICILIO': toStr(m?.domicilio)
        }
      ));

    if(!rows.length){
      mxAlert('No hay médicos para exportar.');
      return;
    }

    const ws = XLSX.utils.json_to_sheet(rows);
    ws['!cols'] = [
      {wch:8},
      {wch:42},
      {wch:18},
      {wch:18},
      {wch:28},
      {wch:36}
    ];

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Medicos');

    const now = new Date();
    const pad = n => String(n).padStart(2,'0');
    const stamp = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}_${pad(now.getHours())}-${pad(now.getMinutes())}`;
    XLSX.writeFile(wb, `MACROXEL_MEDICOS_${stamp}.xlsx`);
  }catch(e){
    console.error('Error exportando médicos', e);
    mxAlert('No se pudo exportar el listado de médicos.');
  }
}

