let salQuickMedTarget = 'ab';
function openSalQuickMedModal(target){
  salQuickMedTarget = (target === 'j' || target === 'ord') ? target : 'ab';
  const nameId = salQuickMedTarget === 'j' ? 'salMedicoJ' : (salQuickMedTarget === 'ord' ? 'salMedicoOrd' : 'salMedicoAb');
  const cedId  = salQuickMedTarget === 'j' ? 'salCedulaJ' : (salQuickMedTarget === 'ord' ? 'salCedulaOrd' : 'salCedulaAb');
  document.getElementById('salQuickMedNombre').value = document.getElementById(nameId)?.value?.trim() || '';
  document.getElementById('salQuickMedCedula').value = document.getElementById(cedId)?.value?.trim() || '';
  document.getElementById('salQuickMedTelefono').value = '';
  document.getElementById('salQuickMedInst').value = '';
  document.getElementById('salQuickMedModal').classList.add('show');
  setTimeout(()=>{ try{ document.getElementById('salQuickMedNombre').focus(); }catch(e){} }, 30);
}
