async function depurarInventarioUnicoLote(){
  await ensureDBReady();
  const user = (typeof getLoggedUserLabel==='function' ? getLoggedUserLabel() : (currentUser||'')).toString().trim() || '—';
  const ok = await mxConfirm('Depurar Inventario:\n\n- Se dejará 1 registro por CLAVE + LOTE\n- Si existen duplicados, se SUMARÁN existencias\n- También se sumarán Almacén, Estantes, Entradas, Salidas y Existencia base\n\n¿Deseas continuar?');
  if(!ok) return;

  const inv = await idbAll('inventory');
  if(!inv || !inv.length){
    mxAlert('Inventario vacío. No hay nada que depurar.');
    return;
  }

  function norm(v){ return String(v||'').trim(); }
  function normKey(v){ return norm(v).toUpperCase(); }
  function num(v){ const n = Number(v||0); return isFinite(n) ? n : 0; }
  function pickCad(a,b){
    const A = norm(a), B = norm(b);
    if(!A && B) return B;
    if(A && !B) return A;
    if(!A && !B) return '';
    const toDate = (s)=>{
      try{
        if(/^\d{2}\/\d{2}\/\d{4}$/.test(s)){
          const [d,m,y]=s.split('/').map(x=>parseInt(x,10));
          return new Date(y, (m||1)-1, d||1);
        }
        if(/^\d{4}-\d{2}(-\d{2})?$/.test(s)){
          const p=s.split('-').map(x=>parseInt(x,10));
          return new Date(p[0], (p[1]||1)-1, p[2]||1);
        }
        const dt = new Date(s);
        return isNaN(dt.getTime()) ? null : dt;
      }catch(e){ return null; }
    };
    const da = toDate(A), db = toDate(B);
    if(da && db) return (da.getTime() <= db.getTime()) ? A : B;
    return A || B;
  }

  const map = new Map();

  for(const row of inv){
    const clave = norm(row.clave || row.codigo || row.id || '');
    const lote  = norm(row.lote || '');
    if(!clave) continue;

    const key = `${normKey(clave)}|${normKey(lote)}`;

    if(!map.has(key)){
      const base = { ...row };
      delete base._id; delete base._rev;
      base.clave = clave;
      base.lote = lote;
      base.almacen    = num(base.almacen);
      base.estantes   = num(base.estantes);
      base.entradas   = num(base.entradas);
      base.salidas    = num(base.salidas);
      base.base_exist = num(base.base_exist);
      base.existencia = num(base.existencia || (base.almacen + base.estantes));
      map.set(key, base);
      continue;
    }

    const base = map.get(key);
    base.almacen    = num(base.almacen)    + num(row.almacen);
    base.estantes   = num(base.estantes)   + num(row.estantes);
    base.entradas   = num(base.entradas)   + num(row.entradas);
    base.salidas    = num(base.salidas)    + num(row.salidas);
    base.base_exist = num(base.base_exist) + num(row.base_exist);
    base.existencia = num(base.existencia) + num(row.existencia || (num(row.almacen) + num(row.estantes)));

    if(!norm(base.descripcion) && norm(row.descripcion)) base.descripcion = row.descripcion;
    if(!norm(base.unidad) && norm(row.unidad)) base.unidad = row.unidad;
    if(!norm(base.clasificacion) && norm(row.clasificacion)) base.clasificacion = row.clasificacion;
    if(!norm(base.restriccion) && norm(row.restriccion)) base.restriccion = row.restriccion;
    if(!norm(base.ubicacion) && norm(row.ubicacion)) base.ubicacion = row.ubicacion;

    base.caducidad = pickCad(base.caducidad, row.caducidad);
    map.set(key, base);
  }

  const unique = Array.from(map.values()).map(o=>{
    const c = { ...o };
    c.almacen    = num(c.almacen);
    c.estantes   = num(c.estantes);
    c.entradas   = num(c.entradas);
    c.salidas    = num(c.salidas);
    c.base_exist = num(c.base_exist);
    c.existencia = num(c.existencia || (c.almacen + c.estantes));
    delete c._id; delete c._rev;
    return c;
  });

  if(unique.length === inv.length){
    mxAlert('No se encontraron repetidos por CLAVE + LOTE. Inventario ya está depurado.');
    return;
  }

  const fusionados = inv.length - unique.length;
  const ok2 = await mxConfirm(`Se encontraron ${fusionados} registros repetidos.\n\nAntes: ${inv.length} registros\nDespués: ${unique.length} registros\n\n¿Confirmas depurar y sumar existencias?`);
  if(!ok2) return;

  if(typeof window.mxReplaceStoreSafely==='function') await window.mxReplaceStoreSafely('inventory',unique);
  else { await idbClear('inventory'); await idbBulkPut('inventory',unique); }
mxAlert('✅ Inventario depurado correctamente. Se unificaron repetidos y se sumaron existencias.');
  if (typeof drawInventario === 'function') drawInventario();
  if (typeof renderDashboard === 'function') renderDashboard();
}

(function(){
  const b = document.getElementById('btnDepurarInv');
  if(b){
    b.onclick = depurarInventarioUnicoLote;
  }
})();
document.getElementById('btnExportInv').onclick = async function exportarTodoExcel() {
  try{
    await ensureDBReady();

    const inventario   = await idbAll('inventory');
    const entradas     = await idbAll('entradas');
    const salidas      = await idbAll('salidas');
    const antibioticos = await idbAll('antibioticos');

    function limpiar(obj) {
      const o = { ...obj };
      delete o._id; delete o._rev; delete o.user; delete o.creadoEn; delete o.actualizadoEn;
      return o;
    }

    const pick = (o, keys)=>{ for(const k of keys){ if(o && o[k]!=null && o[k]!=='' ) return o[k]; } return ''; };
    const toNum = (v)=>{ const n = Number(String(v ?? '').replace(/[^0-9\-\.]/g,'')); return isNaN(n) ? 0 : n; };
    const txt = (v)=> String(v ?? '').trim();

    function getExistenciaPartes(r){
      const alm = toNum(pick(r,['almacen','ALMACEN','almacén','ALMACÉN','pzs_almacen','existenciaAlmacen','alm']));
      const est = toNum(pick(r,['estantes','ESTANTES','estante','ESTANTE','pzs_estantes','existenciaEstante','est']));
      const tienePartes = !!(r && (
        r.almacen != null || r.ALMACEN != null || r['almacén'] != null || r['ALMACÉN'] != null ||
        r.estantes != null || r.ESTANTES != null || r.estante != null || r.ESTANTE != null ||
        r.pzs_almacen != null || r.pzs_estantes != null || r.existenciaAlmacen != null || r.existenciaEstante != null
      ));
      const ex = toNum(pick(r,['existencia','EXISTENCIA','existencias','EXISTENCIAS','stock','STOCK']));
      return { almacen: alm, estantes: est, existencia: tienePartes ? (alm + est) : ex };
    }

    function getExistenciaTotal(r){
      return getExistenciaPartes(r).existencia;
    }

    function parseCadDate(cadStr){
      const s = txt(cadStr);
      if(!s) return null;
      let m;
      if((m = s.match(/^(\d{4})-(\d{2})-(\d{2})/))) return new Date(+m[1], +m[2]-1, +m[3]);
      if((m = s.match(/^(\d{2})\/(\d{2})\/(\d{4})/))) return new Date(+m[3], +m[2]-1, +m[1]);
      if((m = s.match(/^(\d{2})-(\d{2})-(\d{4})/))) return new Date(+m[3], +m[2]-1, +m[1]);
      if((m = s.match(/^(\d{4})\/(\d{2})\/(\d{2})/))) return new Date(+m[1], +m[2]-1, +m[3]);
      const d = new Date(s);
      return isNaN(d.getTime()) ? null : d;
    }

    function cadSemColor(cadDate){
      if(!cadDate) return '';
      const today = new Date(); today.setHours(0,0,0,0);
      const cd = new Date(cadDate); cd.setHours(0,0,0,0);
      const diffDays = Math.floor((cd - today) / 86400000);
      if (diffDays <= 90) return 'red';
      if (diffDays <= 180) return 'yellow';
      return 'green';
    }

    function cadSemLabel(color){
      if(color === 'red') return 'Rojo';
      if(color === 'yellow') return 'Amarillo';
      if(color === 'green') return 'Verde';
      return '';
    }

    function makeInventoryRow(r){
      const partes = getExistenciaPartes(r);
      const alm = partes.almacen;
      const est = partes.estantes;
      const tot = partes.existencia;
      const base = (r.base_exist!=null && r.base_exist!=='') ? toNum(r.base_exist) : tot;
      const cad = pick(r,['caducidad','CADUCIDAD','cad','CAD']);
      const sem = cadSemColor(parseCadDate(cad));
      return {
        'CLAVE': pick(r,['clave','CLAVE','codigo','CODIGO']),
        'CODIGO_BARRAS': pick(r,['codigo_barras','CODIGO_BARRAS','codigoBarras','barcode','BARCODE']),
        'DESCRIPCION': pick(r,['descripcion','DESCRIPCION','nombre','NOMBRE']),
        'UNIDAD': pick(r,['unidad','UNIDAD']),
        'LOTE': pick(r,['lote','LOTE']),
        'CADUCIDAD': cad,
        'SEMAFORO': cadSemLabel(sem),
        'ENTRADAS': toNum(pick(r,['entradas','ENTRADAS'])),
        'SALIDAS': toNum(pick(r,['salidas','SALIDAS'])),
        'ALMACEN': alm,
        'ESTANTES': est,
        'EXISTENCIA': tot,
        ...(typeof window.mxFinancialExportFields==='function'?window.mxFinancialExportFields(r):{}),
        'CLASIFICACION': pick(r,['clasificacion','CLASIFICACION','clasificación','CLASIFICACIÓN','clasif','tipo']),
        'RESTRICCION': pick(r,['restriccion','RESTRICCION','restricción','RESTRICCIÓN']),
        'UBICACION': pick(r,['ubicacion','UBICACION','ubicación','UBICACIÓN']),
        'EXISTENCIA_BASE': base
      };
    }

    function makeEntradaRow(r){
      const antes = toNum(pick(r,['ex_ini','existencia_inicial','antes','ANTES']));
      const pzs = toNum(pick(r,['pzs','PZS','cantidad','CANTIDAD']));
      const saldoFinalRaw = pick(r,['ex_fin','existencia_final','saldo_final','SALDO_FINAL']);
      const saldoFinal = (saldoFinalRaw === '' || saldoFinalRaw == null) ? (antes + pzs) : toNum(saldoFinalRaw);
      return {
        'FECHA': pick(r,['fecha','FECHA']),
        'USUARIO': pick(r,['usuario','USUARIO']),
        'CLAVE': pick(r,['clave','CLAVE']),
        'CODIGO_BARRAS': pick(r,['codigo_barras','CODIGO_BARRAS','codigoBarras','barcode','BARCODE']),
        'DESCRIPCION': pick(r,['descripcion','DESCRIPCION','nombre','NOMBRE']),
        'UNIDAD': pick(r,['unidad','UNIDAD']),
        'LOTE': pick(r,['lote','LOTE']),
        'CADUCIDAD': pick(r,['caducidad','CADUCIDAD','cad','CAD']),
        'ANTES': antes,
        'PZS': pzs,
        'SALDO_FINAL': saldoFinal,
        ...(typeof window.mxFinancialExportFields==='function'?window.mxFinancialExportFields(r):{}),
        'CLASIFICACION': pick(r,['clasificacion','CLASIFICACION','clasificación']),
        'RESTRICCION': pick(r,['restriccion','RESTRICCION','restricción']),
        'UBICACION': pick(r,['ubicacion','UBICACION','ubicación']),
        'REGISTRO_SANITARIO': pick(r,['registro_sanitario','registro sanitario']),
        'DEPARTAMENTO': pick(r,['departamento']),
        'PRESENTACION': pick(r,['presentacion','presentación']),
        'DENOMINACION_GENERICA': pick(r,['denominacion_generica','denominacion generica','denominación genérica']),
        'PROVEEDOR': pick(r,['proveedor']),
        'PROVEEDOR_RFC': pick(r,['proveedor_rfc','proveedorRfc','rfc_proveedor']),
        'PROVEEDOR_ID': pick(r,['proveedor_id','proveedorId']),
        'TITULAR': pick(r,['titular']),
        'TIPO_DOC': pick(r,['tipo_doc','TIPO_DOC','tipoDocumento']),
        'FOLIO': pick(r,['folio','FOLIO'])
      };
    }

    function makeSalidaRow(r){
      const antes = toNum(pick(r,['ex_ini','existencia_inicial','antes','ANTES']));
      const pzs = toNum(pick(r,['pzs','PZS','cantidad','CANTIDAD']));
      const saldoFinalRaw = pick(r,['ex_fin','existencia_final','saldo_final','SALDO_FINAL']);
      const saldoFinal = (saldoFinalRaw === '' || saldoFinalRaw == null) ? Math.max(0, (antes - pzs)) : toNum(saldoFinalRaw);
      return {
        'FECHA': pick(r,['fecha','FECHA']),
        'USUARIO': pick(r,['usuario','USUARIO']),
        'CLAVE': pick(r,['clave','CLAVE']),
        'CODIGO_BARRAS': pick(r,['codigo_barras','CODIGO_BARRAS','codigoBarras','barcode','BARCODE']),
        'DESCRIPCION': pick(r,['descripcion','DESCRIPCION','nombre','NOMBRE']),
        'UNIDAD': pick(r,['unidad','UNIDAD']),
        'LOTE': pick(r,['lote','LOTE']),
        'CADUCIDAD': pick(r,['caducidad','CADUCIDAD','cad','CAD']),
        'ANTES': antes,
        'PZS': pzs,
        'SALDO_FINAL': saldoFinal,
        ...(typeof window.mxFinancialExportFields==='function'?window.mxFinancialExportFields(r):{}),
        'TIPO_DOC': pick(r,['tipo_doc','TIPO_DOC','tipoDocumento']),
        'ESTADO': pick(r,['estado','ESTADO']),
        'MEDICO': pick(r,['medico','MEDICO']),
        'CEDULA': pick(r,['cedula','CEDULA']),
        'PACIENTE': pick(r,['paciente','PACIENTE']),
        'EXPEDIENTE': pick(r,['expediente','EXPEDIENTE']),
        'EDAD': pick(r,['edad_paciente','edadPaciente','edad']),
        'SEXO': pick(r,['sexo_paciente','sexoPaciente','sexo','genero']),
        'TELEFONO_PACIENTE': pick(r,['telefono_paciente','telefonoPaciente']),
        'DIAGNOSTICO': pick(r,['diagnostico','diagnóstico']),
        'CAMA': pick(r,['numeroCama','numero_cama','cama']),
        'SERVICIO': pick(r,['servicio','SERVICIO']),
        'SERVICIO_DESTINO': pick(r,['servicio_destino','destino']),
        'SERVICIO_INICIALES': pick(r,['servicio_iniciales']),
        'TELEFONO_MEDICO': pick(r,['telefono_medico']),
        'DOMICILIO_MEDICO': pick(r,['domicilio_medico']),
        'SOLICITANTE': pick(r,['solicitante']),
        'OBSERVACIONES': pick(r,['observaciones','observacion']),
        'CLASIFICACION': pick(r,['clasificacion','clasificación']),
        'RESTRICCION': pick(r,['restriccion','restricción']),
        'UBICACION': pick(r,['ubicacion','ubicación']),
        'KITS_QUIRURGICOS': pick(r,['kits_quirurgicos','kits']),
        'ORIGEN_SURTIDO': pick(r,['origen_surtido','origenSurtido']),
        'ORIGEN_INVENTARIO': pick(r,['origen_inventario','origenInventario']),
        'FOLIO': pick(r,['folio','FOLIO'])
      };
    }

    function sortInventario(arr){
      const out = Array.isArray(arr) ? arr.slice() : [];
      try{
        if(typeof mxSortInventarioInPlace === 'function') mxSortInventarioInPlace(out);
        else out.sort((a,b)=>
          String(a.descripcion || a.DESCRIPCION || '').localeCompare(String(b.descripcion || b.DESCRIPCION || ''),'es',{sensitivity:'base'})
        );
      }catch(_){}
      return out;
    }

    function sheetRows(rows){
      return (Array.isArray(rows) && rows.length) ? rows : [{ INFO:'Sin datos para esta hoja' }];
    }

    function appendSheet(wb, rows, name){
      XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(sheetRows(rows)), name);
    }

    const invL = inventario.map(limpiar);
    const entL = entradas.map(limpiar).map(makeEntradaRow);
    const salL = salidas.map(limpiar).map(makeSalidaRow);
    const antL = antibioticos.map(limpiar);

    const filtroStock = String(document.getElementById('invFiltroStock')?.value || '').trim().toLowerCase();
    const filtroSem = String(document.getElementById('invFiltroSem')?.value || '').trim().toLowerCase();

    const invBase = sortInventario(invL).filter(r => {
      const total = getExistenciaTotal(r);
      if(filtroStock === 'con' && total <= 0) return false;
      if(filtroStock === 'cero' && total !== 0) return false;
      return true;
    });

    const invSemFiltered = invBase.filter(r => {
      const sem = cadSemColor(parseCadDate(pick(r,['caducidad','CADUCIDAD','cad','CAD'])));
      if(filtroSem === 'red') return sem === 'red';
      if(filtroSem === 'yellow') return sem === 'yellow';
      return true; // verde y todos = general
    });

    const invExportOrdered = invSemFiltered.map(makeInventoryRow);

    const invRojo = invBase
      .filter(r => cadSemColor(parseCadDate(pick(r,['caducidad','CADUCIDAD','cad','CAD']))) === 'red')
      .map(makeInventoryRow);

    const invAmarillo = invBase
      .filter(r => cadSemColor(parseCadDate(pick(r,['caducidad','CADUCIDAD','cad','CAD']))) === 'yellow')
      .map(makeInventoryRow);

    const invPorUbicacion = invBase
      .map(makeInventoryRow)
      .sort((a,b)=>
        String(a.UBICACION || '').localeCompare(String(b.UBICACION || ''),'es',{sensitivity:'base'}) ||
        String(a.DESCRIPCION || '').localeCompare(String(b.DESCRIPCION || ''),'es',{sensitivity:'base'}) ||
        String(a.CLAVE || '').localeCompare(String(b.CLAVE || ''),'es',{sensitivity:'base'})
      );

    const invClavesUnicasMap = new Map();
    invBase.forEach(r=>{
      const clave = txt(r.clave ?? r.CLAVE ?? r.codigo ?? r.CODIGO);
      if(!clave) return;

      const descripcion = txt(r.descripcion ?? r.DESCRIPCION ?? r.nombre ?? r.NOMBRE);
      const unidad = txt(r.unidad ?? r.UNIDAD);
      const clasificacion = txt(r.clasificacion ?? r.CLASIFICACION);
      const restriccion = txt(r.restriccion ?? r.RESTRICCION);
      const exVal = getExistenciaTotal(r);
      const ubicacion = txt(r.ubicacion ?? r.UBICACION ?? r['ubicación'] ?? r['UBICACIÓN']);

      const prev = invClavesUnicasMap.get(clave) || {
        CLAVE: clave,
        DESCRIPCION: descripcion,
        UNIDAD: unidad,
        EXISTENCIA_TOTAL: 0,
        CLASIFICACION: clasificacion,
        RESTRICCION: restriccion,
        UBICACION_REFERENCIA: ubicacion
      };

      if(!prev.DESCRIPCION && descripcion) prev.DESCRIPCION = descripcion;
      if(!prev.UNIDAD && unidad) prev.UNIDAD = unidad;
      if(!prev.CLASIFICACION && clasificacion) prev.CLASIFICACION = clasificacion;
      if(!prev.RESTRICCION && restriccion) prev.RESTRICCION = restriccion;
      if(!prev.UBICACION_REFERENCIA && ubicacion) prev.UBICACION_REFERENCIA = ubicacion;

      prev.EXISTENCIA_TOTAL += exVal;
      invClavesUnicasMap.set(clave, prev);
    });

    const invClavesUnicas = Array.from(invClavesUnicasMap.values()).sort((a,b)=>
      String(a.DESCRIPCION || '').localeCompare(String(b.DESCRIPCION || ''),'es',{sensitivity:'base'}) ||
      String(a.CLAVE || '').localeCompare(String(b.CLAVE || ''),'es',{sensitivity:'base'})
    );

    const clavesAntibiotico = new Set();
    antL.forEach(r=>{
      const clave = txt(r.clave ?? r.CLAVE ?? r.codigo ?? r.CODIGO);
      if(clave) clavesAntibiotico.add(clave);
    });
    salL.forEach(r=>{
      const clave = txt(r.clave ?? r.CLAVE ?? r.codigo ?? r.CODIGO);
      if(!clave) return;
      const tipoDoc = txt(r.tipo_doc ?? r.TIPO_DOC ?? r.tipoDocumento ?? r.tipo ?? r.documento).toLowerCase();
      const restriccion = txt(r.restriccion ?? r.RESTRICCION).toLowerCase();
      const clasificacion = txt(r.clasificacion ?? r.CLASIFICACION).toLowerCase();
      if(tipoDoc === 'receta antibióticos' || tipoDoc === 'receta antibioticos' || tipoDoc.includes('antib') || restriccion.includes('antib') || clasificacion.includes('antib')) {
        clavesAntibiotico.add(clave);
      }
    });

    const antibioticosExistMap = new Map();
    invBase.forEach(r=>{
      const clave = txt(r.clave ?? r.CLAVE ?? r.codigo ?? r.CODIGO);
      if(!clave) return;

      const esAntibMarcado = (typeof mxIsAntibioticoInvRow === 'function') ? mxIsAntibioticoInvRow(r) : false;
      const esAntibPorHistorial = clavesAntibiotico.has(clave);
      const tieneMarcaSanitaria = txt(r.restriccion ?? r.RESTRICCION).toLowerCase().includes('antib') || txt(r.clasificacion ?? r.CLASIFICACION).toLowerCase().includes('antib') || r.antibiotico === true || r.isAntibiotico === true || r.ANTIBIOTICO === true;
      if(!esAntibMarcado && !(esAntibPorHistorial && tieneMarcaSanitaria)) return;

      const descripcion = txt(r.descripcion ?? r.DESCRIPCION ?? r.nombre ?? r.NOMBRE);
      const unidad = txt(r.unidad ?? r.UNIDAD);
      const clasificacion = txt(r.clasificacion ?? r.CLASIFICACION);
      const restriccion = txt(r.restriccion ?? r.RESTRICCION);
      const lote = txt(r.lote ?? r.LOTE);
      const exVal = getExistenciaTotal(r);

      const prev = antibioticosExistMap.get(clave) || {
        CLAVE: clave,
        DESCRIPCION: descripcion,
        UNIDAD: unidad,
        EXISTENCIA_TOTAL: 0,
        LOTES: new Set(),
        CLASIFICACION: clasificacion,
        RESTRICCION: restriccion
      };

      if(!prev.DESCRIPCION && descripcion) prev.DESCRIPCION = descripcion;
      if(!prev.UNIDAD && unidad) prev.UNIDAD = unidad;
      if(!prev.CLASIFICACION && clasificacion) prev.CLASIFICACION = clasificacion;
      if(!prev.RESTRICCION && restriccion) prev.RESTRICCION = restriccion;
      prev.EXISTENCIA_TOTAL += exVal;
      if(lote) prev.LOTES.add(lote);
      antibioticosExistMap.set(clave, prev);
    });

    if(!antibioticosExistMap.size){
      antL.forEach(r=>{
        const clave = txt(r.clave ?? r.CLAVE ?? r.codigo ?? r.CODIGO);
        if(!clave) return;
        const prev = antibioticosExistMap.get(clave) || {
          CLAVE: clave,
          DESCRIPCION: txt(r.descripcion ?? r.DESCRIPCION ?? r.nombre ?? r.NOMBRE),
          UNIDAD: txt(r.unidad ?? r.UNIDAD),
          EXISTENCIA_TOTAL: 0,
          LOTES: new Set(),
          CLASIFICACION: txt(r.clasificacion ?? r.CLASIFICACION),
          RESTRICCION: txt(r.restriccion ?? r.RESTRICCION)
        };
        const lote = txt(r.lote ?? r.LOTE);
        if(lote) prev.LOTES.add(lote);
        antibioticosExistMap.set(clave, prev);
      });
    }

    const antibioticosExistencias = Array.from(antibioticosExistMap.values())
      .map(r => ({
        CLAVE: r.CLAVE,
        DESCRIPCION: r.DESCRIPCION,
        UNIDAD: r.UNIDAD,
        EXISTENCIA_TOTAL: r.EXISTENCIA_TOTAL,
        LOTES_REGISTRADOS: Array.from(r.LOTES).sort((a,b)=>String(a).localeCompare(String(b),'es',{sensitivity:'base'})).join(', '),
        TOTAL_LOTES: r.LOTES.size,
        CLASIFICACION: r.CLASIFICACION,
        RESTRICCION: r.RESTRICCION
      }))
      .sort((a,b)=>
        String(a.DESCRIPCION || '').localeCompare(String(b.DESCRIPCION || ''),'es',{sensitivity:'base'}) ||
        String(a.CLAVE || '').localeCompare(String(b.CLAVE || ''),'es',{sensitivity:'base'})
      );

    const salidasPorClaveMap = new Map();
    salL.forEach(r=>{
      const clave = txt(r.clave ?? r.CLAVE ?? r.codigo ?? r.CODIGO);
      if(!clave) return;
      const pzs = toNum(pick(r,['pzs','PZS','cantidad','CANTIDAD']));
      const fecha = txt(r.fecha ?? r.FECHA);
      const prev = salidasPorClaveMap.get(clave) || { TOTAL_SALIDAS_HIST:0, FECHA_ULTIMA_SALIDA:'' };
      prev.TOTAL_SALIDAS_HIST += pzs;
      if(fecha){
        const fPrev = parseFechaFlexible(prev.FECHA_ULTIMA_SALIDA);
        const fCur = parseFechaFlexible(fecha);
        if(fCur && (!fPrev || fCur > fPrev)) prev.FECHA_ULTIMA_SALIDA = fecha;
      }
      salidasPorClaveMap.set(clave, prev);
    });

    const lentoONuloMovimiento = invClavesUnicas
      .filter(r => !salidasPorClaveMap.has(String(r.CLAVE || '').trim()))
      .map(r => {
        const exTotal = Number(r.EXISTENCIA_TOTAL || 0);
        const ab = antibioticosExistMap.get(String(r.CLAVE || '').trim());
        return {
          CLAVE: r.CLAVE,
          DESCRIPCION: r.DESCRIPCION,
          UNIDAD: r.UNIDAD,
          EXISTENCIA_TOTAL: exTotal,
          TOTAL_LOTES_ACTUALES: ab ? Number(ab.TOTAL_LOTES || 0) : '',
          LOTES_ACTUALES: ab ? String(ab.LOTES_REGISTRADOS || '') : '',
          TOTAL_SALIDAS_HIST: 0,
          FECHA_ULTIMA_SALIDA: '',
          ESTATUS_MOVIMIENTO: exTotal > 0 ? 'NULO' : 'SIN EXISTENCIA'
        };
      })
      .sort((a,b)=>
        String(a.DESCRIPCION || '').localeCompare(String(b.DESCRIPCION || ''),'es',{sensitivity:'base'}) ||
        String(a.CLAVE || '').localeCompare(String(b.CLAVE || ''),'es',{sensitivity:'base'})
      );

    const invCeroExistencias = invClavesUnicas.filter(r => Number(r.EXISTENCIA_TOTAL || 0) <= 0);

    let baseClaves = 0;
    try{
      if(typeof mxGetBaseClavesTotal === 'function') baseClaves = Number(mxGetBaseClavesTotal());
      if(!Number.isFinite(baseClaves) || baseClaves <= 0) baseClaves = Number(document.getElementById('baseClavesTotal')?.value || 0);
    }catch(_){}
    if(!Number.isFinite(baseClaves) || baseClaves <= 0) baseClaves = 520;
    baseClaves = Math.round(baseClaves);

    const __mxMiCpmInvExport = (typeof window.mxMiCpmComputeStats==='function') ? window.mxMiCpmComputeStats(invL) : null;
    if(__mxMiCpmInvExport && __mxMiCpmInvExport.base>0) baseClaves = __mxMiCpmInvExport.base;
    const conExistenciaReal = (__mxMiCpmInvExport && __mxMiCpmInvExport.base>0) ? __mxMiCpmInvExport.conExist : invClavesUnicas.filter(r => Number(r.EXISTENCIA_TOTAL || 0) > 0).length;
    const conExistencia = Math.min(baseClaves, conExistenciaReal);
    const sinExistencia = Math.max(0, baseClaves - conExistencia);
    const pctCon = baseClaves ? ((conExistencia / baseClaves) * 100) : 0;
    const pctSin = baseClaves ? ((sinExistencia / baseClaves) * 100) : 0;

    const resumenAbasto = [
      { INDICADOR:'Base claves', VALOR: baseClaves, PORCENTAJE:'100.0%' },
      { INDICADOR:'Claves únicas detectadas en inventario', VALOR: invClavesUnicas.length, PORCENTAJE: baseClaves ? ((invClavesUnicas.length/baseClaves)*100).toFixed(1)+'%' : '0.0%' },
      { INDICADOR:'Claves con existencia', VALOR: conExistencia, PORCENTAJE: pctCon.toFixed(1)+'%' },
      { INDICADOR:'Claves sin existencia / desabasto', VALOR: sinExistencia, PORCENTAJE: pctSin.toFixed(1)+'%' }
    ];

    const wb = XLSX.utils.book_new();
    appendSheet(wb, invExportOrdered, 'INVENTARIO');
    appendSheet(wb, entL, 'ENTRADAS');
    appendSheet(wb, salL, 'SALIDAS');
    appendSheet(wb, antL, 'HIST_ANTIBIOTICOS');
    appendSheet(wb, antibioticosExistencias, 'EXIST_ANTIBIOTICOS');
    appendSheet(wb, lentoONuloMovimiento, 'LENTO_O_NULO_MOV');
    appendSheet(wb, invRojo, 'PROX_CAD_ROJO');
    appendSheet(wb, invAmarillo, 'PROX_CAD_AMARILLO');
    appendSheet(wb, invCeroExistencias, 'CLAVES_SIN_EXIST');
    appendSheet(wb, invPorUbicacion, 'INV_POR_UBICACION');
    appendSheet(wb, resumenAbasto, 'RESUMEN_ABASTO');

    const fecha = new Date().toLocaleString().slice(0, 10);
    let sufijo = '';
    if (filtroSem === 'red') sufijo += '_ROJO';
    else if (filtroSem === 'yellow') sufijo += '_AMARILLO';
    if (filtroStock === 'con') sufijo += '_CON_EXISTENCIAS';
    else if (filtroStock === 'cero') sufijo += '_EN_CEROS';

    const nombreArchivo = `MACROXEL_INVENTARIO${sufijo}_${fecha}.xlsx`;
    XLSX.writeFile(wb, nombreArchivo);
    mxAlert('✅ Exportación Excel generada: ' + nombreArchivo);
  }catch(e){
    console.error(e);
    mxAlert('No se pudo generar el Excel: ' + (e && e.message ? e.message : e));
  }
};

document.getElementById('btnImpEnt').onclick=async ()=>{ await importReplace(document.getElementById('fileEnt').files,'entradas', mapEntradaImport); await drawEntradas(); renderDashboard(); };
document.getElementById('btnClrEnt').onclick=async ()=>{ if(!await mxConfirm('¿Seguro que deseas eliminar TODOS los registros de entradas?')) return; idbClear('entradas').then(()=>{drawEntradas();renderDashboard();}); };
document.getElementById('btnImpSal').onclick=async ()=>{ await importReplace(document.getElementById('fileSal').files,'salidas', mapSalidaImport); await drawSalidas(); renderDashboard(); };
document.getElementById('btnClrSal').onclick=async ()=>{
  if(!await mxConfirm('¿Seguro que deseas eliminar TODOS los registros de salidas? Los controles del módulo Folios se conservarán.')) return;
  try{
    await idbClear('salidas');
    await Promise.resolve(drawSalidas());
    renderDashboard();
    mxAlert('✅ Historial de Salidas eliminado. Los consecutivos se conservan y solo pueden modificarse desde el módulo Folios por el administrador.');
  }catch(e){
    console.error('[Eliminar Salidas]', e);
    mxAlert('No se pudo eliminar el historial de Salidas: ' + (e?.message || e));
  }
};
document.getElementById('btnImpAb').onclick=async ()=>{ await importReplace(document.getElementById('fileAb').files,'antibioticos', mapAntibioticoImport); await drawAntibioticos(); renderDashboard(); };
document.getElementById('btnClrAbHist1M').onclick = async ()=>{
  const all = await idbAll('antibioticos').catch(()=>[]);
  if(!Array.isArray(all) || !all.length){
    mxAlert('No hay registros de antibióticos para depurar.');
    return;
  }
  if(!await mxConfirm('Se eliminarán del historial de antibióticos todos los registros antiguos y se conservarán solamente los últimos 30 días reales (incluyendo hoy). ¿Deseas continuar?')) return;

  const today = new Date();
  today.setHours(0,0,0,0);

  const cutoff = new Date(today);
  cutoff.setDate(cutoff.getDate() - 29);
  const cutoffYMD = cutoff.toISOString().slice(0,10);

  const keep = [];
  const invalid = [];

  for(const r of all){
    const rawFecha = r && r.fecha;
    const ymd = (typeof mxYMD === 'function') ? mxYMD(rawFecha) : '';
    if(!ymd){
      invalid.push(r);
      continue;
    }
    if(ymd >= cutoffYMD) keep.push(r);
  }

  if(typeof window.mxReplaceStoreSafely==='function') await window.mxReplaceStoreSafely('antibioticos',keep);
  else { await idbClear('antibioticos'); if(keep.length) await idbBulkPut('antibioticos',keep); }

  await drawAntibioticos();
  renderDashboard();

  const eliminados = Math.max(0, all.length - keep.length);
  let msg = `Depuración completada. Se conservaron ${keep.length} registro(s) dentro de los últimos 30 días reales y se eliminaron ${eliminados}.`;
  if(invalid.length){
    msg += `\n\nAviso: ${invalid.length} registro(s) tenían fecha inválida o no reconocible y también se eliminaron.`;
  }
  msg += `\n\nRango conservado: desde ${_fmtYMD(cutoffYMD)} hasta ${_fmtYMD(today.toISOString().slice(0,10))}.`;
  mxAlert(msg);
};
document.getElementById('btnClrAb').onclick=async ()=>{ if(!await mxConfirm('¿Seguro que deseas eliminar TODOS los registros de antibioticos?')) return; idbClear('antibioticos').then(()=>{ drawAntibioticos(); renderDashboard(); }); };
