function mxFocusSalidasBuscadorInmediato(){
  const producto = document.getElementById('salBusca');
  if(!producto) return;

  const aplicar = ()=>{
    try{
      producto.focus({preventScroll:true});
      const fin = String(producto.value || '').length;
      if(typeof producto.setSelectionRange === 'function') producto.setSelectionRange(fin, fin);
    }catch(_e){
      try{ producto.focus(); }catch(__e){}
    }
  };

  // Primer enfoque síncrono para que el escáner pueda escribir desde el primer dígito.
  aplicar();
  try{ if(typeof queueMicrotask === 'function') queueMicrotask(aplicar); }catch(_e){}
  try{ if(typeof requestAnimationFrame === 'function') requestAnimationFrame(aplicar); }catch(_e){}
}

function mxFocusSalidaDespuesDeMedico(nameInputId){
  try{
    // En colectivo justificado el nombre del paciente sigue siendo obligatorio.
    // La cédula y el expediente ya no bloquean la salida.
    if(nameInputId === '#salMedicoJ'){
      const paciente = document.getElementById('salPacienteJ');
      if(paciente && !String(paciente.value || '').trim()){
        const aplicarPaciente = ()=>{
          try{ paciente.focus({preventScroll:true}); }catch(_e){ try{ paciente.focus(); }catch(__e){} }
        };
        aplicarPaciente();
        try{ if(typeof requestAnimationFrame === 'function') requestAnimationFrame(aplicarPaciente); }catch(_e){}
        return;
      }
    }
    mxFocusSalidasBuscadorInmediato();
  }catch(_e){}
}

function mxFocusSalidaColectivoJustificadoNext(source){
  try{
    const tipoVal = String(document.getElementById('salTipo')?.value || '').trim().toLowerCase();
    if(tipoVal !== 'colectivo justificado') return;

    if(source === 'medico'){
      mxFocusSalidaDespuesDeMedico('#salMedicoJ');
      return;
    }

    if(source === 'paciente'){
      const paciente = document.getElementById('salPacienteJ');
      if(String(paciente?.value || '').trim()) mxFocusSalidasBuscadorInmediato();
    }
  }catch(_e){}
}

function attachMedicoAutocomplete(nameInputId, cedInputId){
  const inp=$(nameInputId), ced=$(cedInputId);
  if(!inp || !ced || inp.dataset.mxMedKeyboardBound === '1') return;
  inp.dataset.mxMedKeyboardBound = '1';
  ced.dataset.mxMedKeyboardBound = '1';

  let box = null;
  let activeIndex = -1;
  let requestSeq = 0;
  let pendingEnter = false;
  let pendingMove = 0;
  let cache = [];
  let cacheAt = 0;
  let itemCache = [];
  let lastEraseAt = 0;
  const DOUBLE_ERASE_MS = 700;

  const str = (v)=> String(v == null ? '' : v).trim();
  const norm = (v)=> str(v).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ');
  const cleanCed = (v)=> str(v).replace(/\s+/g,'').toLowerCase();

  const close = ()=>{
    if(box){ box.remove(); box=null; }
    itemCache=[];
    activeIndex = -1;
  };

  const items = ()=> itemCache;

  const setActive = (index)=>{
    const rows=itemCache;
    if(!rows.length){ activeIndex=-1; return; }
    const next=((Number(index)||0)%rows.length+rows.length)%rows.length;
    const previous=(activeIndex>=0&&activeIndex<rows.length)?rows[activeIndex]:null;
    const current=rows[next];
    if(previous&&previous!==current){
      previous.classList.remove('mx-keyboard-active');
      previous.setAttribute('aria-selected','false');
    }
    if(current){
      current.classList.add('mx-keyboard-active');
      current.setAttribute('aria-selected','true');
    }
    activeIndex=next;
    try{ current?.scrollIntoView({block:'nearest'}); }catch(_e){}
  };

  const activateCurrent = ()=>{
    const rows = items();
    if(!rows.length) return false;
    const idx = activeIndex >= 0 && activeIndex < rows.length ? activeIndex : 0;
    rows[idx].dispatchEvent(new MouseEvent('mousedown',{bubbles:true,cancelable:true,view:window}));
    return true;
  };

  const focusName = ()=>{
    try{
      inp.focus({preventScroll:true});
      if(typeof inp.setSelectionRange === 'function') inp.setSelectionRange(0,0);
    }catch(_e){ try{ inp.focus(); }catch(__e){} }
  };

  const clearDoctorSelection = ()=>{
    // Invalida búsquedas asíncronas anteriores para impedir que reaparezca una lista vieja.
    requestSeq++;
    pendingEnter = false;
    pendingMove = 0;
    lastEraseAt = 0;
    close();
    inp.value = '';
    ced.value = '';
    focusName();
  };

  const fill = (m)=>{
    inp.value = str(m?.nombre || m?.NOMBRE || '');
    ced.value = str(m?.cedula || m?.CEDULA || m?.['cédula'] || m?.['Cédula'] || '');
    pendingEnter = false;
    pendingMove = 0;
    lastEraseAt = 0;
    close();
    mxFocusSalidaDespuesDeMedico(nameInputId);
  };

  const loadMedicos = async ()=>{
    const now = Date.now();
    if(Array.isArray(cache) && cache.length && (now-cacheAt) < 60000) return cache;
    await ensureDBReady();
    const all = await idbAll('medicos').catch(()=>[]);
    cache = Array.isArray(all) ? all : [];
    cacheAt = now;
    return cache;
  };

  const getMatches = async (q, mode)=>{
    const all = await loadMedicos();
    const nq = norm(q), cq = cleanCed(q);
    if(!nq && !cq) return [];
    return all.filter(m=>{
      const nombre = norm(m?.nombre || m?.NOMBRE || '');
      const cedula = cleanCed(m?.cedula || m?.CEDULA || m?.['cédula'] || m?.['Cédula'] || '');
      if(mode === 'cedula') return cedula.includes(cq) || nombre.includes(nq);
      return nombre.includes(nq) || cedula.includes(cq);
    }).slice(0,40);
  };

  const render = (list, source)=>{
    close();
    if(!Array.isArray(list) || !list.length){
      pendingEnter = false;
      pendingMove = 0;
      return;
    }

    const el = source === 'cedula' ? ced : inp;
    const r = el.getBoundingClientRect();
    box = document.createElement('div');
    box.className = 'mx-medico-sug-box';
    box.setAttribute('role','listbox');
    Object.assign(box.style,{
      position:'fixed', zIndex:100000, background:'#fff', border:'1px solid #dbe3ef',
      maxHeight:'240px', overflow:'auto', width:Math.max(r.width,320)+'px',
      boxShadow:'0 14px 32px rgba(2,6,23,.16)', left:r.left+'px', top:(r.bottom+4)+'px',
      borderRadius:'12px'
    });

    const enc = (x)=> String(x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
    box.innerHTML = list.map((m,idx)=>{
      const n = str(m?.nombre || m?.NOMBRE || '');
      const c = str(m?.cedula || m?.CEDULA || m?.['cédula'] || m?.['Cédula'] || '');
      const i = str(m?.institucion || m?.INSTITUCION || m?.['institución'] || m?.['Institución'] || '');
      return `<div class="mx-medico-sug-item" role="option" tabindex="-1" data-index="${idx}">
        <div style="font-weight:800;line-height:1.15;">${enc(n || 'Médico sin nombre')}</div>
        <div style="font-size:12px;color:#475569;margin-top:2px;">Cédula: <b>${enc(c || '—')}</b>${i ? ' · '+enc(i) : ''}</div>
      </div>`;
    }).join('');

    document.body.appendChild(box);
    itemCache=Array.from(box.querySelectorAll('.mx-medico-sug-item'));
    itemCache.forEach((row,idx)=>{
      const pick = (ev)=>{
        ev.preventDefault();
        ev.stopPropagation();
        fill(list[idx]);
      };
      row.addEventListener('mousedown', pick);
      row.addEventListener('mouseenter', ()=>setActive(idx));
    });

    setActive(0);
    if(pendingMove){
      setActive(activeIndex + pendingMove);
      pendingMove = 0;
    }
    if(pendingEnter){
      pendingEnter = false;
      queueMicrotask(()=>{ activateCurrent(); });
    }
  };

  const show = async (source)=>{
    const el = source === 'cedula' ? ced : inp;
    const q = str(el.value);
    const seq = ++requestSeq;
    if(!q){ close(); pendingEnter=false; pendingMove=0; return 0; }
    const list = await getMatches(q, source);
    if(seq !== requestSeq) return 0;
    render(list, source);
    return Array.isArray(list) ? list.length : 0;
  };

  const keyHandler = (source)=>(ev)=>{
    const isErase = ev.key === 'Backspace' || ev.key === 'Delete';

    // Solo en el campo de nombre: dos pulsaciones consecutivas de Backspace/Supr
    // limpian de inmediato tanto el nombre como la cédula asociada.
    if(source === 'nombre' && isErase && !ev.ctrlKey && !ev.metaKey && !ev.altKey && !ev.repeat){
      const now = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
      if(lastEraseAt && (now-lastEraseAt) <= DOUBLE_ERASE_MS){
        ev.preventDefault();
        ev.stopPropagation();
        clearDoctorSelection();
        return;
      }
      lastEraseAt = now;
    }else if(!isErase){
      lastEraseAt = 0;
    }

    if(ev.key === 'Escape'){
      ev.preventDefault();
      pendingEnter=false;
      pendingMove=0;
      close();
      return;
    }
    if(ev.key === 'ArrowDown' || ev.key === 'ArrowUp'){
      ev.preventDefault();
      const delta = ev.key === 'ArrowDown' ? 1 : -1;
      if(box && items().length){ setActive((activeIndex < 0 ? 0 : activeIndex) + delta); }
      else { pendingMove = delta; show(source); }
      return;
    }
    if(ev.key === 'Enter'){
      const field=source === 'cedula' ? ced : inp;
      const q = str(field.value);
      if(!q) return;
      ev.preventDefault();
      if(box && items().length){
        activateCurrent();
      }else{
        pendingEnter=true;
        Promise.resolve(show(source)).then((found)=>{
          if(!found && document.activeElement===field){
            pendingEnter=false;
            window.mxFocusNextField?.(field);
          }
        });
      }
    }
  };

  inp.addEventListener('input', ()=>{ pendingEnter=false; pendingMove=0; show('nombre'); });
  ced.addEventListener('input', ()=>{ pendingEnter=false; pendingMove=0; show('cedula'); });
  inp.addEventListener('keydown', keyHandler('nombre'));
  ced.addEventListener('keydown', keyHandler('cedula'));

  const exactFillByCedula = async ()=>{
    const c = cleanCed(ced.value);
    if(!c) return;
    const list = await getMatches(c,'cedula');
    const exact = list.find(m=> cleanCed(m?.cedula || m?.CEDULA || m?.['cédula'] || m?.['Cédula'] || '') === c);
    if(exact) fill(exact);
  };
  ced.addEventListener('change', exactFillByCedula);
  ced.addEventListener('blur', ()=>setTimeout(exactFillByCedula,120));
  document.addEventListener('click',(e)=>{
    if(box && !inp.contains(e.target) && !ced.contains(e.target) && !box.contains(e.target)) close();
  });
}
