    function mxDoseType(){
      try{ return String(document.getElementById('cpmDoseType')?.value || 'ampula'); }catch(e){ return 'ampula'; }
    }
    function mxDoseCfg(type){
      var t = type || mxDoseType();
      if(t === 'tableta') return {unit:'tabletas', per:'Tabletas por caja', containers:'Cajas', extra:'Tabletas extra', total:'Total tabletas', formula:'Fórmula: (tabletas por caja × cajas) + tabletas extra.'};
      if(t === 'gotas') return {unit:'gotas', per:'mL por frasco', containers:'Frascos', extra:'Gotas extra', total:'Total gotas', formula:'Fórmula: (mL por frasco × frascos × gotas por mL) + gotas extra.'};
      if(t === 'ml') return {unit:'mL', per:'mL por frasco', containers:'Frascos', extra:'mL extra', total:'Total mL', formula:'Fórmula: (mL por frasco × frascos) + mL extra.'};
      return {unit:'ampollas', per:'Ampollas por caja', containers:'Cajas', extra:'Ampollas extra', total:'Total ampollas', formula:'Fórmula: (ampollas por caja × cajas) + ampollas extra.'};
    }
    function mxDoseFormat(n,type){
      if(!(n > 0)) return '';
      if(type === 'ml') return String(Number(n.toFixed(3))).replace(/\.0+$/,'');
      return String(Math.round(n));
    }
    function mxRefreshDoseUi(){
      try{
        var type=mxDoseType(), cfg=mxDoseCfg(type);
        var perLabel=document.getElementById('cpmDosePerLabel'); if(perLabel) perLabel.textContent=cfg.per;
        var contLabel=document.getElementById('cpmDoseContainersLabel'); if(contLabel) contLabel.textContent=cfg.containers;
        var extraLabel=document.getElementById('cpmDoseExtraLabel'); if(extraLabel) extraLabel.textContent=cfg.extra;
        var totalLabel=document.getElementById('cpmDoseTotalLabel'); if(totalLabel) totalLabel.textContent=cfg.total;
        var formula=document.getElementById('cpmDoseFormula'); if(formula) formula.textContent=cfg.formula;
        var hint=document.getElementById('cpmDoseUnitHint'); if(hint) hint.textContent='Resultado en '+cfg.unit+'.';
        var factorWrap=document.getElementById('cpmDoseFactorWrap'); if(factorWrap) factorWrap.style.display=type==='gotas'?'flex':'none';
        var per=document.getElementById('cpmAmpPorCaja'); if(per){ per.placeholder=(type==='ampula'||type==='tableta'||type==='gotas'||type==='ml')?'Auto / manual':'Cantidad'; }
        var pzs=document.getElementById('cpmInlinePzs'); if(pzs){pzs.step=type==='ml'?'0.01':'1';pzs.min=type==='ml'?'0.01':'1';}
      }catch(e){}
    }
    function mxCalcAmpulasInline(){
      try{
        var type=mxDoseType();
        var per=Number(document.getElementById('cpmAmpPorCaja')?.value || 0);
        var containers=Number(document.getElementById('cpmAmpNumCajas')?.value || 0);
        var extra=Number(document.getElementById('cpmAmpExtra')?.value || 0);
        var factor=Number(document.getElementById('cpmDoseFactor')?.value || 0);
        var total=0;
        if(type==='gotas') total=(per*containers*factor)+extra;
        else total=(per*containers)+extra;
        if(type!=='ml' && total>0) total=Math.round(total);
        var totalEl=document.getElementById('cpmAmpTotal'); if(totalEl) totalEl.value=mxDoseFormat(total,type);
        return total;
      }catch(e){ return 0; }
    }
    function mxDetectDosePerContainerFromDesc(desc,type){
      try{
        var s=_toStr(desc).replace(/\s+/g,' ').trim(); if(!s) return 0;
        var plain=s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();
        var patterns=[];
        if(type==='ampula') patterns=[
          /\b(?:ENVASE|CAJA|ESTUCHE|PAQUETE|BLISTER|BOLSA|KIT)\s+CON\s+(\d+(?:[\.,]\d+)?)\s+(FRASCOS?\s*AMPULA(?:S)?|AMPOLLETAS?|AMPULAS?|AMPOLLAS?|FRASCOS?)\b/,
          /\bCON\s+(\d+(?:[\.,]\d+)?)\s+(FRASCOS?\s*AMPULA(?:S)?|AMPOLLETAS?|AMPULAS?|AMPOLLAS?|FRASCOS?)\b/,
          /\b(\d+(?:[\.,]\d+)?)\s+(FRASCOS?\s*AMPULA(?:S)?|AMPOLLETAS?|AMPULAS?|AMPOLLAS?)\b/
        ];
        else if(type==='tableta') patterns=[
          /\b(?:ENVASE|CAJA|BLISTER|FRASCO)\s+CON\s+(\d+(?:[\.,]\d+)?)\s+(TABLETAS?|COMPRIMIDOS?)\b/,
          /\bCON\s+(\d+(?:[\.,]\d+)?)\s+(TABLETAS?|COMPRIMIDOS?)\b/,
          /\b(\d+(?:[\.,]\d+)?)\s+(TABLETAS?|COMPRIMIDOS?)\b/
        ];
        else if(type==='gotas'||type==='ml') patterns=[
          /\b(?:FRASCO|ENVASE|BOTELLA)(?:\s+GOTERO)?(?:\s+CON)?\s+(\d+(?:[\.,]\d+)?)\s*ML\b/,
          /\b(\d+(?:[\.,]\d+)?)\s*ML\b/
        ];
        for(var i=0;i<patterns.length;i++){
          var m=plain.match(patterns[i]);
          if(m&&m[1]){var qty=Number(String(m[1]).replace(',','.'));if(Number.isFinite(qty)&&qty>0)return qty;}
        }
        return 0;
      }catch(e){ return 0; }
    }
    function mxDetectAmpulasPorCajaFromDesc(desc){ return mxDetectDosePerContainerFromDesc(desc,'ampula'); }
    function mxAutoDetectAmpulasPorCaja(forceFocus){
      try{
        var descEl=document.getElementById('cpmInlineDesc'), perEl=document.getElementById('cpmAmpPorCaja'), containersEl=document.getElementById('cpmAmpNumCajas');
        if(!descEl||!perEl) return 0;
        var type=mxDoseType(), detected=mxDetectDosePerContainerFromDesc(descEl.value||'',type), prevAuto=perEl.dataset.autoDetected==='1', current=Number(perEl.value||0);
        if(detected>0){
          if(!current||prevAuto||current===detected){perEl.value=String(detected).replace(/\.0+$/,'');perEl.dataset.autoDetected='1';perEl.title='Detectado desde el nombre / descripción';perEl.style.background='#ecfeff';perEl.style.borderColor='#67e8f9';}
          mxCalcAmpulasInline();
          if(forceFocus&&containersEl)setTimeout(function(){try{containersEl.focus();if(containersEl.select)containersEl.select();}catch(e){}},60);
          return detected;
        }
        if(prevAuto){perEl.value='';perEl.dataset.autoDetected='';perEl.title='';perEl.style.background='';perEl.style.borderColor='';mxCalcAmpulasInline();}
        return 0;
      }catch(e){ return 0; }
    }
