        var clearBtn=document.getElementById('cpmAmpClear');if(clearBtn)clearBtn.addEventListener('click',function(){mxClearAmpulasInlineCalc();try{document.getElementById('cpmAmpPorCaja')?.focus();}catch(e){}});
        var useBtn=document.getElementById('cpmAmpUse');if(useBtn)useBtn.addEventListener('click',function(){var type=mxDoseType(),cfg=mxDoseCfg(type),total=mxCalcAmpulasInline();if(type==='gotas'&&!(Number(document.getElementById('cpmDoseFactor')?.value||0)>0)){mxAlert('⚠️ Captura cuántas gotas por mL entrega este gotero.');return;}if(!(total>0)){mxAlert('⚠️ Captura primero los datos de la calculadora de dosificación.');return;}var pzsEl=document.getElementById('cpmInlinePzs');if(pzsEl){pzsEl.value=mxDoseFormat(total,type);pzsEl.title='Cantidad calculada en '+cfg.unit;try{pzsEl.focus();if(pzsEl.select)pzsEl.select();}catch(e){}}});
        mxRefreshDoseUi();mxSetAmpulasInlineCalcExpanded(false);mxCalcAmpulasInline();
