    (function(){
      var cadEl = document.getElementById('cpmInlineCad');
      if(!cadEl) return;
      function fmtCad(v){
        var n = String(v || '').replace(/\D/g,'').slice(0,8);
        if(n.length <= 2) return n;
        if(n.length <= 4) return n.slice(0,2) + '/' + n.slice(2);
        return n.slice(0,2) + '/' + n.slice(2,4) + '/' + n.slice(4);
      }
      function onCadInput(){
        var oldStart = cadEl.selectionStart || 0;
        var beforeLen = cadEl.value.length;
        cadEl.value = fmtCad(cadEl.value);
        var afterLen = cadEl.value.length;
        var nextPos = oldStart + (afterLen - beforeLen);
        try{ cadEl.setSelectionRange(nextPos, nextPos); }catch(e){}
      }
      cadEl.setAttribute('inputmode','numeric');
      cadEl.setAttribute('maxlength','10');
      cadEl.addEventListener('input', onCadInput);
      cadEl.addEventListener('blur', function(){ cadEl.value = fmtCad(cadEl.value).trim(); });
    })();

    function _toStr(v){ return (v==null?'':String(v)); }
    function _mxExtractUnidadFromDesc(desc){
      try{
        var s = _toStr(desc).replace(/\s+/g,' ').trim();
        if(!s) return '';
        var up = s.toUpperCase();
        var idx = up.indexOf('ENVASE');
        if(idx < 0) return '';
        var unit = s.slice(idx).trim();
        unit = unit.replace(/^[\s:;,.\-]+/, '').trim();
        return unit;
      }catch(e){ return ''; }
    }
    function _mxAutoFillUnidadFromDesc(){
      try{
        var uniEl = document.getElementById('cpmInlineUni');
        var descEl = document.getElementById('cpmInlineDesc');
        if(!uniEl || !descEl) return;
        if(_toStr(uniEl.value).trim()) return;
        var inferred = _mxExtractUnidadFromDesc(descEl.value);
        if(inferred) uniEl.value = inferred;
      }catch(e){}
    }
        async function _idbAll(store){
      if(typeof idbAll==='function'){ return await idbAll(store); }
      console.warn('idbAll no disponible'); return [];
    }
        
    function placeDropdown(dropEl, anchor){
      var r = anchor.getBoundingClientRect();
      dropEl.style.left = r.left + 'px';
      dropEl.style.top  = (r.bottom + window.scrollY) + 'px';
      dropEl.style.width = r.width + 'px';
    }

const sInp = document.getElementById('cpmInlineSearch');
const drop = document.getElementById('cpmInlineDrop');

function closeDropCPM(){
  drop.style.display = 'none';
  drop.innerHTML = '';
}

function normalizeCPM(txt) {
  return (txt || '')
    .toString()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}

sInp.addEventListener('input', async function(){
  let q = normalizeCPM(this.value);
  if (!q) { return closeDropCPM(); }

  const cpmData = await _idbAll('cpm') || [];
  let results = cpmData.filter(x =>
    normalizeCPM(x.csg).includes(q) ||
    normalizeCPM(x.descripcion).includes(q)
  );

  if (!results.length) {
    if (!cacheInv.length) await refreshCacheInv();
    results = cacheInv.filter(x =>
      normalizeCPM(x.clave).includes(q) ||
      normalizeCPM(x.descripcion || x.nombre).includes(q) ||
      normalizeCPM(x.lote).includes(q)
    );
  }

  if (!results.length) return closeDropCPM();

  function applyInlineCpmItem(x){
    try{
      document.getElementById('cpmInlineBar').value   = x.codigo_barras || x.codigoBarras || x.barcode || '';
      document.getElementById('cpmInlineClave').value = x.csg || x.clave || '';
      document.getElementById('cpmInlineDesc').value  = x.descripcion || x.nombre || '';
      try{ document.getElementById('cpmInlineDesc').dispatchEvent(new Event('input')); }catch(e){}
      document.getElementById('cpmInlineUni').value   = x.unidad || '';
      try{ _mxAutoFillUnidadFromDesc(); }catch(e){}
      try{ mxAutoDetectAmpulasPorCaja(false); }catch(e){}
      try{
        setTimeout(function(){
          var cadEl = document.getElementById('cpmInlineCad');
          if(cadEl){ cadEl.focus(); if(cadEl.select) cadEl.select(); }
        }, 60);
      }catch(e){}
      var metaClas = x.clasificacion || x.clasif || '';
      var metaRest = x.restriccion || x.restric || '';
      var metaUbic = x.ubicacion || x['UBICACIÓN'] || x['ubicación'] || '';
      var clasEl = document.getElementById('cpmInlineClas'); if(clasEl) clasEl.value = metaClas;
      var restEl = document.getElementById('cpmInlineRest'); if(restEl) restEl.value = metaRest;
      var ubicEl = document.getElementById('cpmInlineUbic'); if(ubicEl) ubicEl.value = metaUbic;
      window.__cpmInlineMeta = { clasificacion:metaClas, restriccion:metaRest, ubicacion:metaUbic };
      closeDropCPM();
    }catch(e){}
  }

  if (results.length === 1) {
    applyInlineCpmItem(results[0]);
    return;
  }

  drop.innerHTML = results.map(x => `
    <div class="cpm-dropdown-item"
      data-bar="${x.codigo_barras || x.codigoBarras || x.barcode || ''}"
      data-csg="${x.csg || x.clave || ''}"
      data-desc="${x.descripcion || x.nombre || ''}"
      data-uni="${x.unidad || ''}"
      data-clas="${x.clasificacion || x.clasif || ''}"
      data-rest="${x.restriccion || x.restric || ''}"
      data-ubic="${x.ubicacion || x['UBICACIÓN'] || x['ubicación'] || ''}">
      ${x.csg || x.clave || ''} — ${(x.descripcion || x.nombre || '').toUpperCase()}
    </div>
  `).join('');

  placeDropdown(drop, sInp);
  drop.style.display = 'block';

  drop.querySelectorAll('.cpm-dropdown-item').forEach(it=>{
    it.addEventListener('click', ()=>{
      applyInlineCpmItem({
        codigo_barras: it.dataset.bar || '',
        csg: it.dataset.csg || '',
        clave: it.dataset.csg || '',
        descripcion: it.dataset.desc || '',
        nombre: it.dataset.desc || '',
        unidad: it.dataset.uni || '',
        clasificacion: it.dataset.clas || '',
        restriccion: it.dataset.rest || '',
        ubicacion: it.dataset.ubic || ''
      });
    });
  });
});

document.addEventListener('click', (e)=>{
  if (drop.style.display === 'block' && !drop.contains(e.target) && e.target !== sInp) {
    closeDropCPM();
  }
});

function formatCaducidad(fecha) {
  if (!fecha) return '';

  let f = String(fecha).trim();
  f = f.replace(/^['"]|['"]$/g,'').trim();

  const pad2 = (n)=>String(n).padStart(2,'0');
  const lastDay = (y,m)=>{ // m: 1-12
    const d = new Date(Number(y), Number(m), 0); // día 0 = último del mes anterior
    return pad2(d.getDate());
  };

  if (/^\d{4}-\d{2}-\d{2}$/.test(f)) {
    const [y, m, d] = f.split("-");
    return `${pad2(d)}/${pad2(m)}/${y}`;
  }

  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(f)) {
    const [d,m,y] = f.split('/');
    return `${pad2(d)}/${pad2(m)}/${y}`;
  }

  if (/^\d{4}-\d{2}$/.test(f)) {
    const [y, m] = f.split("-");
    const dd = lastDay(y, m);
    return `${dd}/${m}/${y}`;
  }

  if (/^\d{1,2}\/\d{4}$/.test(f)) {
    const [m, y] = f.split("/");
    const mm = pad2(m);
    const dd = lastDay(y, mm);
    return `${dd}/${mm}/${y}`;
  }

  if (/^\d{4}\/\d{1,2}$/.test(f)) {
    const [y, m] = f.split("/");
    const mm = pad2(m);
    const dd = lastDay(y, mm);
    return `${dd}/${mm}/${y}`;
  }

  return f; // ⚠️ Si no coincide con ningún patrón, no lo rompe.
}

