  function aggregate(items){
    const map=new Map();
    for(const raw of Array.isArray(items)?items:[]){
      const qty=num(raw?.pzs ?? raw?.cantidad ?? raw?.qty);
      if(qty<=0) continue;
      const p=identityParts(raw);
      const key=p.id ? `ID:${p.id}` : `${p.clave}|${p.barcode}|${p.lote}|${p.cad}`;
      const current=map.get(key) || Object.assign({},raw,{pzs:0});
      current.pzs=num(current.pzs)+qty;
      map.set(key,current);
    }
    return [...map.values()];
  }

  function branchCode(){
    const raw=typeof mxGetSucursalFromLicense==='function'?mxGetSucursalFromLicense():'HGAM';
    return norm(raw).replace(/[^A-Z0-9]/g,'').slice(0,14)||'HGAM';
  }

  function nextFolio(logs){
    const year=new Date().getFullYear(), branch=branchCode();
    const rx=new RegExp(`^TRF-${branch}-${year}-(\\d+)$`,'i');
    let max=0;
    for(const row of logs||[]){
      const match=txt(row?.folio).match(rx);
      if(match) max=Math.max(max,Number(match[1])||0);
    }
    return `TRF-${branch}-${year}-${String(max+1).padStart(6,'0')}`;
  }

  function stateMatches(row,expected,prefix){
    if(!row || !expected) return false;
    const loc=locations(row);
    return loc.almacen===num(expected[`${prefix}Almacen`]) && loc.estantes===num(expected[`${prefix}Estantes`]);
  }

  async function verifyInventory(expectedRows){
    if(typeof window.__mxFlushSqlWrites==='function') await window.__mxFlushSqlWrites();
    try{ await window.electronSql?.flush?.(); }catch(_e){}
    for(let attempt=0;attempt<3;attempt++){
      const rows=await freshAll('inventory');
      const errors=[];
      for(const expected of expectedRows){
        const row=rows.find((item)=>txt(item?._id)===txt(expected.inventoryId));
        const loc=locations(row);
        if(!row || loc.almacen!==num(expected.almacenDespues) || loc.estantes!==num(expected.estantesDespues)){
          errors.push(`${expected.clave} lote ${expected.lote||'—'}: esperado Almacén ${expected.almacenDespues}, Estantes ${expected.estantesDespues}; guardado Almacén ${loc.almacen}, Estantes ${loc.estantes}.`);
        }
      }
      if(!errors.length){
        try{ window.__mxSetInventoryMemory?.(rows,true); }catch(_e){}
        return rows;
      }
      if(attempt<2) await new Promise((resolve)=>setTimeout(resolve,120));
      else { const error=new Error('SQLite no confirmó las cantidades de la transferencia.'); error.details=errors; throw error; }
    }
    return [];
  }

  async function inspectExistingLog(existing){
    const expected=Array.isArray(existing?.items)?existing.items:(Array.isArray(existing?.resultado)?existing.resultado:[]);
    if(!expected.length) return {valid:false,repairable:false};
    const inventory=await freshAll('inventory');
    let after=true,before=true;
    for(const item of expected){
      const row=inventory.find((r)=>txt(r?._id)===txt(item.inventoryId));
      after=after && stateMatches(row,{afterAlmacen:item.almacenDespues,afterEstantes:item.estantesDespues},'after');
      before=before && stateMatches(row,{beforeAlmacen:item.almacenAntes,beforeEstantes:item.estantesAntes},'before');
    }
    return {valid:after,repairable:!after&&before};
  }

