(function(){
  if(window.__mxOperacionHardeningFinal) return;
  window.__mxOperacionHardeningFinal = true;

  const S = (v)=> (v==null ? '' : String(v));
  const qs  = (sel,root)=> (root||document).querySelector(sel);
  const qsa = (sel,root)=> Array.from((root||document).querySelectorAll(sel));

  if(typeof window.toStr !== 'function') window.toStr = S;
  if(typeof window.qs !== 'function') window.qs = qs;
  if(typeof window.qsa !== 'function') window.qsa = qsa;
  if(typeof window.$ !== 'function')   window.$ = qs;
  if(typeof window.$$ !== 'function')  window.$$ = qsa;

  
  
  function normalizeInventarioActions(){
    const table = qs('#tblInv');
    if(!table) return;

    const trHead = qs('#tblInv thead tr');
    if(trHead){
      qsa('th', trHead)
        .filter(th => S(th.textContent).trim().toLowerCase() === 'acciones')
        .forEach(th => th.remove());
    }

    qsa('#tblInv tbody tr').forEach(tr => {
      qsa('td[data-actions]', tr).forEach(td => td.remove());
    });
  }

  function protectTableRedraws(){
    [['drawInventario', normalizeInventarioActions], ['renderInventario', normalizeInventarioActions]].forEach(([fnName, afterFn]) => {
      const orig = window[fnName];
      if(typeof orig !== 'function' || orig.__mxPatchedSafe) return;
      const wrapped = async function(){
        const r = await orig.apply(this, arguments);
        try{ requestAnimationFrame(afterFn); }catch(e){}
        return r;
      };
      wrapped.__mxPatchedSafe = true;
      window[fnName] = wrapped;
    });
  }

  function wireLoginSafety(){
    const btn = qs('#btnLogin');
    if(!btn || btn.__mxPatchedLogin) return;
    btn.__mxPatchedLogin = true;
    // boot() ya prepara la base. No se abre de nuevo en cada clic de acceso.
  }

  let __mxHardeningStarted = false;
  function initialRun(){
    if(__mxHardeningStarted) return;
    __mxHardeningStarted = true;
    wireLoginSafety();
    protectTableRedraws();
    normalizeInventarioActions();
  }

  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initialRun, {once:true});
  else initialRun();
})();


