let __mxFirebaseProbeState='warning';
let __mxFirebaseProbeMessage='Sin comprobar';
let __mxFirebaseProbeRunning=false;
let __mxFirebaseProbeAt=0;
function mxRenderFirebaseHeaderStatus(){
  try{
    const badge = document.getElementById('mxFirebaseStatus');
    if(!badge) return;
    const configured=(typeof mxConfiguredRemoteDbUrl==='function'?mxConfiguredRemoteDbUrl():'')||'';
    const enabled=typeof mxRemoteDbEnabled==='function'?mxRemoteDbEnabled():true;
    const url=(typeof mxRemoteDbUrl==='function'?mxRemoteDbUrl():'')||'';
    if(configured&&!enabled){badge.hidden=false;badge.style.display='';badge.classList.remove('connected','warning');badge.classList.add('offline');badge.title=`Firebase desconectado\n${configured}`;badge.setAttribute('aria-label','Firebase desconectado');return;}
    if(!url){badge.hidden=true;badge.style.display='none';badge.classList.remove('connected','warning','offline');badge.title='';badge.setAttribute('aria-label','');return;}
    badge.hidden=false;
    badge.style.display='';
    const online = navigator.onLine !== false;
    let state='warning',message='Comprobando Firebase';
    if(!online){ state='offline'; message='Sin Internet'; }
    else { state=__mxFirebaseProbeState||'warning'; message=__mxFirebaseProbeMessage||'Comprobando Firebase'; }
    badge.classList.remove('connected','warning','offline');
    badge.classList.add(state);
    badge.title=(url?`${message}\n${url}`:`${message}\nSin URL configurada`);
    badge.setAttribute('aria-label',message);
  }catch(e){}
}
async function mxProbeFirebaseConnection(force=false){
  if(typeof mxRemoteDbEnabled==='function'&&!mxRemoteDbEnabled()){__mxFirebaseProbeState='offline';__mxFirebaseProbeMessage='Firebase desconectado';mxRenderFirebaseHeaderStatus();return false;}
  const url=(typeof mxRemoteDbUrl==='function'?mxRemoteDbUrl():'')||'';
  if(!url||navigator.onLine===false){__mxFirebaseProbeState=url?'offline':'warning';__mxFirebaseProbeMessage=url?'Firebase sin conexión':'Firebase sin URL';mxRenderFirebaseHeaderStatus();return false;}
  if(__mxFirebaseProbeRunning)return false;
  if(!force&&Date.now()-__mxFirebaseProbeAt<15000){mxRenderFirebaseHeaderStatus();return __mxFirebaseProbeState==='connected';}
  __mxFirebaseProbeRunning=true;__mxFirebaseProbeState='warning';__mxFirebaseProbeMessage='Comprobando Firebase';mxRenderFirebaseHeaderStatus();
  try{
    const probeBranch=(typeof mxGetSucursalFromLicense==='function'?(String(mxGetSucursalFromLicense()||'').trim().toUpperCase()||'HGAM'):'HGAM');
    const probePath='/inventory_heartbeat/'+encodeURIComponent(probeBranch);
    const r=await mxFirebaseRequestAcrossPool(probePath,{timeout:8000,cache:'no-store'},true);
    if(!r.ok)throw new Error(`HTTP ${r.status}`);
    __mxFirebaseProbeState='connected'; __mxFirebaseProbeMessage=`Firebase conectado · servidor ${(mxRemoteDbPool().urls.indexOf(mxConfiguredRemoteDbUrl())+1)||1}/${mxRemoteDbPool().urls.length||1}`;
    return true;
  }catch(e){__mxFirebaseProbeState='offline';__mxFirebaseProbeMessage=`Firebase sin acceso (${e?.message||'error'})`;return false;}
  finally{__mxFirebaseProbeRunning=false;__mxFirebaseProbeAt=Date.now();mxRenderFirebaseHeaderStatus();}
}

