function mxEnsureConfigCardPosition(card, preferredAfterId){
  const view = document.getElementById('view-configuracion');
  if(!view || !card) return;
  if(card.parentNode !== view){
    const anchor = preferredAfterId ? document.getElementById(preferredAfterId) : null;
    if(anchor && anchor.parentNode === view) anchor.insertAdjacentElement('afterend', card);
    else {
      const h3 = view.querySelector(':scope > h3');
      if(h3 && h3.parentNode === view) h3.insertAdjacentElement('afterend', card);
      else view.prepend(card);
    }
  }
}



