/* ===== MACROXEL CANONICAL SOURCE: mx-global-processing-controller ===== */
(function(){
  if(window.__mxBusyInstalled) return;
  window.__mxBusyInstalled = true;

  const state = {
    visible: false,
    timer: null,
    lastMessage: 'Espera un momento, el sistema está realizando la operación.',
    lastMini: 'Procesando…'
  };

  const WATCHED_CLICK_IDS = {
    btnImpInv: 'Importando inventario…',
    btnImpEnt: 'Importando entradas…',
    btnImpSal: 'Importando salidas…',
    btnBackupLoad: 'Restaurando respaldo…',
    btnBackupSave: 'Generando respaldo…',
    btnActualizarInventario: 'Actualizando inventario…',
    btnDepurarInv: 'Depurando inventario…',
    btnClrMov: 'Eliminando historial de movimientos…',
    btnClrSal: 'Eliminando historial de salidas…',
    btnClrEnt: 'Eliminando historial de entradas…',
    btnClrAbHist1M: 'Eliminando historial de antibióticos…',
    btnClrInv: 'Eliminando registros de inventario…',
    
    
    
    mxCatImportBtn: 'Importando archivo…'
  };

  const WATCHED_FILE_IDS = {
    fileInv: 'Importando inventario…',
    fileEnt: 'Importando entradas…',
    fileSal: 'Importando salidas…',
    
    backupFile: 'Restaurando respaldo…',
    mxCatImportFile: 'Importando archivo…'
  };

  function qs(id){ return document.getElementById(id); }
  function miniText(msg){ return String(msg || 'Procesando…').replace(/\s+/g,' ').trim(); }

  function setTexts(msg, mini){
    state.lastMessage = msg || state.lastMessage;
    state.lastMini = mini || miniText(state.lastMessage);
    const full = qs('mxBusyText');
    const sm = qs('mxBusyMiniText');
    if(full) full.textContent = state.lastMessage;
    if(sm) sm.textContent = state.lastMini;
  }

  function paint(show){
    const overlay = qs('mxBusyOverlay');
    const mini = qs('mxBusyMini');
    if(!overlay || !mini) return;
    if(show){
      overlay.classList.add('show');
      mini.classList.add('show');
      document.body.classList.add('mx-busy-cursor');
      state.visible = true;
    }else{
      overlay.classList.remove('show');
      mini.classList.remove('show');
      document.body.classList.remove('mx-busy-cursor');
      state.visible = false;
    }
  }

  function clearBusy(){
    clearTimeout(state.timer);
    paint(false);
  }

  window.mxBusyStart = function(msg, opts){
    opts = opts || {};
    clearTimeout(state.timer);
    setTexts(msg || 'Procesando…', opts.mini);
    paint(true);
    if(opts.autoHideMs){
      state.timer = setTimeout(clearBusy, Math.max(400, Number(opts.autoHideMs || 0)));
    }
  };

  window.mxBusyEnd = function(){
    clearBusy();
  };

  window.mxBusyPulse = function(msg, ms){
    window.mxBusyStart(msg, {autoHideMs: ms || 1800});
  };

  document.addEventListener('click', function(ev){
    const el = ev.target && ev.target.closest ? ev.target.closest('button,.btn,[type="button"],[type="submit"]') : null;
    if(!el) return;
    const msg = WATCHED_CLICK_IDS[el.id || ''];
    if(!msg) return;
    window.mxBusyPulse(msg, 2500);
  }, true);

  document.addEventListener('change', function(ev){
    const el = ev.target;
    if(!el) return;
    const msg = WATCHED_FILE_IDS[el.id || ''] || (el.type === 'file' ? 'Importando archivo…' : '');
    if(!msg) return;
    const hasFiles = !('files' in el) || (el.files && el.files.length > 0);
    if(hasFiles) window.mxBusyPulse(msg, 3000);
  }, true);

  window.addEventListener('load', function(){
    setTimeout(clearBusy, 120);
  });
  document.addEventListener('visibilitychange', function(){
    if(!document.hidden) setTimeout(clearBusy, 120);
  });
  window.addEventListener('pageshow', function(){
    setTimeout(clearBusy, 120);
  });
  window.addEventListener('error', clearBusy);
  window.addEventListener('unhandledrejection', clearBusy);
})();


