/* ===== MACROXEL CANONICAL SOURCE: mx-inventory-export-menu-script ===== */
(function(){
  function initInventoryExportMenu(){
    const wrap = document.getElementById('mxInvExportWrap');
    const trigger = document.getElementById('btnInvFilesMenu');
    const menu = document.getElementById('mxInvExportMenu');
    if(!wrap || !trigger || !menu || trigger.dataset.mxBound==='1') return;
    trigger.dataset.mxBound='1';

    function setOpen(open){
      wrap.classList.toggle('open', !!open);
      trigger.setAttribute('aria-expanded', open ? 'true' : 'false');
      menu.setAttribute('aria-hidden', open ? 'false' : 'true');
      if(open){
        const first = menu.querySelector('button:not([disabled])');
        if(first) requestAnimationFrame(()=>first.focus());
      }
    }

    trigger.addEventListener('click', function(ev){
      ev.preventDefault();
      ev.stopPropagation();
      setOpen(!wrap.classList.contains('open'));
    });

    menu.addEventListener('click', function(ev){
      const option = ev.target.closest('.mx-inv-export-option');
      if(option) setTimeout(()=>setOpen(false), 0);
    });

    menu.addEventListener('keydown', function(ev){
      const options = Array.from(menu.querySelectorAll('.mx-inv-export-option:not([disabled])'));
      const index = options.indexOf(document.activeElement);
      if(ev.key==='Escape'){
        ev.preventDefault(); setOpen(false); trigger.focus(); return;
      }
      if((ev.key==='ArrowDown' || ev.key==='ArrowUp') && options.length){
        ev.preventDefault();
        const delta = ev.key==='ArrowDown' ? 1 : -1;
        const next = index < 0 ? 0 : (index + delta + options.length) % options.length;
        options[next].focus();
      }
    });

    document.addEventListener('click', function(ev){
      if(!wrap.contains(ev.target)) setOpen(false);
    });
    document.addEventListener('keydown', function(ev){
      if(ev.key==='Escape' && wrap.classList.contains('open')){ setOpen(false); trigger.focus(); }
    });
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', initInventoryExportMenu, {once:true});
  else initInventoryExportMenu();
})();


/* ===== MACROXEL CANONICAL SOURCE: mx-v86-safe-cancel-buttons ===== */
(function(){
  const modalByButton = {
    medCancel:'medModal',
    salQuickMedCancel:'salQuickMedModal',
    cpmCancel:'cpmAddModal',
    invCancel:'invEditModal',
  };
  function bind(){
    Object.entries(modalByButton).forEach(([buttonId, modalId])=>{
      const button = document.getElementById(buttonId);
      if(!button || button.dataset.mxCancelSafe==='1') return;
      button.dataset.mxCancelSafe='1';
      button.type='button';
      button.addEventListener('click', function(ev){
        ev.preventDefault();
        ev.stopImmediatePropagation();
        const modal = document.getElementById(modalId);
        if(modal){ modal.classList.remove('show'); modal.style.display=''; modal.setAttribute('aria-hidden','true'); }
        try{ if(buttonId==='medCancel') medEditId=null; }catch(_e){}
      }, true);
    });
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', bind, {once:true});
  else bind();
})();


/* ===== MACROXEL CANONICAL SOURCE: mx90-sidebar-canonical-script ===== */
(function(){
  function mountSidebar(){
    const nav=document.getElementById('navTabs');
    if(!nav) return;
    /* El menú deja de depender del flujo y la altura de la cabecera. */
    if(nav.parentElement!==document.body) document.body.appendChild(nav);
    nav.style.removeProperty('height');
    nav.style.removeProperty('max-height');
    if(!document.body.classList.contains('mx-module-open')) nav.scrollTop=0;
  }
  function resetHomeScroll(){
    const nav=document.getElementById('navTabs');
    if(nav && !document.body.classList.contains('mx-module-open')) nav.scrollTop=0;
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',mountSidebar,{once:true});
  else mountSidebar();
  window.addEventListener('load',function(){mountSidebar();resetHomeScroll();},{once:true});
  document.addEventListener('click',function(ev){
    const tab=ev.target && ev.target.closest ? ev.target.closest('#navTabs .tab') : null;
    if(tab) requestAnimationFrame(resetHomeScroll);
  });
  const bodyObserver=new MutationObserver(function(){
    if(!document.body.classList.contains('mx-module-open')) requestAnimationFrame(function(){mountSidebar();resetHomeScroll();});
  });
  bodyObserver.observe(document.body,{attributes:true,attributeFilter:['class']});
})();


