(function(){
  if(window.__mxMiCpmV96Installed) return;
  window.__mxMiCpmV96Installed=true;
  const STORAGE_KEY='mx_mi_cpm_asignado_v1';
  const legacyGetBase = (typeof window.mxGetBaseClavesTotal==='function') ? window.mxGetBaseClavesTotal.bind(window) : (()=>520);
  let editKey='';
  let selectedKey='';
  let lastRendered=[];

  const clean=v=>String(v==null?'':v).trim();
  const norm=v=>clean(v).toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Z0-9]/g,'');
  const low=v=>clean(v).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const esc=v=>String(v==null?'':v).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const num=v=>{const n=Number(v);return Number.isFinite(n)?n:0;};

  function normalizeRecord(r){
    r=r||{};
    const clave=clean(r.clave||r.csg||r.codigo||r['doce digitos (csg)']||r['doce dígitos (csg)']);
    const numeroRaw=r.numero??r.no??r['no.']??r.num??r.n;
    const numero=Math.max(0,Math.floor(num(numeroRaw)));
    const grupoTerapeutico=clean(r.grupoTerapeutico||r.grupo_terapeutico||r['grupo terapéutico']||r['grupo terapeutico']||r.grupo);
    const hospitalQty=Math.max(0,num(r.hospitalGeneralAjuscoMedio??r['hospital general ajusco medio']??r.pzsAsignadas??r.pzs_asignadas??r['pzs asignadas']??r.pzs));
    return {
      numero,
      clave,
      key:norm(clave),
      descripcion:clean(r.descripcion||r.descripción||r.nombre||r.producto),
      gpo:clean(r.gpo||r['gpo.']||r.grupoNumero||r.grupo_numero),
      grupoTerapeutico,
      hospitalGeneralAjuscoMedio:hospitalQty,
      /* Alias internos para conservar compatibilidad con cálculos y respaldos anteriores. */
      grupo:grupoTerapeutico,
      pzsAsignadas:hospitalQty,
      costo:Math.max(0,num(r.costo??r.costo_unitario??r['costo unitario'])),
      precio_venta:Math.max(0,num(r.precio_venta??r.precioVenta??r['precio de venta']??r['precio venta'])),
      iva_pct:Math.max(0,num(r.iva_pct??r.ivaPct??r['iva %']??r.iva)),
      ieps_pct:Math.max(0,num(r.ieps_pct??r.iepsPct??r['ieps %']??r.ieps))
    };
  }
  function readCatalog(){
    try{
      const raw=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');
      const map=new Map();
      (Array.isArray(raw)?raw:[]).forEach(x=>{const r=normalizeRecord(x);if(r.key)map.set(r.key,r);});
      return Array.from(map.values()).sort((a,b)=>(num(a.numero)||999999)-(num(b.numero)||999999)||(a.descripcion||a.clave).localeCompare(b.descripcion||b.clave,'es',{sensitivity:'base'}));
    }catch(_e){return [];}
  }
  function saveCatalog(rows){
    const map=new Map();
    (Array.isArray(rows)?rows:[]).forEach(x=>{const r=normalizeRecord(x);if(r.key)map.set(r.key,r);});
    const out=Array.from(map.values()).sort((a,b)=>(num(a.numero)||999999)-(num(b.numero)||999999)||(a.descripcion||a.clave).localeCompare(b.descripcion||b.clave,'es',{sensitivity:'base'}));
    localStorage.setItem(STORAGE_KEY,JSON.stringify(out));
    return out;
  }
  function inventoryMap(invRows){
    const map=new Map();
    (Array.isArray(invRows)?invRows:[]).forEach(r=>{
      const key=norm(r?.clave||r?.csg||r?.codigo); if(!key)return;
      const direct=Number(r?.existencia);
      const ex=Number.isFinite(direct) ? direct : num(r?.almacen)+num(r?.estantes);
      const prev=map.get(key)||{existencia:0,descripcion:'',unidad:''};
      prev.existencia+=Number.isFinite(ex)?ex:0;
      if(!prev.descripcion)prev.descripcion=clean(r?.descripcion||r?.nombre);
      if(!prev.unidad)prev.unidad=clean(r?.unidad);
      map.set(key,prev);
    });
    return map;
  }
  function computeStats(invRows){
    const catalog=readCatalog();
    const inv=inventoryMap(invRows);
    if(catalog.length){
      let con=0;
      const rows=catalog.map(r=>{
        const meta=inv.get(r.key)||{existencia:0};
        const existencia=num(meta.existencia);
        if(existencia>0)con++;
        return Object.assign({},r,{existencia,estado:existencia>0?'CON EXISTENCIA':'DESABASTO'});
      });
      const keys=new Set(catalog.map(r=>r.key));
      let extras=0; for(const [k,v] of inv.entries())if(!keys.has(k)&&num(v.existencia)>0)extras++;
      const base=catalog.length,sin=Math.max(0,base-con);
      return {catalogActive:true,base,conExist:con,sinExist:sin,pctCon:base?con/base*100:0,pctSin:base?sin/base*100:0,extras,inventoryUnique:inv.size,rows};
    }
    const base=Math.max(1,num(legacyGetBase())||520);
    let real=0;for(const v of inv.values())if(num(v.existencia)>0)real++;
    const con=Math.min(base,real),sin=Math.max(0,base-con);
    return {catalogActive:false,base,conExist:con,sinExist:sin,pctCon:base?con/base*100:0,pctSin:base?sin/base*100:0,extras:0,inventoryUnique:inv.size,rows:[]};
  }
  window.mxMiCpmRead=readCatalog;
  window.mxMiCpmComputeStats=computeStats;
  window.mxGetBaseClavesTotal=function(){const n=readCatalog().length;return n||legacyGetBase();};
  window.mxComputeClavesStatsFromInv=function(invRows){
    const s=computeStats(invRows);return {total:s.base,conExist:s.conExist,sinExist:s.sinExist,extras:s.extras,catalogActive:s.catalogActive};
  };

  async function getInventory(){try{if(typeof ensureDBReady==='function')await ensureDBReady();return (typeof idbAll==='function'?await idbAll('inventory'):[])||[];}catch(_e){return [];}}
  function paintKpi(el,pct,invert){
    if(!el||!el.parentElement)return;const card=el.parentElement;card.classList.remove('kpi-ok','kpi-warn','kpi-bad','kpi-neutral');
    let cls='kpi-bad';if(invert){if(pct<=5)cls='kpi-ok';else if(pct<=20)cls='kpi-warn';}else{if(pct>=95)cls='kpi-ok';else if(pct>=80)cls='kpi-warn';}card.classList.add(cls);
  }
  async function applyDashboardStats(invRows){
    const inv=Array.isArray(invRows)?invRows:await getInventory();const s=computeStats(inv);
    const baseInput=document.getElementById('baseClavesTotal');
    if(baseInput){baseInput.value=String(s.base);baseInput.readOnly=!!s.catalogActive;baseInput.title=s.catalogActive?'Base calculada automáticamente con Mi Catálogo':'Base manual de respaldo; cargue Mi Catálogo para usar las claves asignadas';}
    const hint=document.getElementById('dispoBaseHint');if(hint)hint.textContent=s.catalogActive?`Mi Catálogo activo: ${s.base.toLocaleString('es-MX')} claves asignadas`:`Base manual: ${s.base.toLocaleString('es-MX')} claves · Cargue Mi Catálogo`;
    const note=document.getElementById('dispoStatsNote');if(note)note.textContent=`Asignadas con existencia: ${s.conExist.toLocaleString('es-MX')} (${s.pctCon.toFixed(1)}%) · Desabasto: ${s.sinExist.toLocaleString('es-MX')} (${s.pctSin.toFixed(1)}%)${s.catalogActive?` · Claves extra ignoradas: ${s.extras.toLocaleString('es-MX')}`:''}`;
    const con=document.getElementById('kpiPzs'),sin=document.getElementById('kpiIn'),pct=document.getElementById('kpiOut'),base=document.getElementById('kpiBaseLabel');
    if(con)con.textContent=`${s.conExist.toLocaleString('es-MX')} (${s.pctCon.toFixed(1)}%)`;
    if(sin)sin.textContent=`${s.sinExist.toLocaleString('es-MX')} (${s.pctSin.toFixed(1)}%)`;
    if(pct)pct.textContent=`${s.pctCon.toFixed(1)}%`;
    if(base)base.textContent=s.catalogActive?`Mi Catálogo: ${s.base.toLocaleString('es-MX')}`:`Base: ${s.base.toLocaleString('es-MX')}`;
    paintKpi(con,s.pctCon,false);paintKpi(sin,s.pctSin,true);paintKpi(pct,s.pctCon,false);
    return s;
  }
  window.mxUpdateClavesDashboardNote=function(invRows){return applyDashboardStats(invRows);};

  async function refreshAvailabilityChart(invRows){
    const inv=Array.isArray(invRows)?invRows:await getInventory();const s=await applyDashboardStats(inv);
    const canvas=document.getElementById('chartDisponibilidad520');if(!canvas||typeof Chart!=='function')return s;
    try{const old=(typeof Chart.getChart==='function')?Chart.getChart(canvas):null;if(old)old.destroy();}catch(_e){}
    try{new Chart(canvas,{type:'doughnut',data:{labels:[`Con existencia (${s.conExist} · ${s.pctCon.toFixed(1)}%)`,`Desabasto (${s.sinExist} · ${s.pctSin.toFixed(1)}%)`],datasets:[{data:[s.conExist,s.sinExist],backgroundColor:['#16a34a','#dc2626']}]},options:{responsive:true,maintainAspectRatio:false}});}catch(_e){}
    return s;
  }

  const originalRenderDashboard=window.renderDashboard;
  if(typeof originalRenderDashboard==='function')window.renderDashboard=async function(){const r=await originalRenderDashboard.apply(this,arguments);await applyDashboardStats();return r;};
  const originalRenderDashboardCharts=window.renderDashboardCharts;
  if(typeof originalRenderDashboardCharts==='function')window.renderDashboardCharts=async function(){const r=await originalRenderDashboardCharts.apply(this,arguments);await refreshAvailabilityChart();return r;};
  const originalDrawInventario=window.drawInventario;
  if(typeof originalDrawInventario==='function')window.drawInventario=async function(){const r=await originalDrawInventario.apply(this,arguments);try{const inv=await getInventory();const s=computeStats(inv);const note=document.getElementById('invStatsNote');if(note)note.textContent=s.catalogActive?`Filas: ${inv.length.toLocaleString('es-MX')} · Claves de Mi Catálogo: ${s.base.toLocaleString('es-MX')} · Abasto real: ${s.conExist.toLocaleString('es-MX')} (${s.pctCon.toFixed(1)}%) · Desabasto: ${s.sinExist.toLocaleString('es-MX')} (${s.pctSin.toFixed(1)}%) · Claves extra ignoradas: ${s.extras.toLocaleString('es-MX')}`:`Filas: ${inv.length.toLocaleString('es-MX')} · Base manual: ${s.base.toLocaleString('es-MX')} · Cargue Mi Catálogo para calcular el abasto real por claves asignadas.`;}catch(_e){}return r;};

  async function exportAvailability(){
    try{
      const catalog=readCatalog();if(!catalog.length)return mxAlert('Primero carga tus claves asignadas en Configuración > Mi Catálogo.');
      const inv=await getInventory();const s=computeStats(inv);
      const exactRow=(r,index)=>({
        'No.':Number(r.numero)||index+1,
        'CLAVE':r.clave,
        'DESCRIPCIÓN':r.descripcion,
        'GPO':r.gpo,
        'GRUPO TERAPEUTICO':r.grupoTerapeutico,
        'HOSPITAL GENERAL AJUSCO MEDIO':r.hospitalGeneralAjuscoMedio,
        ...(typeof window.mxFinancialEnabled==='function'&&window.mxFinancialEnabled()?{'COSTO':r.costo||0,'PRECIO VENTA':r.precio_venta||0,'IVA %':r.iva_pct||0,'IEPS %':r.ieps_pct||0}:{})
      });
      const rows=s.rows.map(exactRow);
      const conRows=s.rows.filter(r=>r.existencia>0).map(exactRow);
      const sinRows=s.rows.filter(r=>r.existencia<=0).map(exactRow);
      const resumen=[{INDICADOR:'Claves asignadas Mi Catálogo',VALOR:s.base,PORCENTAJE:'100.0%'},{INDICADOR:'Con existencia',VALOR:s.conExist,PORCENTAJE:s.pctCon.toFixed(1)+'%'},{INDICADOR:'Desabasto',VALOR:s.sinExist,PORCENTAJE:s.pctSin.toFixed(1)+'%'},{INDICADOR:'Claves extra de inventario ignoradas',VALOR:s.extras,PORCENTAJE:''}];
      const wb=XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(resumen),'RESUMEN');
      XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'MI_CPM');
      XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(conRows),'CON_EXISTENCIA');
      XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(sinRows),'DESABASTO');
      const d=new Date(),tag=`${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`;XLSX.writeFile(wb,`MI_CPM_ABASTO_REAL_${tag}.xlsx`);
    }catch(e){console.error(e);mxAlert('No se pudo exportar Mi Catálogo: '+(e?.message||e));}
  }

  function makeSection(){
    if(document.getElementById('mxMiCpmSection'))return;
    const view=document.getElementById('view-configuracion');if(!view)return;
    const sec=document.createElement('div');sec.className='cfg-section';sec.id='mxMiCpmSection';
    sec.innerHTML=`<h4 class="cfg-title">📋 Mi Catálogo</h4>
      <div class="mx-mi-cpm-help"><b>Catálogo manual de configuración.</b> Aquí las claves se agregan o importan manualmente. En modo Financiero también puedes guardar costo, precio de venta, IVA e IEPS. Este catálogo no recibe altas automáticas desde Entradas.</div>
      <div class="mx-mi-cpm-kpis"><div class="mx-mi-cpm-kpi"><span>Claves asignadas</span><b id="mxMiCpmKBase">0</b></div><div class="mx-mi-cpm-kpi"><span>Con existencia</span><b id="mxMiCpmKCon">0</b></div><div class="mx-mi-cpm-kpi"><span>Desabasto</span><b id="mxMiCpmKSin">0</b></div><div class="mx-mi-cpm-kpi"><span>Abasto real</span><b id="mxMiCpmKPct">0.0%</b></div><div class="mx-mi-cpm-kpi"><span>Extras ignoradas</span><b id="mxMiCpmKExtra">0</b></div></div>
      <div class="mx-mi-cpm-import"><input accept=".xlsx,.xls,.csv,.xlsm" class="file" id="mxMiCpmFile" type="file"><button class="btn ok cfg-btn" id="mxMiCpmImport" type="button">📥 Cargar Mi Catálogo</button><button class="btn cfg-btn" id="mxMiCpmExport" type="button">⬇️ Exportar</button><button class="btn danger cfg-btn" id="mxMiCpmDeleteAll" type="button">🗑️ Eliminar listado</button></div>
      <div class="mx-mi-cpm-note"><b>Encabezados detectados:</b> No. · CLAVE · DESCRIPCIÓN · GPO · GRUPO TERAPEUTICO · HOSPITAL GENERAL AJUSCO MEDIO. El sistema localiza automáticamente la fila del encabezado e ignora cualquier columna adicional.</div>
      <div class="mx-mi-cpm-form"><input class="input" id="mxMiCpmNumero" min="0" placeholder="No." type="number"><input class="input" id="mxMiCpmClave" placeholder="CLAVE"><input class="input" id="mxMiCpmDesc" placeholder="DESCRIPCIÓN"><input class="input" id="mxMiCpmGpo" placeholder="GPO"><input class="input" id="mxMiCpmGrupoTer" placeholder="GRUPO TERAPÉUTICO"><input class="input" id="mxMiCpmHospital" min="0" placeholder="HOSPITAL GENERAL AJUSCO MEDIO" type="number"></div><div class="mx-catalog-fin-grid" id="mxMiCpmFinance"><label>Costo unitario<input class="input" id="mxMiCpmCosto" min="0" step="0.0001" type="number" placeholder="0.00"></label><label>Precio de venta<input class="input" id="mxMiCpmPrecio" min="0" step="0.01" type="number" placeholder="0.00"></label><label>IVA %<input class="input" id="mxMiCpmIva" min="0" max="100" step="0.01" type="number" placeholder="0"></label><label>IEPS %<input class="input" id="mxMiCpmIeps" min="0" max="100" step="0.01" type="number" placeholder="0"></label></div>
      <div class="mx-mi-cpm-actions"><button class="btn ok cfg-btn" id="mxMiCpmSave" type="button">➕ Agregar / actualizar</button><button class="btn cfg-btn" id="mxMiCpmClear" type="button">Limpiar campos</button><button class="btn danger cfg-btn" id="mxMiCpmDeleteSelected" type="button" disabled>🗑️ Eliminar seleccionada</button><input class="input" id="mxMiCpmSearch" placeholder="🔎 Buscar por clave, descripción o grupo terapéutico" style="flex:1 1 320px;"></div>
      <div class="mx-mi-cpm-note">Clic selecciona una fila; doble clic abre sus datos para editar.</div>
      <div class="mx-mi-cpm-table-wrap"><table class="table" id="mxMiCpmTable"><thead><tr><th>No.</th><th>CLAVE</th><th>DESCRIPCIÓN</th><th>GPO</th><th>GRUPO TERAPÉUTICO</th><th>HOSPITAL GENERAL AJUSCO MEDIO</th><th class="mx-catalog-fin-col">COSTO</th><th class="mx-catalog-fin-col">PRECIO VENTA</th><th class="mx-catalog-fin-col">IVA %</th><th class="mx-catalog-fin-col">IEPS %</th></tr></thead><tbody></tbody></table></div><div class="mx-mi-cpm-note" id="mxMiCpmRowsNote"></div>`;
    const backup=document.getElementById('mxBackupConfigSection');if(backup&&backup.parentNode===view)view.insertBefore(sec,backup);else view.appendChild(sec);
    setTimeout(()=>{try{window.mxInitConfigAccordions?.();}catch(_e){}},0);
  }

  function formRecord(){return normalizeRecord({numero:document.getElementById('mxMiCpmNumero')?.value,clave:document.getElementById('mxMiCpmClave')?.value,descripcion:document.getElementById('mxMiCpmDesc')?.value,gpo:document.getElementById('mxMiCpmGpo')?.value,grupoTerapeutico:document.getElementById('mxMiCpmGrupoTer')?.value,hospitalGeneralAjuscoMedio:document.getElementById('mxMiCpmHospital')?.value,costo:document.getElementById('mxMiCpmCosto')?.value,precio_venta:document.getElementById('mxMiCpmPrecio')?.value,iva_pct:document.getElementById('mxMiCpmIva')?.value,ieps_pct:document.getElementById('mxMiCpmIeps')?.value});}
  function clearForm(){editKey='';selectedKey='';['mxMiCpmNumero','mxMiCpmClave','mxMiCpmDesc','mxMiCpmGpo','mxMiCpmGrupoTer','mxMiCpmHospital','mxMiCpmCosto','mxMiCpmPrecio','mxMiCpmIva','mxMiCpmIeps'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});const b=document.getElementById('mxMiCpmSave');if(b)b.textContent='➕ Agregar / actualizar';const del=document.getElementById('mxMiCpmDeleteSelected');if(del)del.disabled=true;document.querySelectorAll('#mxMiCpmTable tbody tr').forEach(tr=>tr.classList.remove('mx-mi-cpm-selected'));}
  function fillForm(r){editKey=r.key;selectedKey=r.key;const vals={mxMiCpmNumero:r.numero,mxMiCpmClave:r.clave,mxMiCpmDesc:r.descripcion,mxMiCpmGpo:r.gpo,mxMiCpmGrupoTer:r.grupoTerapeutico,mxMiCpmHospital:r.hospitalGeneralAjuscoMedio,mxMiCpmCosto:r.costo,mxMiCpmPrecio:r.precio_venta,mxMiCpmIva:r.iva_pct,mxMiCpmIeps:r.ieps_pct};Object.entries(vals).forEach(([id,v])=>{const el=document.getElementById(id);if(el)el.value=v??'';});const b=document.getElementById('mxMiCpmSave');if(b)b.textContent='💾 Guardar cambios';const del=document.getElementById('mxMiCpmDeleteSelected');if(del)del.disabled=false;document.getElementById('mxMiCpmClave')?.focus();}
  function selectRecord(r,rowEl){selectedKey=r?.key||'';document.querySelectorAll('#mxMiCpmTable tbody tr').forEach(tr=>tr.classList.toggle('mx-mi-cpm-selected',tr===rowEl));const del=document.getElementById('mxMiCpmDeleteSelected');if(del)del.disabled=!selectedKey;}

  async function renderSection(){
    makeSection();const inv=await getInventory();const s=computeStats(inv);const catalog=readCatalog();const q=low(document.getElementById('mxMiCpmSearch')?.value||'');
    const shown=s.catalogActive?s:{base:0,conExist:0,sinExist:0,pctCon:0,extras:0,rows:[]};
    const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v;};set('mxMiCpmKBase',shown.base.toLocaleString('es-MX'));set('mxMiCpmKCon',shown.conExist.toLocaleString('es-MX'));set('mxMiCpmKSin',shown.sinExist.toLocaleString('es-MX'));set('mxMiCpmKPct',shown.pctCon.toFixed(1)+'%');set('mxMiCpmKExtra',shown.extras.toLocaleString('es-MX'));
    const rows=(s.catalogActive?s.rows:catalog).filter(r=>!q||low([r.numero,r.clave,r.descripcion,r.gpo,r.grupoTerapeutico,r.hospitalGeneralAjuscoMedio].join(' ')).includes(q));lastRendered=rows;
    const tb=document.querySelector('#mxMiCpmTable tbody');
    if(tb)tb.innerHTML=rows.slice(0,500).map((r,i)=>`<tr data-micpm-index="${i}" data-micpm-key="${esc(r.key)}" class="${selectedKey===r.key?'mx-mi-cpm-selected':''}"><td class="mx-mi-cpm-no-cell">${num(r.numero)||i+1}</td><td><span class="mx-mi-cpm-status-dot ${r.existencia>0?'ok':'zero'}" title="${r.existencia>0?'Con existencia':'Desabasto'}"></span><b>${esc(r.clave)}</b></td><td>${esc(r.descripcion)}</td><td>${esc(r.gpo)}</td><td>${esc(r.grupoTerapeutico)}</td><td>${num(r.hospitalGeneralAjuscoMedio)}</td><td class="mx-catalog-fin-col">$${num(r.costo).toFixed(2)}</td><td class="mx-catalog-fin-col">$${num(r.precio_venta).toFixed(2)}</td><td class="mx-catalog-fin-col">${num(r.iva_pct).toFixed(2)}%</td><td class="mx-catalog-fin-col">${num(r.ieps_pct).toFixed(2)}%</td></tr>`).join('')||'<tr><td colspan="10" style="text-align:center;padding:18px;">Sin claves cargadas en Mi Catálogo.</td></tr>';
    set('mxMiCpmRowsNote',rows.length>500?`Mostrando 500 de ${rows.length.toLocaleString('es-MX')} claves filtradas.`:`${rows.length.toLocaleString('es-MX')} clave(s) mostrada(s). Los puntos verde/rojo junto a la clave indican existencia o desabasto sin agregar columnas.`);
    const del=document.getElementById('mxMiCpmDeleteSelected');if(del)del.disabled=!selectedKey;
    await applyDashboardStats(inv);
  }

  async function parseImport(file){
    if(!file)throw new Error('Selecciona un archivo.');
    if(typeof XLSX==='undefined')throw new Error('No está disponible el lector de Excel.');
    const wb=XLSX.read(await file.arrayBuffer(),{type:'array'});
    const out=[];
    const headerKey=v=>low(v).replace(/[^a-z0-9]+/g,' ').trim();
    const aliases={
      numero:['no','numero','num'],
      clave:['clave','csg','doce digitos csg'],
      descripcion:['descripcion','nombre','producto'],
      gpo:['gpo'],
      grupoTerapeutico:['grupo terapeutico'],
      hospitalGeneralAjuscoMedio:['hospital general ajusco medio'],
      costo:['costo','costo unitario'],precio_venta:['precio venta','precio de venta'],iva_pct:['iva','iva %'],ieps_pct:['ieps','ieps %']
    };
    const findCol=(headers,names)=>{for(let i=0;i<headers.length;i++){if(names.includes(headers[i]))return i;}return -1;};
    let recognizedSheet=false;
    for(const sn of wb.SheetNames){
      const matrix=XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,defval:'',raw:false,blankrows:false});
      let headerRow=-1,cols=null;
      for(let i=0;i<Math.min(matrix.length,30);i++){
        const headers=(matrix[i]||[]).map(headerKey);
        const candidate={numero:findCol(headers,aliases.numero),clave:findCol(headers,aliases.clave),descripcion:findCol(headers,aliases.descripcion),gpo:findCol(headers,aliases.gpo),grupoTerapeutico:findCol(headers,aliases.grupoTerapeutico),hospitalGeneralAjuscoMedio:findCol(headers,aliases.hospitalGeneralAjuscoMedio),costo:findCol(headers,aliases.costo),precio_venta:findCol(headers,aliases.precio_venta),iva_pct:findCol(headers,aliases.iva_pct),ieps_pct:findCol(headers,aliases.ieps_pct)};
        if(candidate.clave>=0&&candidate.descripcion>=0&&candidate.gpo>=0&&candidate.grupoTerapeutico>=0&&candidate.hospitalGeneralAjuscoMedio>=0){headerRow=i;cols=candidate;break;}
      }
      if(headerRow<0||!cols)continue;
      recognizedSheet=true;
      for(let i=headerRow+1;i<matrix.length;i++){
        const row=matrix[i]||[];
        const r=normalizeRecord({numero:cols.numero>=0?row[cols.numero]:'',clave:row[cols.clave],descripcion:row[cols.descripcion],gpo:row[cols.gpo],grupoTerapeutico:row[cols.grupoTerapeutico],hospitalGeneralAjuscoMedio:row[cols.hospitalGeneralAjuscoMedio],costo:cols.costo>=0?row[cols.costo]:0,precio_venta:cols.precio_venta>=0?row[cols.precio_venta]:0,iva_pct:cols.iva_pct>=0?row[cols.iva_pct]:0,ieps_pct:cols.ieps_pct>=0?row[cols.ieps_pct]:0});
        if(r.key)out.push(r);
      }
    }
    if(!recognizedSheet)throw new Error('No se encontró el encabezado requerido: No., CLAVE, DESCRIPCIÓN, GPO, GRUPO TERAPEUTICO y HOSPITAL GENERAL AJUSCO MEDIO.');
    const unique=new Map();
    out.forEach((r,index)=>{if(!r.numero)r.numero=index+1;unique.set(r.key,r);});
    return Array.from(unique.values()).sort((a,b)=>(num(a.numero)||999999)-(num(b.numero)||999999)||a.clave.localeCompare(b.clave));
  }

  async function refreshSystem(){await renderSection();try{await window.renderDashboard?.();}catch(_e){}try{await window.renderDashboardCharts?.();}catch(_e){}try{await window.drawInventario?.();}catch(_e){}}
  function bind(){
    makeSection();
    document.getElementById('mxMiCpmSave')?.addEventListener('click',async()=>{const r=formRecord();if(!r.key)return mxAlert('La CLAVE es obligatoria.');let rows=readCatalog();if(!r.numero)r.numero=(rows.reduce((m,x)=>Math.max(m,num(x.numero)),0)||0)+1;if(editKey&&editKey!==r.key)rows=rows.filter(x=>x.key!==editKey);rows=rows.filter(x=>x.key!==r.key);rows.push(r);saveCatalog(rows);clearForm();await refreshSystem();});
    document.getElementById('mxMiCpmClear')?.addEventListener('click',clearForm);
    document.getElementById('mxMiCpmSearch')?.addEventListener('input',window.mxDebounce?window.mxDebounce(renderSection,100):renderSection);
    document.getElementById('mxMiCpmImport')?.addEventListener('click',async()=>{const file=document.getElementById('mxMiCpmFile')?.files?.[0];if(!file)return mxAlert('Selecciona el archivo de Mi Catálogo.');try{const rows=await parseImport(file);if(!rows.length)return mxAlert('No se encontraron claves válidas en el archivo.');const unique=new Map(rows.map(r=>[r.key,r]));if(!await mxConfirm(`Se cargarán ${unique.size} claves únicas y se reemplazará el listado actual de Mi Catálogo. ¿Continuar?`))return;saveCatalog(Array.from(unique.values()));document.getElementById('mxMiCpmFile').value='';clearForm();await refreshSystem();mxAlert(`Mi Catálogo cargado correctamente: ${unique.size} claves asignadas. Solo se conservaron las seis columnas autorizadas.`);}catch(e){console.error(e);mxAlert('No se pudo cargar Mi Catálogo: '+(e?.message||e));}});
    document.getElementById('mxMiCpmExport')?.addEventListener('click',exportAvailability);
    document.getElementById('mxMiCpmDeleteAll')?.addEventListener('click',async()=>{const rows=readCatalog();if(!rows.length)return mxAlert('Mi Catálogo ya está vacío.');if(!await mxConfirm(`¿Eliminar las ${rows.length} claves de Mi Catálogo? El cálculo regresará temporalmente a la base manual.`))return;localStorage.removeItem(STORAGE_KEY);clearForm();await refreshSystem();});
    document.getElementById('mxMiCpmTable')?.addEventListener('click',ev=>{const tr=ev.target.closest('tr[data-micpm-index]');if(!tr)return;const r=lastRendered[Number(tr.dataset.micpmIndex)];if(r)selectRecord(r,tr);});
    document.getElementById('mxMiCpmTable')?.addEventListener('dblclick',ev=>{const tr=ev.target.closest('tr[data-micpm-index]');if(!tr)return;const r=lastRendered[Number(tr.dataset.micpmIndex)];if(r)fillForm(r);});
    document.getElementById('mxMiCpmDeleteSelected')?.addEventListener('click',async()=>{if(!selectedKey)return;const r=readCatalog().find(x=>x.key===selectedKey);if(!r)return clearForm();if(!await mxConfirm(`¿Eliminar la clave ${r.clave} de Mi Catálogo?`))return;saveCatalog(readCatalog().filter(x=>x.key!==selectedKey));clearForm();await refreshSystem();});
    const oldBtn=document.getElementById('btnExportDispoExcel');if(oldBtn&&oldBtn.dataset.mxMiCpmBound!=='1'){const fresh=oldBtn.cloneNode(true);fresh.dataset.mxMiCpmBound='1';oldBtn.parentNode.replaceChild(fresh,oldBtn);fresh.addEventListener('click',exportAvailability);}
    renderSection();
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind,{once:true});else bind();
  window.addEventListener('load',()=>{setTimeout(()=>{renderSection();refreshAvailabilityChart();},300);},{once:true});
})();


