  function mxAnaHistoryDateLabel(ms){if(!ms)return'—';try{return new Date(ms).toLocaleString('es-MX',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});}catch(_e){return'—';}}
