    modal.querySelector('#mxAnaCjHistoryState').addEventListener('change',()=>{mxAnaCjHistoryPage=1;mxAnaRenderCollectiveHistory();});
    const daysInput=modal.querySelector('#mxAnaCjHistoryDays');daysInput.addEventListener('change',()=>{const next=mxAnaNormalizeHistoryDays(daysInput.value);daysInput.value=String(next);mxAnaCjHistoryDays=next;mxAnaCjHistoryPage=1;mxAnaRefreshCollectiveHistory(false);});daysInput.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();daysInput.blur();}});
