async function poll(){if(running){rerun=true;queueState({rerun:true});return num(window.__mxCriticalQueueStatus?.transferAdjust?.pending)}if(!document.body?.classList?.contains('logged')||navigator.onLine===false||typeof window.mxAplicarAjusteTransferenciaCentral!=='function'||!String(window.mxRemoteDbUrl?.()||'').trim())return 0;running=true;queueState({running:true,rerun:false});let processed=0,lastPending=0;try{for(let guard=0;guard<MAX_DRAIN;guard++){const next=await nextPending();if(!next)break;lastPending=num(window.__mxCriticalQueueStatus?.transferAdjust?.pending);const[id]=next,claimed=await claim(id).catch(e=>{console.warn('[MX AJUSTES COLA] No se pudo reservar',id,e);return null});if(!claimed){await new Promise(r=>setTimeout(r,20));continue}queueState({currentId:id,currentFolio:txt(claimed.originalFolio),startedAt:new Date().toISOString()});await processOne(id,claimed);processed++;queueState({processed,lastProcessedId:id,currentId:'',currentFolio:''});await new Promise(r=>setTimeout(r,20))}}catch(e){console.warn('[MX AJUSTES TRANSFERENCIA COLA]',e?.message||e);queueState({lastError:e?.message||String(e)})}finally{running=false;queueState({running:false,processed,currentId:'',rerun:false});if(rerun){rerun=false;setTimeout(()=>schedule(20),0)}}return Math.max(processed,lastPending)}
