function filterRows(){const q=txt($('vlaSearch')?.value).toLowerCase(),st=txt($('vlaStatus')?.value);return records.filter(r=>{if(st&&stateOf(r)!==st)return false;const apps=Object.values(appsOf(r)).map(a=>a.appName).join(' ');return!q||[r.fullName,r.phone,r.email,r.deviceId,r.branch,r.plan,apps].some(x=>txt(x).toLowerCase().includes(q))})}
