  for(const alias of aliases){
    const copy={...rec,deviceId:alias,deviceKey:alias,canonicalDeviceGroup:canonical,canonicalPhysicalDeviceKey:physicalKeyFor(rec),consolidatedByPhysicalDevice:aliases.length>1};
    for(const k of ['__key','__aliases','__source','__sourceBranch','consolidatedDeviceCount','_mxGenericAppNeedsCleanup'])delete copy[k];
    await fb(`${PATH}/${encodeURIComponent(branch())}/${encodeURIComponent(alias)}`,'PUT',copy);
  }
