function recomputeRecordAppPointers(rec,apps,now){const all=Object.values(apps||{}),active=all.filter(a=>appState(a)==='active'),pending=all.filter(a=>appState(a)==='pending'),latest=newestAppFromMap(apps),lastPending=pending.sort((a,b)=>appRequestTs(b)-appRequestTs(a))[0]||null;rec.applications=apps;if(latest){rec.appCode=code(latest.appCode||latest.appName);rec.appName=appLabel(rec.appCode);rec.app=rec.appName;rec.application=rec.appName}else{rec.appCode='';rec.appName='';rec.app='';rec.application=''}rec.pendingAppCode=lastPending?code(lastPending.appCode||lastPending.appName):'';rec.pendingAppName=lastPending?appLabel(rec.pendingAppCode):'';rec.active=active.length>0;rec.status=active.length?'active':pending.length?'pending':'registered';rec.manualValidationRequired=pending.length>0;rec.identityAutoLinkBlocked=pending.length>0;rec.identityAccessInherited=false;rec.updatedAt=now;return rec}
async function deleteIdentityApplication(rec,id,appCode){const c=code(appCode),devs=new Set(aliasKeysFor(rec,id).map(mxIdentityKey)),now=new Date().toISOString();let changed=false;for(const br of await allActivationBranches()){const root=await fb(`/viewer_identities/${encodeURIComponent(br)}`,'GET').catch(()=>null);if(!root||typeof root!=='object')continue;for(const[userId,identity]of Object.entries(root)){if(!identity||typeof identity!=='object')continue;const devices={...(identity.devices||{})};let touched=false;for(const[dk,d0]of Object.entries(devices)){const d=d0&&typeof d0==='object'?d0:{},dev=mxIdentityKey(d.deviceId||dk);if(!devs.has(mxIdentityKey(dk))&&!devs.has(dev))continue;const raw=d.applications&&typeof d.applications==='object'?{...d.applications}:{},clean={};let removedHere=false;for(const[k,a]of Object.entries(raw)){if(code(a?.appCode||k)===c){removedHere=true;continue}clean[k]=a}if(removedHere){touched=true;devices[dk]={...d,applications:clean,updatedAt:now,lastAccessChange:'app_delete'}}}if(!touched)continue;changed=true;const authorizedApps={};for(const d of Object.values(devices))for(const[k,a]of Object.entries(d?.applications||{})){if(!a||a.active!==true||a.manualValidationRequired===true||a.autoLinkBlocked===true)continue;const st=norm(a.status||'ACTIVE');if(/SUSPEND|REVOK|CANCEL|INACTIV|DESACTIV|DELET|ELIMIN/.test(st))continue;const ac=code(a.appCode||k),prev=authorizedApps[ac],pt=appRequestTs(prev),nt=appRequestTs(a);if(!prev||nt>=pt)authorizedApps[ac]={...a,appCode:ac,appName:appLabel(ac)}}await fb(`/viewer_identities/${encodeURIComponent(br)}/${encodeURIComponent(userId)}`,'PUT',{...identity,devices,authorizedApps,updatedAt:now,lastAccessChange:'app_delete'}).catch(()=>null)}}return changed}
async function deleteViewerApplication(rec,id,appCode){const c=code(appCode);if(!c||isGenericAppCode(c))throw new Error('No se pudo identificar el visor a eliminar.');const label=appLabel(c),ok=await(window.mxConfirm?window.mxConfirm(`¿Eliminar ${label} de este dispositivo?\n\nSe eliminará únicamente este visor. El dispositivo y los demás visores permanecerán registrados. Si el usuario vuelve a necesitarlo deberá enviar una solicitud nueva desde ese visor.`):Promise.resolve(confirm(`¿Eliminar ${label} de este dispositivo?`)));if(!ok)return false;const now=new Date().toISOString(),apps=appsOf(rec);delete apps[c];const deleted={...(rec.deletedApplications||{})};deleted[c]={appCode:c,appName:label,deletedAt:now,deletedBy:currentUser(),reason:'viewer_direct_delete'};rec.deletedApplications=deleted;recomputeRecordAppPointers(rec,apps,now);await saveRecord(id,rec);await deleteIdentityApplication(rec,id,c).catch(()=>false);recoveryCache=[];recoveryAt=0;recoveryBusy=null;await syncLocalRecords([rec]);updateNavPending();render();window.dispatchEvent(new CustomEvent('mx-viewer-activations-synced',{detail:{count:records.length,deletedApp:c,device:id,at:now}}));setStatus(`✅ ${label} eliminado de este dispositivo. No quedó como pendiente ni como “Autorizar visor”.`,'ok');return true}
