      if(!bestOrder||orderScore>bestOrder.score)bestOrder={mode:'order',sheetName,matrix,headerRow:r,map,headers,score:orderScore,hits:orderHits};
      const invRequired=['clave','descripcion','unidad','lote','caducidad'],invHits=invRequired.filter(k=>map[k]!=null).length,hasQty=map.existencia!=null||map.existencia_base!=null||map.almacen!=null||map.estantes!=null||map.cantidad!=null,inventoryNamed=norm(sheetName)==='inventario',invScore=invHits+(hasQty?2:0)+(map.codigo_barras!=null?.15:0)+(inventoryNamed?4:0);
