function parseDateYmd(value){if(value instanceof Date&&!isNaN(value))return`${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,'0')}-${String(value.getDate()).padStart(2,'0')}`;if(typeof value==='number'&&Number.isFinite(value)){try{const d=XLSX.SSF.parse_date_code(value);if(d?.y)return`${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`;}catch(_e){}}const s=txt(value);if(!s)return'';let m=s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);if(m)return`${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;m=s.match(/^(\d{1,2})[\-/.](\d{1,2})[\-/.](\d{2,4})/);if(m){let y=m[3];if(y.length===2)y=(Number(y)>=70?'19':'20')+y;return`${y}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;}const d=new Date(s);return isNaN(d)?'':`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
