function validateRow(r){const errors=[];if(!txt(r.fechaYmd))errors.push('Fecha');if(!txt(r.clave))errors.push('Clave');if(!txt(r.descripcion))errors.push('Descripción');if(!txt(r.unidad))errors.push('Presentación');if(!txt(r.lote))errors.push('Lote');if(!txt(r.cadYmd))errors.push('Caducidad');if(!(num(r.pzs)>0))errors.push('Piezas');return errors;}
