function updateFromInput(e){const el=e.target,id=el.dataset.id,field=el.dataset.field;if(!id||!field)return;const row=cart.find(r=>r.id===id);if(!row)return;if(field==='selected')row.selected=el.checked;else if(field==='pzs')row[field]=Math.max(0,Math.round(num(el.value)));else if(['costo','precio_venta','iva_pct','ieps_pct'].includes(field))row[field]=Math.max(0,financeNum(el.value));else row[field]=el.value;if(field==='folio')row.folioUsesDefault=!txt(el.value);if(field==='descripcion'&&!row.unidad)row.unidad=extractPresentation(row.descripcion,'');row.duplicateSaved=existingSigs.has(signature(row));updateRowStatus(id);updateSummary();}
function updateRowStatus(id){const row=cart.find(r=>r.id===id),tr=document.querySelector(`#mxEiBody tr[data-id="${CSS.escape(id)}"]`);if(!row||!tr)return;const errors=validateRow(row),status=tr.querySelector('.mx-ei-status');tr.classList.toggle('invalid',errors.length>0);tr.classList.toggle('duplicate',!errors.length&&row.duplicateSaved);if(status){status.className='mx-ei-status '+(errors.length?'bad':row.duplicateSaved?'warn':'ok');status.textContent=errors.length?'Falta: '+errors.join(', '):row.duplicateSaved?'Ya existe; no seleccionado':'Listo';}}
