  const best=findBestSheet(wb);
  if(!best)throw new Error('No se encontró una hoja compatible.');
  if(best.mode==='order'&&best.hits<6)throw new Error('No se reconocieron los encabezados del pedido. Se requieren Fecha entrega, Clave, Descripción, cantidad entregada, Lote y F_CAD. El folio ahora es opcional.');
  if(best.mode==='inventory'&&!(best.hits>=5&&best.hasQty))throw new Error('No se reconoció una plantilla de inventario. Se requieren CLAVE, DESCRIPCION, UNIDAD, LOTE, CADUCIDAD y una existencia (EXISTENCIA, EXISTENCIA_BASE o ALMACEN/ESTANTES).');
