window.mxServiceOrderApplyLinkedSalida=function mxServiceOrderApplyLinkedSalida(savedRow={}){
  const id=mxLinkedOrderIdFromSalida(savedRow);if(!id)return Promise.resolve({ok:false,skipped:'sin_pedido'});
  const previous=mxLinkedSalidaOrderQueue.get(id)||Promise.resolve();
  const job=previous.catch(()=>{}).then(()=>mxApplyLinkedSalidaNow(savedRow));
  mxLinkedSalidaOrderQueue.set(id,job);
  return job.finally(()=>{if(mxLinkedSalidaOrderQueue.get(id)===job)mxLinkedSalidaOrderQueue.delete(id)});
};
async function mxFindCompletedLocalOrder(opBase){
  try{
    if(window.electronSql?.isElectron)return await window.electronSql.indexGet('pedidos','_mx_op_id',opBase,false);
    const list=await idbAll('pedidos').catch(()=>[]);return(list||[]).find(r=>txt(r.op_id||r._mxOpId)===opBase)||null;
  }catch(_e){return null}
}
