function mxOrderPdfSafeText(v){
  return txt(v)
    .replace(/&(?:rarr|#8594);/gi,' -> ')
    .replace(/[→⇒⟶⟹]/g,' -> ')
    .replace(/[–—−]/g,'-')
    .replace(/[“”]/g,'"')
    .replace(/[‘’]/g,"'")
    .replace(/\u00A0/g,' ')
    .replace(/[\u200B-\u200F\u202A-\u202E\u2060\uFEFF]/g,'')
    .replace(/[^\x20-\x7E\u00A0-\u00FF]/g,' ')
    .replace(/\s+/g,' ')
    .trim();
}
