function mxOrderPdfBlankCollectiveGrid(doc,startY,endY,startNumber=1){
  const pageW=doc.internal.pageSize.getWidth(),left=8,right=pageW-8,rowH=8.0;
  let y=Math.max(0,num(startY)),limit=Math.max(y,num(endY));
  const fixed=[7.5,24,76,44,22,22,44],fixedTotal=fixed.reduce((a,b)=>a+b,0),last=Math.max(18,(right-left)-fixedTotal),widths=[...fixed,last];
  const rows=Math.max(0,Math.floor((limit-y)/rowH));
  if(!rows)return{rows:0,finalY:y};
  const xs=[left];for(const width of widths)xs.push(xs[xs.length-1]+width);
  doc.setDrawColor(0,0,0);doc.setLineWidth(.23);doc.setFont('helvetica','normal');doc.setFontSize(5.7);doc.setTextColor(0,0,0);
  for(let i=0;i<rows;i++){
    const top=y+i*rowH,bottom=top+rowH;
    mxOrderPdfLine(doc,left,top,right,top,.23);mxOrderPdfLine(doc,left,bottom,right,bottom,.23);
    for(const x of xs)mxOrderPdfLine(doc,x,top,x,bottom,.23);
    const n=Math.max(1,Math.floor(num(startNumber)))+i;doc.text(String(n),left+widths[0]/2,top+rowH/2+1.8,{align:'center'});
  }
  return{rows,finalY:y+rows*rowH}
}
