const MX_ORDER_PDF_RECORD_CACHE=new Map();
async function mxOrderPdfRefreshMedicalApproval(r={},force=false){
  const id=txt(r?.id||r?.firebase_id||r?.__key);if(!id)return r;
  try{
    const cached=MX_ORDER_PDF_RECORD_CACHE.get(id),now=Date.now();
    let fresh=!force&&cached&&now-cached.at<4000?cached.value:null;
    if(!fresh){
      const request=Promise.resolve(mxGetJson(`${ROOT}/${encodeURIComponent(branch())}/${encodeURIComponent(id)}`))
        .then(value=>{if(value){MX_ORDER_PDF_RECORD_CACHE.set(id,{at:Date.now(),value});}return value})
        .catch(()=>null);
      // La descarga no queda detenida indefinidamente por una conexión lenta.
      fresh=await Promise.race([request,new Promise(resolve=>setTimeout(()=>resolve(null),2400))]);
    }
    if(!fresh)return r;
    const merged={...r,medico:txt(fresh.medico)||r.medico,cedula:txt(fresh.cedula)||r.cedula,medicoId:txt(fresh.medicoId)||r.medicoId,validacionMedica:fresh.validacionMedica||r.validacionMedica,validacionMedicaEstado:txt(fresh.validacionMedicaEstado)||r.validacionMedicaEstado,medicoAprobado:fresh.medicoAprobado===true||r.medicoAprobado===true,medicoAprobacionNombre:txt(fresh.medicoAprobacionNombre)||r.medicoAprobacionNombre,medicoAprobacionCedula:txt(fresh.medicoAprobacionCedula)||r.medicoAprobacionCedula,medicoAprobacionFecha:txt(fresh.medicoAprobacionFecha)||r.medicoAprobacionFecha,validacionFarmacovigilancia:fresh.validacionFarmacovigilancia||r.validacionFarmacovigilancia,validacionFarmacovigilanciaEstado:txt(fresh.validacionFarmacovigilanciaEstado)||r.validacionFarmacovigilanciaEstado,farmacovigilanciaValidado:fresh.farmacovigilanciaValidado===true||r.farmacovigilanciaValidado===true,farmacovigilanciaValidadoPor:txt(fresh.farmacovigilanciaValidadoPor)||r.farmacovigilanciaValidadoPor,farmacovigilanciaValidadoAt:txt(fresh.farmacovigilanciaValidadoAt)||r.farmacovigilanciaValidadoAt,notaFarmacovigilancia:txt(fresh.notaFarmacovigilancia||fresh.observacionFarmacovigilancia||fresh.validacionFarmacovigilancia?.nota)||r.notaFarmacovigilancia,observacionFarmacovigilancia:txt(fresh.observacionFarmacovigilancia||fresh.notaFarmacovigilancia||fresh.validacionFarmacovigilancia?.nota)||r.observacionFarmacovigilancia,cierreFarmacovigilancia:fresh.cierreFarmacovigilancia===true||r.cierreFarmacovigilancia===true,cierreFarmacovigilanciaEstado:txt(fresh.cierreFarmacovigilanciaEstado)||r.cierreFarmacovigilanciaEstado,estadoFarmacovigilancia:txt(fresh.estadoFarmacovigilancia)||r.estadoFarmacovigilancia,farmacovigilanciaFinalizado:fresh.farmacovigilanciaFinalizado===true||r.farmacovigilanciaFinalizado===true,farmacovigilanciaCerradoAt:txt(fresh.farmacovigilanciaCerradoAt)||r.farmacovigilanciaCerradoAt,farmacovigilanciaCerradoPor:txt(fresh.farmacovigilanciaCerradoPor)||r.farmacovigilanciaCerradoPor,cierreServicio:fresh.cierreServicio===true||r.cierreServicio===true,cierreServicioEstado:txt(fresh.cierreServicioEstado)||r.cierreServicioEstado,estadoCierreServicio:txt(fresh.estadoCierreServicio)||r.estadoCierreServicio,estadoTratamiento:txt(fresh.estadoTratamiento)||r.estadoTratamiento,tratamientoActivo:fresh.tratamientoActivo===false?false:r.tratamientoActivo,servicioCierreNombre:txt(fresh.servicioCierreNombre)||r.servicioCierreNombre,servicioCerradoPor:txt(fresh.servicioCerradoPor||fresh.cierreServicioPor)||r.servicioCerradoPor,servicioCerradoAt:txt(fresh.servicioCerradoAt||fresh.cierreServicioAt)||r.servicioCerradoAt,cierreServicioPor:txt(fresh.cierreServicioPor)||r.cierreServicioPor,cierreServicioAt:txt(fresh.cierreServicioAt)||r.cierreServicioAt,observacionPdfServicio:txt(fresh.observacionPdfServicio)||r.observacionPdfServicio,notaJustificado:txt(fresh.notaJustificado||fresh.notaUsuario)||r.notaJustificado,notaUsuario:txt(fresh.notaUsuario||fresh.notaJustificado)||r.notaUsuario,updatedAt:txt(fresh.updatedAt)||r.updatedAt};
    if(merged._id){try{await idbPut('pedidos',merged)}catch(_e){}}
    return merged;
  }catch(_e){return r}
}

async function mxOrderPdfHydrateRequesterHistory(r={}){
  try{
    if(!norm(r?.tipo||r?.tipo_doc).includes('JUSTIFICADO')||!txt(r?.paciente))return r;
    const items=Array.isArray(r?.items)&&r.items.length?r.items:(Array.isArray(r?.approvedItems)?r.approvedItems:[]),keys=new Set(items.map(it=>norm(it?.clave)).filter(Boolean));
    if(!keys.size)return r;
    const patient=norm(r.paciente),exp=norm(r.expediente),all=await idbAll('salidas').catch(()=>[]),local=[];
    const parseRemaining=v=>{const m=txt(v).match(/FALTAN\s+(\d+(?:[.,]\d+)?)\s+PZS?/i);return m?num(String(m[1]).replace(',','.')):0};
    for(const x of all||[]){
      if(!x||!norm(x.tipo_doc).includes('COLECTIVO JUSTIFICADO'))continue;
      if(norm(x.paciente)!==patient)continue;
      if(exp&&norm(x.expediente)&&norm(x.expediente)!==exp)continue;
      if(!keys.has(norm(x.clave)))continue;
      const nurse=txt(x.enfermera_responsable_colectivo||x.enfermera_que_solicita||x.usuario_solicita||x.solicitante||x.quien_solicita);
      local.push({...x,fechaIso:txt(x.fechaIso||x.createdAt||x.fecha),cantidadRecibida:num(x.pzs||x.cantidad),cantidadRestante:num(x.cantidadRestante)||parseRemaining(x.observaciones),enfermeraResponsableColectivo:nurse,usuarioSolicita:nurse,solicitante:nurse,surteFarmacia:txt(x.surteFarmacia||x.usuario_farmacia||x.usuario_salida||x.usuario),folio:txt(x.folio)});
    }
    const prior=Array.isArray(r.historialPacienteMedicamento)?r.historialPacienteMedicamento:[],merged=[],seen=new Set();
    for(const x of [...prior,...local]){
      if(!x||typeof x!=='object')continue;
      const nurse=txt(x.enfermeraResponsableColectivo||x.usuarioSolicita||x.solicitante||x.quienSolicita||x.enfermera_que_solicita),k=txt(x._mxOpId||x.op_id||x.id)||[txt(x.fechaIso||x.fechaTexto||x.fecha),txt(x.folio),norm(x.clave),txt(x.lote),num(x.cantidadRecibida||x.pzs),norm(nurse)].join('|');
      if(seen.has(k))continue;seen.add(k);merged.push({...x,enfermeraResponsableColectivo:nurse,usuarioSolicita:nurse,solicitante:nurse});
    }
    merged.sort((a,b)=>(Date.parse(a.fechaIso||a.createdAt||a.fecha||0)||0)-(Date.parse(b.fechaIso||b.createdAt||b.fecha||0)||0));
    const latest=merged.slice().reverse().find(x=>txt(x.enfermeraResponsableColectivo||x.usuarioSolicita||x.solicitante));
    const latestNurse=latest?txt(latest.enfermeraResponsableColectivo||latest.usuarioSolicita||latest.solicitante):'';
    return{...r,historialPacienteMedicamento:merged,enfermeraResponsableColectivo:latestNurse||r.enfermeraResponsableColectivo,usuarioSolicita:latestNurse||r.usuarioSolicita,solicitante:latestNurse||r.solicitante,quienSolicita:latestNurse||r.quienSolicita};
  }catch(e){console.warn('[PDF][SOLICITANTES] No se pudo completar historial',e);return r}
}

function mxOrderPdfOrdinaryObservation(item={}){return [txt(item?.observacion),txt(item?.observaciones)].filter(Boolean).join(' | ').split('|').map(v=>txt(v)).filter(Boolean).filter(v=>!/^LOTE\s+SELECCIONADO\s*:/i.test(v)&&!/^CADUCIDAD\s*:/i.test(v)).filter((v,i,a)=>a.indexOf(v)===i).join(' | ')}
function mxOrderPdfValeObservation(item={}){return mxOrderPdfOrdinaryObservation(item).split('|').map(v=>txt(v)).filter(Boolean).filter(v=>!/^PEDIDO\s+DE\s+HOSPITAL\s+SOLICITADO\s+POR\b/i.test(v)&&!/^PRODUCTOS\s+PR[ÓO]XIMOS\s+A\s+CADUCAR\b/i.test(v)).join(' | ')}
