    root.innerHTML=`<div role="dialog" aria-modal="true" style="width:min(620px,96vw);background:#fff;border-radius:18px;box-shadow:0 24px 70px rgba(15,23,42,.28);padding:22px;color:#0f172a"><h3 style="margin:0 0 8px;font-size:19px">🧪 Baja de caducados</h3><p style="margin:0 0 16px;color:#475569;line-height:1.45">Selecciona hasta qué fecha quieres retirar existencias. Ambos procesos generan Salidas y el PDF <b>Colectivo caducados</b>.</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px"><button type="button" data-mode="today" class="btn" style="min-height:84px;text-align:left;padding:14px"><b>📅 Fecha actual hacia atrás</b><br><small>Da de baja todo lo que ya caducó hasta hoy, incluyendo meses anteriores.</small></button><button type="button" data-mode="month" class="btn danger" style="min-height:84px;text-align:left;padding:14px"><b>🗓️ Mes en curso</b><br><small>Da de baja todo lo vencido y también lo que caduque hasta el último día del mes actual.</small></button></div><div style="display:flex;justify-content:flex-end;margin-top:14px"><button type="button" data-cancel class="btn">Cancelar</button></div></div>`;
    const finish=value=>{document.removeEventListener('keydown',onKey,true);root.remove();resolve(value)};
    const onKey=e=>{if(e.key==='Escape'){e.preventDefault();finish(null)}};
    root.addEventListener('click',e=>{const b=e.target.closest('[data-mode]');if(b)return finish(b.dataset.mode);if(e.target===root||e.target.closest('[data-cancel]'))finish(null)});
