function mxFulLocalDateYmd(value=new Date()){const d=value instanceof Date?value:new Date(value);if(Number.isNaN(d.getTime()))return'';return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function mxFulCompactObservation(...values){const out=[];for(const value of values){for(const raw of txt(value).split(/\s*\|\s*|\r?\n+/g)){const item=txt(raw).replace(/\s+/g,' ');if(!item||/^LOTE\s+SELECCIONADO\s*:/i.test(item)||/^CADUCIDAD\s*:?\s*\d/i.test(item))continue;const key=norm(item).replace(/[.;]+$/g,'');if(!key||out.some(x=>x.key===key))continue;out.push({key,text:item})}}return out.map(x=>x.text).join(' | ')}
