function mxFulShortService(v){const s=txt(v).replace(/\s+/g,' ');return s.length>25?s.slice(0,24)+'…':s}
function mxFulJustifiedOperationalObservation(r={}){const current=txt(r?.servicioSolicitanteActual||r?.movimientoServicio?.a||r?.servicio),previous=txt(r?.servicioAnteriorPaciente||r?.movimientoServicio?.de||r?.servicioFolioOrigen),parts=[];if(r?.cambioServicio===true||(previous&&current&&norm(previous)!==norm(current))){parts.push(previous&&current?`SERV.: ${mxFulShortService(previous)} → ${mxFulShortService(current)}`:(current?`SERV.: ${mxFulShortService(current)}`:'CAMBIO DE SERVICIO'))}if(mxFulFvClosed(r))parts.push('CERRADO');return mxFulCompactObservation(parts.join(' | '))}
function mxFulOrdinaryObservation(base,requester,supplier){const kept=mxFulCompactObservation(base).split(/\s*\|\s*/g).filter(Boolean).filter(x=>!/^SOLICITA\s*:/i.test(x)&&!/^SURTE\s*:/i.test(x));const req=txt(requester),sup=txt(supplier);const id=[req?`Solicita: ${req}`:'',sup?`Surte: ${sup}`:''].filter(Boolean).join(' · ');if(id)kept.push(id);return mxFulCompactObservation(kept.join(' | '))}
const branch = () => txt(window.mxGetSucursalFromLicense?.() || 'HGAM').toUpperCase() || 'HGAM';
