    item?.cantidadSolicitadaAhora ?? item?.cantidadPorRecibir ??
    item?.cantidadRecibidaSolicitada ?? item?.cantidad24Horas ??
    item?.cantidadSolicitada ?? item?.pzs ?? item?.cantidad
