function mxFulHospitalName(r={}){return txt(r?.hospitalSolicitanteNombre||r?.hospitalNombre||r?.hospital||'')}
function mxFulHospitalInitials(r={}){return norm(r?.hospitalSolicitanteIniciales||r?.hospitalIniciales||r?.servicioIniciales||r?.inicialesServicio||r?.servicio).replace(/[^A-Z0-9]/g,'').slice(0,12)}
function mxFulRequester(r={}){return txt(r?.jefeDepartamento||r?.jefeDepartamentoNombre||r?.usuarioSolicita||r?.solicitante||r?.quienSolicita||r?.enfermeraResponsableColectivo)}
function mxFulValeObservation(...values){return mxFulCompactObservation(...values).split(/\s*\|\s*/g).filter(Boolean).filter(x=>!/^SOLICITA\s*:/i.test(x)&&!/^SURTE\s*:/i.test(x)).join(' | ')}

function parts(row){
  const hasParts = row && [
    'almacen','alm','pzs_almacen','pzsalmacen',
    'estantes','est','pzs_estantes','pzsestantes'
  ].some((key) => Object.prototype.hasOwnProperty.call(row, key));
  const legacy = num(row?.existencia ?? row?.existencias ?? row?.stock);
  return {
    has: hasParts,
    almacen: hasParts ? num(row?.almacen ?? row?.alm ?? row?.pzs_almacen ?? row?.pzsalmacen) : legacy,
    estantes: hasParts ? num(row?.estantes ?? row?.est ?? row?.pzs_estantes ?? row?.pzsestantes) : 0
  };
}

function available(row){
  const p = parts(row);
  return window.mxWarehouseModeEnabled?.() ? p.estantes : (p.almacen + p.estantes);
}

function cadTime(value){
  const raw = txt(value);
  let date = null;
  if(/^\d{4}-\d{2}/.test(raw)) date = new Date(raw + '-01T12:00:00');
  else if(/^\d{2}\/\d{2}\/\d{4}$/.test(raw)){
    const [day, month, year] = raw.split('/');
    date = new Date(+year, +month - 1, +day, 12);
  }else date = new Date(raw);
  return date && !Number.isNaN(date.getTime()) ? date.getTime() : Number.MAX_SAFE_INTEGER;
}

function allocate(inventory,item,quantity,preference={}){let remaining=quantity;const allocations=[],preferredId=txt(preference?.inventoryId??preference?.selectedInventoryId),preferredLot=norm(preference?.lote??preference?.selectedLot),preferredCad=norm(preference?.caducidad??preference?.selectedCaducidad),hasPreference=Boolean(preferredId||preferredLot||preferredCad);let lots=(inventory||[]).filter(row=>norm(row?.clave)===norm(item.clave)&&available(row)>0);if(hasPreference){lots=lots.filter(row=>{if(preferredId)return txt(row?._id)===preferredId;if(preferredLot&&norm(row?.lote)!==preferredLot)return false;if(preferredCad&&norm(row?.caducidad)!==preferredCad)return false;return true})}lots.sort((a,b)=>cadTime(a?.caducidad)-cadTime(b?.caducidad)||num(a?._id)-num(b?._id));for(const row of lots){if(remaining<=0)break;const p=parts(row),take=Math.min(remaining,available(row)),next={...row};let almacen=p.almacen,estantes=p.estantes;if(window.mxWarehouseModeEnabled?.())estantes-=take;else{const fromEstantes=Math.min(estantes,take);estantes-=fromEstantes;almacen-=(take-fromEstantes)}next.almacen=Math.max(0,almacen);next.estantes=Math.max(0,estantes);next.pzs_almacen=next.almacen;next.pzs_estantes=next.estantes;next.existencia=next.almacen+next.estantes;allocations.push({before:row,next,take,selected:hasPreference});remaining-=take}return{allocations,missing:remaining,selected:hasPreference,matchedLots:lots.length}}

async function durable(operations){
  if(window.electronSql?.isElectron && typeof window.electronSql.transactionDurable === 'function'){
    return window.electronSql.transactionDurable(operations);
  }
  for(const op of operations){
    if(op.type === 'put') await window.idbPut(op.store, op.value);
    else if(op.type === 'delete') await window.idbDelete(op.store, op.key);
  }
  return true;
}

function hasAntibioticMarker(value){
  const marker = norm(value).replace(/[._-]+/g, ' ');
  return /(^|[\s/|,;])ANTIBIOTIC[OA]S?($|[\s/|,;])/.test(marker);
}

function firstValue(row, keys){
  for(const key of keys){
    const value = row?.[key];
    if(value != null && txt(value)) return value;
  }
  return '';
}

function isAntibioticProduct(inventoryRow, orderItem){
  const rows = [inventoryRow, orderItem].filter(Boolean);
  for(const row of rows){
    if(row.antibiotico === true || row.isAntibiotico === true || row.ANTIBIOTICO === true) return true;
    const values = [
      firstValue(row, ['departamento','departamento_clasificacion','departamentoClasificacion','DEPARTAMENTO']),
      firstValue(row, ['clasificacion','clasificación','CLASIFICACION','CLASIFICACIÓN']),
      firstValue(row, ['restriccion','restricción','RESTRICCION','RESTRICCIÓN'])
    ];
    if(values.some(hasAntibioticMarker)) return true;
  }

  try{
    if(typeof window.mxSalidasEsAntibioticoRow === 'function' && window.mxSalidasEsAntibioticoRow(inventoryRow)){
      return true;
    }
  }catch(_error){}

  try{
    if(typeof window.mxFindClasifCatalog === 'function'){
      const catalog = window.mxFindClasifCatalog(inventoryRow?.clave || orderItem?.clave);
      if(catalog && hasAntibioticMarker(catalog.clasificacion || catalog.clasif || catalog.tipo)) return true;
    }
  }catch(_error){}

  return false;
}

