    if(dup){const p=parts(dup);throw new Error(`Ya existe la clave ${clave} con lote ${lote} en Inventario (Almacén ${p.almacen}, Estantes ${p.estantes}). Usa el registro existente para evitar duplicados.`)}
    if(typeof window.mxAplicarConteoInventarioCentral!=='function')throw new Error('Motor central de ajustes de inventario no disponible.');
    const result=await window.mxAplicarConteoInventarioCentral({requestId:id,reason:'Alta de producto desde Visor Transferencias',user:by,inventoryMode:'alta_visor_transferencias',items:[{createNew:true,isNew:true,nuevoProducto:true,clave,descripcion:nombre,unidad:presentacion,lote,caducidad,ubicacion,almacenNuevo,estantesNuevo}]});
