function qCadNum(v){
  const s=qTxt(v);let m=s.match(/^(\d{4})-(\d{2})-(\d{2})$/);if(m)return new Date(+m[1],+m[2]-1,+m[3]).getTime();
  m=s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})$/);if(m)return new Date(+m[3],+m[2]-1,+m[1]).getTime();
  return Number.POSITIVE_INFINITY;
}
async function qInventory(force=false){
  const now=Date.now();
  if(!force && invCacheV148.length && now-invCacheAtV148<60000) return invCacheV148.slice();
  let rows=[];
  // V148: nunca fuerces una recarga pesada durante el arranque o una búsqueda.
  // Primero reutiliza la fotografía que el Sistema Principal ya mantiene en memoria.
  try{ if(typeof cacheInv!=='undefined' && Array.isArray(cacheInv) && cacheInv.length) rows=cacheInv.slice(); }catch(_e){}
  if(force){
    try{ if(typeof window.__mxLoadInventory==='function') rows=await window.__mxLoadInventory({force:true,requireRows:true});
      else if(typeof refreshCacheInv==='function') rows=await refreshCacheInv(); }catch(_e){}
  }else if(!rows.length){
    try{ rows=await idbAll('inventory'); }catch(_e){ rows=[]; }
    if(!rows.length){
      try{ if(typeof window.__mxLoadInventory==='function') rows=await window.__mxLoadInventory({force:false,requireRows:false}); }catch(_e){}
    }
  }
  invCacheV148=Array.isArray(rows)?rows:[];invCacheAtV148=Date.now();
  return invCacheV148.slice();
}
function qProdKey(r={}){ return qNorm(r.clave||r.codigo_barras||r.codigoBarras||r.barcode||r.descripcion||r.nombre); }
function qSameProduct(a,b){
  const ac=qNorm(a?.clave),bc=qNorm(b?.clave); if(ac&&bc) return ac===bc;
  const ab=qNorm(a?.codigo_barras||a?.codigoBarras||a?.barcode),bb=qNorm(b?.codigo_barras||b?.codigoBarras||b?.barcode); if(ab&&bb)return ab===bb;
  return qProdKey(a)===qProdKey(b);
}
async function qInventoryCatalog(force=false){
  const now=Date.now();
  if(!force && invCatalogV148.length && now-invCatalogAtV148<60000) return invCatalogV148;
  const inv=await qInventory(force),map=new Map();
  for(const r of inv){
    const key=qProdKey(r);if(!key)continue;
    const qty=Math.max(0,qPickExis(r));
    const prev=map.get(key)||{clave:qTxt(r.clave),codigo_barras:qTxt(r.codigo_barras||r.codigoBarras||r.barcode),descripcion:qTxt(r.descripcion||r.nombre),unidad:qTxt(r.unidad),disponible:0,lotes:0,__finQty:0,__costValue:0,__saleValue:0,__costFallback:0,__saleFallback:0};
    prev.disponible+=qty;prev.lotes++;
    if(!prev.clave)prev.clave=qTxt(r.clave);if(!prev.codigo_barras)prev.codigo_barras=qTxt(r.codigo_barras||r.codigoBarras||r.barcode);if(!prev.descripcion)prev.descripcion=qTxt(r.descripcion||r.nombre);if(!prev.unidad)prev.unidad=qTxt(r.unidad);
    const f=qFinanceOf(r),cu=Math.max(0,qNum(f?.costo ?? f?.costo_final)),pv=Math.max(0,qNum(f?.precio_venta));
    if(cu>0||pv>0){
      if(!prev.__costFallback&&cu>0)prev.__costFallback=cu;if(!prev.__saleFallback&&pv>0)prev.__saleFallback=pv;
      if(qty>0){prev.__finQty+=qty;prev.__costValue+=qty*cu;prev.__saleValue+=qty*pv;}
    }
    map.set(key,prev);
  }
  invCatalogV148=[...map.values()].map(r=>{
    const den=r.__finQty>0?r.__finQty:0;
    const out={...r,costo_unitario:den>0?r.__costValue/den:r.__costFallback,precio_venta:den>0?r.__saleValue/den:r.__saleFallback};
    delete out.__finQty;delete out.__costValue;delete out.__saleValue;delete out.__costFallback;delete out.__saleFallback;
    return out;
  }).sort((a,b)=>qTxt(a.descripcion).localeCompare(qTxt(b.descripcion),'es',{sensitivity:'base'}));
  invCatalogAtV148=Date.now();
  return invCatalogV148;
}
