function closeServiceModal(){if(serviceBusy)return;$q('mxQxServiceModal')?.classList.add('hidden');renderDoctorDrop([]);}
async function hydrateExactDoctor(){
  const nombre=qTxt($q('mxQxSrvMedName')?.value),ced=qTxt($q('mxQxSrvMedCed')?.value);if(!nombre&&!ced)return;const all=await loadDoctors();const m=all.find(x=>ced&&qNorm(x.cedula)===qNorm(ced))||all.find(x=>qNorm(x.nombre)===qNorm(nombre));if(!m)return;if(!$q('mxQxSrvMedTel').value)$q('mxQxSrvMedTel').value=qTxt(m.telefono);if(!$q('mxQxSrvMedDom').value)$q('mxQxSrvMedDom').value=qTxt(m.domicilio);if(!$q('mxQxSrvMedCed').value)$q('mxQxSrvMedCed').value=qTxt(m.cedula);serviceState.doctorId=m._id||null;
}
async function ensureServiceDoctorLinked(medico){
  if(!medico?.nombre)return null;
  const all=await loadDoctors(true),existing=all.find(m=>String(m._id)===String(serviceState.doctorId||''))||all.find(m=>medico.cedula&&qNorm(m.cedula)===qNorm(medico.cedula))||all.find(m=>!medico.cedula&&qNorm(m.nombre)===qNorm(medico.nombre));
  const row={nombre:medico.nombre,cedula:medico.cedula||qTxt(existing?.cedula),telefono:medico.telefono||qTxt(existing?.telefono),domicilio:medico.domicilio||qTxt(existing?.domicilio),institucion:qTxt(existing?.institucion)};if(existing?._id)row._id=existing._id;
  try{const id=await idbPut('medicos',row);serviceState.doctorId=row._id||id;doctorCacheAt=0;try{await drawMedicos?.();}catch(_e){}return serviceState.doctorId;}catch(_e){return null;}
}
async function planServiceAllocations(items){
  const inv=await qInventory(true),alloc=[],short=[];
  for(const item of items){
    const lots=inv.filter(r=>qSameProduct(r,item)&&qPickExis(r)>0).sort((a,b)=>{const d=qCadNum(a.caducidad||a.cad)-qCadNum(b.caducidad||b.cad);if(d!==0)return d;return qPickExis(b)-qPickExis(a);});
    const total=lots.reduce((s,r)=>s+Math.max(0,qPickExis(r)),0),needed=qInt(item.cantidad);if(total<needed){short.push(`${item.clave||item.descripcion}: requiere ${needed}, disponible ${total}`);continue;}
    let rem=needed;for(const r of lots){if(rem<=0)break;const avail=Math.max(0,qInt(qPickExis(r))),take=Math.min(rem,avail);if(take>0){alloc.push({item,match:r,qty:take,exIni:avail});rem-=take;}}
  }
  if(short.length)throw new Error('Existencia insuficiente:\n'+short.join('\n'));
  return alloc;
}
function aggregatePdfItems(items,alloc){return items.map(it=>{const a=alloc.filter(x=>qSameProduct(x.item,it)),lots=[...new Set(a.map(x=>`${qTxt(x.match?.lote)||'S/L'} / ${qTxt(x.match?.caducidad||x.match?.cad)||'S/C'}`))];return{...it,lotes:lots.join(', ')};});}
