function qDateYmd(value){
  const s=qTxt(value);let m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return `${m[1]}-${m[2]}-${m[3]}`;m=s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);if(m)return `${m[3]}-${String(m[2]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`;try{const d=typeof parseFechaFlexible==='function'?parseFechaFlexible(s):new Date(s);if(d&&Number.isFinite(d.getTime()))return qLocalYmd(d);}catch(_e){}return qLocalYmd();
}
function qDateDisplay(ymd){const m=qTxt(ymd).match(/^(\d{4})-(\d{2})-(\d{2})$/);return m?`${m[3]}/${m[2]}/${m[1]}`:qTxt(ymd);}
