  const state=qNorm(group?.estado);if(group?.prestamoActivo||state==='prestado')return '<span class="mx-qx-status-chip warn">💼 Préstamo activo</span>';if(state==='recuperado')return '<span class="mx-qx-status-chip info">↩️ Recuperado</span>';return '<span class="mx-qx-status-chip ok">✅ Completa</span>';
