function renderServiceHistory(){
  const body=$q('mxQxHistBody');if(!body)return;
  const term=qNorm($q('mxQxHistSearch')?.value),from=qTxt($q('mxQxHistFrom')?.value),to=qTxt($q('mxQxHistTo')?.value);
  const rows=serviceHistoryGroups.filter(g=>{
    const date=qDateYmd(g.fecha||g.stamp);
    if(from&&date<from)return false;
    if(to&&date>to)return false;
    return !term||qNorm([g.folio,g.destino?.nombre,g.destino?.iniciales,g.medico?.nombre,g.medico?.cedula,g.paciente?.nombre,(g.kits||[]).join(' '),g.estado,g.eanPrestamo].join(' ')).includes(term);
  });
  $q('mxQxHistCount').textContent=`${rows.length} servicio${rows.length===1?'':'s'}`;
  body.innerHTML=rows.length?rows.slice(0,150).map(g=>{const buttons=[`<button class="btn" type="button" data-qx-hist-edit="${qEsc(g.folio)}">✏️ Editar</button>`];if(g.eanPrestamo)buttons.push(`<button class="btn" type="button" data-qx-hist-label="${qEsc(g.folio)}">🏷️ Etiqueta</button>`);if(g.prestamoActivo){buttons.push(`<button class="btn" type="button" data-qx-hist-adjust="${qEsc(g.folio)}">↩️ Ajustar préstamo</button>`);buttons.push(`<button class="btn ok" type="button" data-qx-hist-finalize="${qEsc(g.folio)}">✅ Finalizar</button>`);}else if(g.total>0){buttons.push(`<button class="btn ok" type="button" data-qx-hist-pdf="${qEsc(g.folio)}">📄 Generar PDF</button>`);}return `<tr><td><b>${qEsc(qDateDisplay(g.fecha))}</b></td><td><b>${qEsc(g.folio)}</b>${g.eanPrestamo?`<span class="mx-qx-ean-badge mx-qx-ean-text">${qEsc(g.eanPrestamo)}</span>`:''}</td><td>${qEsc(g.destino?.nombre||'—')}<small style="display:block;color:#64748b">${qEsc(g.destino?.iniciales||'')}</small></td><td>${qEsc(g.medico?.nombre||'—')}<small style="display:block;color:#64748b">Cédula: ${qEsc(g.medico?.cedula||'—')}</small></td><td>${qEsc(g.paciente?.nombre||'—')}<small style="display:block;color:#64748b">${qEsc(g.paciente?.edad?g.paciente.edad+' años':'')} ${qEsc(g.paciente?.sexo||'')}</small></td><td><b>${g.items.length} producto${g.items.length===1?'':'s'} · ${g.total} pzs</b><small style="display:block;color:#64748b">${qEsc((g.kits||[]).join(', ')||'Sin kit')}</small>${serviceHistoryStatusHtml(g)}</td><td><div class="mx-qx-history-actions">${buttons.join('')}</div></td></tr>`;}).join(''):'<tr><td colspan="7" class="mx-qx-history-empty">No hay servicios quirúrgicos con este filtro.</td></tr>';
  body.querySelectorAll('[data-qx-hist-edit]').forEach(b=>b.onclick=()=>openServiceHistoryEdit(b.dataset.qxHistEdit));
  body.querySelectorAll('[data-qx-hist-pdf]').forEach(b=>b.onclick=()=>generateServiceHistoryPdf(b.dataset.qxHistPdf,b));
  body.querySelectorAll('[data-qx-hist-label]').forEach(b=>b.onclick=()=>{const g=serviceHistoryGroups.find(x=>x.folio===b.dataset.qxHistLabel);if(g)openLoanLabelModal(g,false)});
  body.querySelectorAll('[data-qx-hist-adjust]').forEach(b=>b.onclick=()=>openServiceLoanAdjust(b.dataset.qxHistAdjust));
  body.querySelectorAll('[data-qx-hist-finalize]').forEach(b=>b.onclick=()=>finalizeServiceLoan(b.dataset.qxHistFinalize,b));
}
