  if(!destino)return qAlert('Selecciona el servicio de destino.');if(!medico.nombre)return qAlert('Captura o selecciona el nombre del médico.');if(!paciente.nombre)return qAlert('Captura el nombre del paciente.');if(!serviceState.selectedKits.length)return qAlert('Agrega al menos un kit al servicio.');if(!items.length)return qAlert('Los kits seleccionados no tienen productos para surtir.');
